// Generated by scripts/gen-l10n.mjs (gdetail n2, id) — 不要手改;改翻譯請改 scripts/out/l10n/id/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["id"]=Object.assign(window.GRAMMAR_DETAIL_L10N["id"]||{},{"n2-8":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜からには」kurang lebih artinya <b>「karena sudah ～, ya harus ～」</b>. Di depan kamu taruh hal yang sudah diputuskan, sudah terjadi, dan tidak bisa diubah. Di belakang kamu bilang \"jadi aku pasti akan…\". Dalam bahasa Indonesia kita sering bilang \"Kalau memang mau dikerjakan, kerjakan sebaik-baiknya\". Dalam bahasa Jepang jadinya: <span class='gd-jp'>やるからには、一番を目指す。</span>（Karena sudah mau melakukannya, aku menargetkan juara satu）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Paling sering dipakai dengan kata kerja. Yang penting, apakah di depannya memakai bentuk 「た」 atau bentuk kamus. Artinya berbeda:<br><b>Hal yang sudah dilakukan</b>：bentuk た＋からには　<span class='gd-pair'><span class='gd-jp'>引き受けた</span> → <span class='gd-jp'>引き受けたからには</span></span>（karena sudah menerimanya）<br><b>Hal yang diputuskan untuk dilakukan, tapi belum dilakukan</b>：bentuk kamus＋からには　<span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するからには</span></span>（karena memang mau kuliah di luar negeri）<br><b>Kata benda, kata sifat-な</b>：di tengah perlu ditambah 「である」　<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロであるからには</span></span>（karena seorang profesional）</div><div class='gd-h'>Apa yang disambung di belakangnya</div><div class='gd-sec'>Setelah からには, selalu ada \"jadi, sikap apa yang seharusnya aku punya\". Tidak boleh hanya menyebut suatu kejadian. Ada empat pola yang paling umum:</div><div class='gd-sec'><span class='gd-tag'>Tekad</span>Aku pasti akan melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したからには、必ず守る。</span>（Karena sudah berjanji, aku pasti menepatinya）</div><div class='gd-sec'><span class='gd-tag'>Kewajiban</span>Sering berpasangan dengan 「なければならない」「べきだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に出るからには、毎日練習しなければならない。</span>（Karena ikut pertandingan, harus latihan setiap hari）</div><div class='gd-sec'><span class='gd-tag'>Meminta lawan bicara</span>Sering berpasangan dengan 「てください」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に住むからには、ゴミの出し方はちゃんと覚えてください。</span>（Karena tinggal di Jepang, tolong ingat baik-baik cara membuang sampah）</div><div class='gd-sec'><span class='gd-tag'>Dugaan yang wajar</span>Sering berpasangan dengan 「はずだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼がやると言ったからには、ちゃんとやるはずだ。</span>（Karena dia sendiri bilang akan melakukannya, seharusnya dia mengerjakannya dengan benar）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Kalimat-kalimat ini hampir menjadi ungkapan baku. Hafalkan saja satu kalimat utuh:</div><div class='gd-ex-line'>・<span class='gd-jp'>やるからには、本気でやろう。</span>（Karena mau melakukannya, ayo lakukan dengan serius）</div><div class='gd-ex-line'>・<span class='gd-jp'>こうなったからには、もうやるしかない。</span>（Setelah jadi begini, tidak ada pilihan selain nekat melakukannya）</div><div class='gd-ex-line'>・<span class='gd-jp'>自分で決めたからには、最後までがんばる。</span>（Karena aku sendiri yang memutuskan, aku akan berjuang sampai akhir）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di belakangnya tidak boleh hanya menyebut satu kejadian yang sudah terjadi.<br>×<span class='gd-jp'>日本に来たからには、寿司を食べた。</span><br>○<span class='gd-jp'>日本に来たからには、本場の寿司を食べたい。</span>（Karena sudah datang ke Jepang, aku ingin makan sushi yang asli）<br>・Kata benda tidak bisa langsung disambung: bukan プロからには, tetapi <span class='gd-jp'>プロであるからには</span>.<br>・Jangan sembarangan tertukar antara bentuk た dan bentuk kamus: <span class='gd-jp'>結婚したからには</span> artinya sudah menikah, sedangkan <span class='gd-jp'>結婚するからには</span> artinya sudah memutuskan untuk menikah.<br>・Pola ini membawa tekad \"aku akan menanggungnya\", jadi nuansanya berat. Kalau hanya menyebut alasan, misalnya \"hujan jadi bawa payung\", cukup pakai 「から」, tidak perlu からには.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>からこそ</b>（n2-9）＝<b>justru karena ～ makanya ～</b>, fokusnya menekankan bahwa \"alasannya memang ini\".<br><b>からには</b>＝<b>karena sudah ～, ya harus ～</b>, fokusnya pada \"apa yang harus kulakukan selanjutnya\".<br>Sama-sama bicara soal pekerjaan yang disukai:<br>・<span class='gd-jp'>好きな仕事を選んだからには、簡単にはやめない。</span>（Karena sudah memilih pekerjaan yang disukai, aku tidak akan berhenti begitu saja）<br>・<span class='gd-jp'>好きな仕事だからこそ、毎日がんばれる。</span>（Justru karena pekerjaan yang disukai, aku bisa berjuang setiap hari）</div><div class='gd-sec'><b>上は</b>（n2-32）＝artinya hampir sama dengan からには, tetapi lebih kaku dan lebih formal, banyak dipakai dalam tulisan atau situasi resmi. Selain itu, 「以上（は）」 yang sering terdengar juga artinya sangat dekat.<br>・<span class='gd-jp'>引き受けたからには、最後までやります。</span>（Karena sudah menerimanya, aku akan mengerjakannya sampai akhir: bisa dipakai dalam percakapan sehari-hari）<br>・<span class='gd-jp'>引き受けた上は、最後までやり遂げる所存です。</span>（Karena sudah menerimanya, saya bertekad menuntaskannya sampai akhir: situasi formal）</div><div class='gd-warn'>Tips menentukan: \"karena sudah ～, ya harus ～\" pakai からには; \"justru karena ～ makanya ～\" pakai からこそ; kalau sama-sama \"karena sudah\" tapi mau terdengar lebih formal, ganti ke 上は.</div>","n2-25":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜どころか」kurang lebih artinya <b>「mana mungkin ～, malah…」「jangankan ～, bahkan … pun …」</b>. Pertama kamu sebut A yang dikira semua orang benar, lalu kamu beri tahu: kenyataannya jauh dari A, dan sering kali <b>justru kebalikannya</b>. Misalnya kamu kira libur bisa istirahat, ternyata 「休息どころか、lebih capek daripada kerja」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja: bentuk kamus＋どころか　<span class='gd-pair'><span class='gd-jp'>やせる</span> → <span class='gd-jp'>やせるどころか</span></span><br>Kata sifat-い: disambung langsung　<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いどころか</span></span><br>Kata sifat-な, kata benda: disambung langsung, <b>jangan tambah だ</b>　<span class='gd-pair'><span class='gd-jp'>簡単</span> → <span class='gd-jp'>簡単どころか</span></span><span class='gd-pair'><span class='gd-jp'>旅行</span> → <span class='gd-jp'>旅行どころか</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Malah kebalikannya</span>A bukan hanya tidak terjadi, tapi malah bergerak ke arah sebaliknya. Di belakangnya sering muncul <span class='gd-jp'>逆に</span>、<span class='gd-jp'>かえって</span>、<span class='gd-jp'>もっと</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエットしているのに、やせるどころか太ってしまった。</span>（Padahal aku sedang diet, jangankan kurus, malah jadi gemuk）</div><div class='gd-ex-line'>・<span class='gd-jp'>薬を飲んだのに、よくなるどころか、もっと悪くなった。</span>（Sudah minum obat, bukannya membaik, malah makin parah）</div><div class='gd-sec'><span class='gd-tag'>Jangankan A, B pun tidak</span>A adalah hal yang lebih sulit, B adalah hal yang lebih dasar. B saja tidak bisa, apalagi A. Di belakangnya sering muncul 「も」「さえ」＋bentuk negatif.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、旅行どころか、週末に休むこともできない。</span>（Sibuk sekali, jangankan jalan-jalan, istirahat di akhir pekan pun tidak bisa）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は漢字どころか、ひらがなも読めない。</span>（Dia jangankan kanji, hiragana pun tidak bisa baca）</div><div class='gd-sec'><span class='gd-tag'>Bukan hanya A</span>Kenyataannya jauh lebih besar dari A, arahnya sama tapi jauh melampaui.</div><div class='gd-ex-line'>・<span class='gd-jp'>1万円どころか、5万円もかかった。</span>（Bukan cuma sepuluh ribu yen, ternyata habis lima puluh ribu yen）</div><div class='gd-sec'><span class='gd-tag'>それどころか</span>Ditaruh di awal kalimat untuk menanggapi ucapan lawan bicara: \"Mana ada, justru malah…\". Sangat sering dipakai dalam percakapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>「迷惑だった？」「それどころか、すごく助かったよ。」</span>（「Aku merepotkan ya?」「Mana ada, justru sangat membantu.」）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda dan kata sifat-な jangan tambah だ: bilang <span class='gd-jp'>簡単どころか</span>, bukan 簡単だどころか.<br>・Jangan terbalik urutan \"jangankan A, B pun\": taruh hal yang <b>lebih sulit</b> di A, dan hal yang <b>lebih dasar</b> di B. Yang benar 「漢字どころか、ひらがなも読めない」; kalau dibalik jadi 「ひらがなどころか、漢字も読めない」, artinya jadi aneh.<br>・Kalau A dan B sama-sama hal baik dan kamu hanya ingin \"menambahkan satu hal lagi\", どころか tidak bisa dipakai: \"Toko ini enak, dan murah juga\" tidak bisa dibilang 美味しいどころか安い. Pakailah <span class='gd-jp'>ばかりか</span> atau <span class='gd-jp'>だけでなく</span>.<br>・どころか membawa perasaan \"di luar dugaan, sampai melongo\", jadi cocok untuk hasil yang mengejutkan. Jangan dipaksakan untuk hal yang biasa-biasa saja.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal hari hujan:<br><b>ばかりか</b>＝A <b>benar terjadi</b>, lalu ditambah B: <span class='gd-jp'>雨ばかりか、雷まで鳴りだした。</span>（Bukan hanya hujan, petir pun mulai menyambar）<br><b>どころか</b>＝A <b>dibantah</b>, kenyataannya kebalikan: <span class='gd-jp'>雨がやむどころか、どんどん強くなっている。</span>（Hujan jangankan berhenti, malah makin deras）<br><b>どころじゃない</b>＝sekarang <b>sama sekali tidak ada tenaga</b> untuk A: <span class='gd-jp'>雨がひどくて、花見どころじゃない。</span>（Hujannya deras sekali, mana bisa menikmati bunga sakura）</div><div class='gd-warn'>Tips menentukan: \"Bukan hanya A, tapi juga B\" itu ばかりか; \"mana mungkin A, justru kebalikannya\" itu どころか; \"sekarang mana sempat/ada mood untuk A\" itu どころじゃない.</div>","n2-26":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ばかりか」「〜ばかりでなく」artinya <b>“tidak hanya ～, bahkan ～ juga”</b> atau <b>“bukan hanya ～, tetapi juga ～”</b>. Kamu menyebut satu hal dulu, lalu <b>menambah</b> satu hal lagi yang lebih dari itu. Dalam percakapan sehari-hari, orang lebih sering bilang 「〜だけじゃなくて」. ばかりか dan ばかりでなく terdengar lebih formal, jadi sering muncul di tulisan, berita, dan pidato.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menambah hal baik</span>Kelebihan datang satu demi satu.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は安いばかりでなく、味もいい。</span>（Toko ini tidak hanya murah, rasanya juga enak）</div><div class='gd-ex-line'>・<span class='gd-jp'>その歌は子どもばかりか、大人にも人気がある。</span>（Lagu itu tidak hanya disukai anak-anak, orang dewasa pun menyukainya）</div><div class='gd-sec'><span class='gd-tag'>Menambah hal buruk</span>Sudah buruk, eh ternyata ada yang lebih buruk lagi. ばかりか sangat sering dipakai untuk situasi “masa sih sampai ～” seperti ini, dengan nuansa kaget atau kesal.</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻したばかりか、資料も忘れてきた。</span>（Sudah terlambat, dokumennya juga lupa dibawa）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は謝らないばかりか、文句まで言ってきた。</span>（Dia bukan hanya tidak minta maaf, malah balik mengeluh）</div><div class='gd-sec'>Di bagian belakang kalimat, sering dipasang <b>「も」「まで」「さえ」</b> yang berarti “bahkan ～ pun”, sehingga kesan “menambah” terasa lebih jelas.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: langsung sambung　<span class='gd-pair'><span class='gd-jp'>遅刻した</span> → <span class='gd-jp'>遅刻したばかりか</span></span><br><b>Kata sifat-い</b>: langsung sambung　<span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いばかりか</span></span><br><b>Kata sifat-な</b>: tambahkan 「な」　<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利なばかりか</span></span><br><b>Kata benda</b>: langsung sambung, tanpa だ　<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもばかりか</span></span><br>（Dalam tulisan yang lebih formal, kata sifat-な dan kata benda juga bisa disambung dengan「である」, misalnya <span class='gd-jp'>学生であるばかりでなく</span>）<br>Cara menyambung ばかりでなく sama persis.</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は交通が便利なばかりか、家賃も安い。</span>（Kota ini tidak hanya punya transportasi yang praktis, sewanya juga murah）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata benda tidak boleh ada だ: yang benar <span class='gd-jp'>日本語ばかりか</span>, bukan 「日本語だばかりか」. Untuk kata sifat-な, jangan lupa な: <span class='gd-jp'>きれいなばかりか</span>.<br>・<b>Setelah ばかりか tidak boleh ada permintaan, perintah, atau tekad</b> seperti “tolong ～”, “lakukan ～”, “aku akan ～”. Dalam kasus itu, pakai ばかりでなく (atau だけでなく): <span class='gd-jp'>肉ばかりでなく、野菜も食べなさい。</span>（Jangan makan daging saja, sayur juga harus dimakan）Kalau bilang 「肉ばかりか、野菜も食べなさい」, kedengarannya tidak natural.<br>・Jangan tertukar dengan 「ばかり」 yang berdiri sendiri: <span class='gd-jp'>日本語ばかり勉強している</span> artinya “belajar bahasa Jepang <b>saja</b>”, sedangkan <span class='gd-jp'>日本語ばかりか英語も勉強している</span> artinya “<b>tidak hanya</b> bahasa Jepang, bahasa Inggris juga dipelajari”. Dengan tambahan か saja, artinya sudah sangat berbeda.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>どころか</b> juga sering diterjemahkan “tidak hanya ～”, tetapi cara pakainya berbeda. Kuncinya ada pada <b>apakah hal yang di depan itu benar atau tidak</b>.<br><b>ばかりか</b>: yang di depan benar, lalu yang di belakang menambahkan hal lain.<br><span class='gd-jp'>彼は英語ばかりか、フランス語も話せる。</span>（Dia tidak hanya bisa bahasa Inggris, bahasa Prancis juga bisa: bahasa Inggris bisa）<br><b>どころか</b>: hal yang di depan sama sekali tidak terjadi, bahkan jauh dari itu.<br><span class='gd-jp'>彼はフランス語どころか、英語も話せない。</span>（Jangankan bahasa Prancis, bahasa Inggris pun dia tidak bisa: bahasa Prancis tidak bisa）<br><span class='gd-jp'>やせるどころか、太ってしまった。</span>（Jangankan kurus, malah jadi gemuk）</div><div class='gd-sec'><b>のみならず</b> artinya hampir sama dengan ばかりか dan ばかりでなく, hanya saja lebih bergaya tulisan dan lebih kaku, biasanya muncul di tulisan atau situasi formal.</div><div class='gd-warn'>Trik cepat: kalau hal di depan “memang ada” lalu kamu menambah satu hal lagi, pakai ばかりか atau ばかりでなく. Kalau hal di depan “sama sekali tidak ada”, atau hasilnya justru berlawanan, pakai どころか. Kalau di belakangnya menyuruh orang melakukan sesuatu, pilih ばかりでなく.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Masih satu keluarga “tidak hanya ～”, kamu bisa lanjut ke <span class='gd-jp'>〜のみならず</span>、<span class='gd-jp'>〜はもちろん</span>、<span class='gd-jp'>〜上に</span>、<span class='gd-jp'>〜に限らず</span>, lalu bandingkan nuansa masing-masing.</div>","n2-35":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ざるを得ない」artinya <b>“terpaksa ～” atau “mau tidak mau harus ～”</b>. Sebenarnya hati kamu kurang mau, tetapi situasinya memang begitu dan <b>tidak ada pilihan lain</b>, jadi cuma bisa melakukannya. Rasanya seperti kita bilang “Mau bagaimana lagi, ya sudah, terpaksa berangkat juga”.</div><div class='gd-sec'>Kalau dipecah, lebih mudah diingat: <span class='gd-jp'>ざる</span> adalah bentuk “tidak” dalam bahasa Jepang klasik, <span class='gd-jp'>得ない</span> artinya “tidak bisa”. Digabung jadi “<b>tidak bisa tidak melakukan</b>”, jadi sama dengan “mau tidak mau harus”. <span class='gd-jp'>得ない</span> dibaca <b>えない</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Terdesak keadaan</span>Karena suatu alasan, kamu dipaksa melakukan hal yang sebenarnya kurang ingin kamu lakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>台風が来るので、旅行を中止せざるを得ない。</span>（Karena topan akan datang, terpaksa membatalkan perjalanan）</div><div class='gd-ex-line'>・<span class='gd-jp'>人が足りないので、休みの日も出勤せざるを得なかった。</span>（Karena kekurangan orang, hari libur pun terpaksa masuk kerja）</div><div class='gd-sec'><span class='gd-tag'>Terpaksa mengakui・terpaksa mengatakan</span>Sering dipakai bersama <span class='gd-jp'>認める</span> dan <span class='gd-jp'>言う</span>, artinya “sebenarnya tidak mau, tapi faktanya memang begitu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の実力は認めざるを得ない。</span>（Kemampuannya, mau tidak mau, harus kuakui）</div><div class='gd-ex-line'>・<span class='gd-jp'>残念ながら、この計画は失敗だったと言わざるを得ない。</span>（Sayangnya, harus dikatakan bahwa rencana ini gagal）</div><div class='gd-h'>Cara mengubah: lihat dulu golongan kata kerjanya</div><div class='gd-sec'>Caranya: ubah dulu ke bentuk ない, lalu <b>buang ない</b>, kemudian tambahkan ざるを得ない.</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span> → buang ない → <span class='gd-jp'>行かざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わない</span> → <span class='gd-jp'>言わざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>従う</span> → <span class='gd-jp'>従わない</span> → <span class='gd-jp'>従わざるを得ない</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>:<br><span class='gd-pair'><span class='gd-jp'>認める</span> → <span class='gd-jp'>認めない</span> → <span class='gd-jp'>認めざるを得ない</span></span><br><span class='gd-pair'><span class='gd-jp'>諦める</span> → <span class='gd-jp'>諦めざるを得ない</span></span></div><div class='gd-sec'><b>Golongan 3 (dua-duanya pengecualian, hafalkan saja)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せざるを得ない</span></span>（bukan しざる）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ざるを得ない</span>（こざるをえない）</span></div><div class='gd-sec'>Bentuk lampau adalah <span class='gd-jp'>得なかった</span>, dan untuk bentuk yang lebih sopan, <span class='gd-jp'>得ません</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>する</span> harus berubah jadi <b>せざる</b>; menulis 「しざるを得ない」 itu salah. Pola “kata benda＋する” seperti <span class='gd-jp'>中止する</span> dan <span class='gd-jp'>出勤する</span> juga sama: <span class='gd-jp'>中止せざるを得ない</span>.<br>・Kata kerja berakhiran う seperti <span class='gd-jp'>言う</span> dan <span class='gd-jp'>従う</span> berubah jadi <b>わ</b> di bentuk ない: <span class='gd-jp'>言わない</span>, jadi yang benar <span class='gd-jp'>言わざる</span>, bukan 「言あざる」.<br>・<span class='gd-jp'>得ない</span> dibaca <b>えない</b>, jangan dibaca とくない atau うない.<br>・Ini ungkapan yang cenderung formal dan bergaya tulisan, sering muncul di berita, laporan, dan situasi resmi. Kalau ngobrol dengan teman dan mau bilang “terpaksa”, biasanya lebih natural pakai ungkapan seperti <span class='gd-jp'>行くしかない</span>.<br>・Ungkapan ini punya nuansa “sebenarnya tidak mau”, jadi jangan dipakai untuk hal yang memang kamu sangat ingin lakukan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>なければならない</b> = <b>harus dilakukan</b> karena aturan atau logika, dan belum tentu membawa perasaan tertentu:<br><span class='gd-jp'>明日は会議だから、早く行かなければならない。</span>（Besok ada rapat, jadi harus berangkat lebih pagi）<br><b>ざるを得ない</b> = sebenarnya tidak mau, tetapi <b>keadaan memaksa sampai tidak ada pilihan</b>:<br><span class='gd-jp'>熱があるが、代わりの人がいないので、行かざるを得ない。</span>（Meskipun demam, tidak ada orang yang bisa menggantikan, jadi terpaksa berangkat）</div><div class='gd-sec'><b>ずにはいられない</b> (mirip sekali, sama-sama ada ず/ざる) = <b>tidak tertahankan, tidak bisa menahan diri</b>; perasaannya muncul sendiri dari dalam hati:<br><span class='gd-jp'>部長の冗談がおもしろくて、笑わずにはいられなかった。</span>（Lelucon kepala bagian itu lucu sekali, sampai tidak tahan tertawa）<br><span class='gd-jp'>部長の冗談はつまらなかったが、笑わざるを得なかった。</span>（Lelucon kepala bagian itu membosankan, tapi terpaksa ikut tertawa）</div><div class='gd-warn'>Trik cepat: kalau cuma “memang harus dilakukan”, pakai なければならない. Kalau “tidak mau tapi tidak ada pilihan”, pakai ざるを得ない. Kalau “tidak tahan”, pakai ずにはいられない.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Sering muncul bersama “karena sudah ～”: <span class='gd-jp'>上司の判断である以上、従わざるを得ない。</span>（Karena sudah merupakan keputusan atasan, mau tidak mau harus patuh）. Kamu bisa lanjut belajar ungkapan “karena sudah ～ maka ～” seperti <span class='gd-jp'>〜上は</span> dan <span class='gd-jp'>〜からには</span>.</div>","n2-37":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜かねる」mirip kalimat yang sering diucapkan customer service: <b>「Mohon maaf, untuk hal ini tidak bisa kami layani」</b>, atau frasa surat resmi: <b>「dengan berat hati tidak dapat kami penuhi」</b>. Secara harfiah artinya \"sebenarnya ingin melakukannya, tapi sulit\". Kenyataannya, ini adalah <b>penolakan yang sangat sopan</b>, atau cara menyatakan bahwa kamu merasa serba salah.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Penolakan sopan</span>Paling sering dipakai pelayan toko, customer service, dan perusahaan saat berbicara ke pihak luar. Kata \"tidak bisa\" jadi terdengar jauh lebih lembut.</div><div class='gd-ex-line'>・<span class='gd-jp'>返品はお受けいたしかねます。</span>（Mohon maaf, kami tidak dapat menerima pengembalian barang）</div><div class='gd-ex-line'>・<span class='gd-jp'>その件についてはお答えしかねます。</span>（Mohon maaf, soal itu tidak bisa saya jawab）</div><div class='gd-ex-line'>・<span class='gd-jp'>申し訳ございませんが、私ではわかりかねます。</span>（Mohon maaf, untuk hal ini saya kurang tahu）</div><div class='gd-sec'><span class='gd-tag'>Tidak bisa menerima di hati</span>Secara posisi atau perasaan, kamu tidak bisa mengiyakan.</div><div class='gd-ex-line'>・<span class='gd-jp'>その意見には賛成しかねます。</span>（Saya tidak bisa menyetujui pendapat itu）</div><div class='gd-sec'><span class='gd-tag'>Belum bisa memutuskan</span><span class='gd-jp'>決めかねる</span> adalah ungkapan tetap yang sangat umum, artinya \"ragu, tidak bisa memutuskan\".</div><div class='gd-ex-line'>・<span class='gd-jp'>どちらにするか決めかねている。</span>（Aku masih bingung mau pilih yang mana）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke bentuk ます, buang 「ます」, lalu tambahkan 「かねる」.<br><span class='gd-pair'><span class='gd-jp'>答えます</span> → <span class='gd-jp'>答えかねる</span></span><span class='gd-pair'><span class='gd-jp'>わかります</span> → <span class='gd-jp'>わかりかねる</span></span><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しかねる</span></span><br>Kalau mau lebih sopan lagi, ganti する dengan bentuk merendah いたす:<span class='gd-pair'><span class='gd-jp'>いたします</span> → <span class='gd-jp'>いたしかねます</span></span><br>Dalam praktiknya, yang paling sering kamu dengar adalah bentuk sopan <b>「〜かねます」</b>.</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・<b>Tidak dipakai untuk hal yang di luar kemampuan</b>. Untuk \"terlalu berat, tidak sanggup mengangkatnya\", katakan <span class='gd-jp'>重くて持てない</span>, bukan 重くて持ちかねる. かねる dipakai untuk \"sulit atau tidak mau melakukannya\" karena aturan, posisi, atau perasaan.<br>・<span class='gd-jp'>わかりかねます</span> tidak terlihat seperti kalimat negatif, tapi artinya \"saya tidak tahu / kurang paham\". Jangan sampai kamu mengira artinya \"saya tahu\".<br>・<b>かねます dan かねません artinya berlawanan</b>: <span class='gd-jp'>お答えしかねます</span> berarti \"tidak bisa menjawab\"; <span class='gd-jp'>起こりかねません</span> berarti \"sangat mungkin terjadi\". Bedanya hanya satu ん, jangan tertukar.<br>・Nadanya sangat formal. Dipakai ke teman akan terdengar aneh; di antara teman, cukup bilang <span class='gd-jp'>ちょっと無理</span>.<br>・Ada dua ungkapan khusus yang perlu dihafal terpisah: <span class='gd-jp'>見るに見かねて手伝った</span>（tidak tega melihatnya, lalu membantu）dan <span class='gd-jp'>お待ちかねの新商品</span>（produk baru yang sudah lama dinanti-nanti）. Keduanya bukan penolakan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama saat pelanggan minta pengembalian barang:<br><b>できない</b> = langsung bilang tidak bisa, lebih kaku: <span class='gd-jp'>返品はできません。</span>（Tidak bisa dikembalikan）<br><b>かねる</b> = menolak dengan sopan dan halus: <span class='gd-jp'>返品はお受けいたしかねます。</span>（Mohon maaf, pengembalian tidak dapat kami proses）<br><b>がたい</b> bukan untuk menolak orang, tapi menggambarkan sesuatu yang \"sulit untuk ~\": <span class='gd-jp'>信じがたい話だ。</span>（Cerita yang sulit dipercaya）<br><b>かねない</b> = khawatir hal buruk bisa terjadi: <span class='gd-jp'>このままでは事故になりかねない。</span>（Kalau begini terus, bisa-bisa terjadi kecelakaan）</div><div class='gd-warn'>Trik menentukan: menolak permintaan orang dengan sopan → かねる; sesuatu sulit dipercaya atau sulit diterima → がたい; khawatir \"jangan-jangan bisa ~\" → かねない.</div><div class='gd-h'>Setelah ini belajar apa</div><div class='gd-sec'>Pelajaran berikutnya adalah 「〜かねない」. Bentuknya hampir sama, tapi artinya berlawanan, jadi pas untuk diingat bersama.</div>","n2-54":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜につれて」sama dengan <b>\"seiring ~, (jadi) makin ~\"</b> dalam bahasa Indonesia. Hal di depan berubah pelan-pelan, dan hal di belakang ikut berubah pelan-pelan. Rasanya seperti \"cuaca makin dingin, makin banyak orang yang minum minuman hangat\", yaitu dua hal yang berubah bersamaan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Verba</span>Bentuk kamus (bentuk asli yang kamu temukan di kamus) langsung ditambah につれて.<br><span class='gd-pair'><span class='gd-jp'>時間が経つ</span> → <span class='gd-jp'>時間が経つにつれて</span></span>（seiring berjalannya waktu）<br><span class='gd-pair'><span class='gd-jp'>慣れる</span> → <span class='gd-jp'>慣れるにつれて</span></span>（seiring terbiasa）</div><div class='gd-sec'><span class='gd-tag'>Nomina</span>Langsung ditambah につれて, tapi nomina itu sendiri harus mengandung makna \"perubahan\", misalnya <span class='gd-jp'>成長</span>, <span class='gd-jp'>進化</span>, <span class='gd-jp'>変化</span>, <span class='gd-jp'>高齢化</span>.<br><span class='gd-pair'><span class='gd-jp'>成長</span> → <span class='gd-jp'>成長につれて</span></span>（seiring pertumbuhan）</div><div class='gd-sec'>Dalam tulisan, sering juga dipakai bentuk yang lebih pendek 「<span class='gd-jp'>につれ</span>」. Artinya sama.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Saat kedua hal itu berubah <b>sedikit demi sedikit</b>. Di paruh kalimat belakang sering dipasangkan 「<span class='gd-jp'>〜てきた</span>」「<span class='gd-jp'>〜ていく</span>」「<span class='gd-jp'>〜くなる</span>」 untuk menonjolkan kesan \"perlahan-lahan\".</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の生活に慣れるにつれて、毎日が楽しくなってきた。</span>（Seiring terbiasa dengan kehidupan di Jepang, setiap hari terasa makin menyenangkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>年を取るにつれて、体力が落ちてきた。</span>（Seiring bertambahnya usia, stamina jadi menurun）</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもの成長につれて、家が狭く感じるようになった。</span>（Seiring anak tumbuh besar, rumah mulai terasa sempit）</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・<b>Tidak bisa dipakai untuk hal yang selesai sekali jadi</b>. \"Lulus\", \"pindah rumah\", \"menikah\" terjadi sekali saja, jadi tidak bisa bilang <span class='gd-jp'>卒業するにつれて</span>. Hal di depan harus perubahan yang berlangsung bertahap.<br>・<b>Kalimat belakang tidak boleh berupa \"aku akan ~\" atau \"tolong ~\"</b>. Bagian belakang harus berupa perubahan yang terjadi dengan sendirinya, tidak bisa berisi niat sendiri atau perintah ke orang lain. Kalimat seperti \"seiring bahasa Jepangmu membaik, ayo kita lebih banyak ngobrol\" tidak bisa memakai につれて.<br>・<b>Nomina tidak boleh sembarangan</b>. <span class='gd-jp'>雨につれて</span> salah, karena \"hujan\" sendiri bukan perubahan; yang benar <span class='gd-jp'>雨が強くなるにつれて</span>（seiring hujan makin deras）.<br>・Kata \"seiring\" atau \"dengan\" dalam bahasa Indonesia dipakai cukup luas, tapi につれて hanya untuk \"kedua sisi berubah bertahap secara bersamaan\". Jangan langsung menerjemahkan setiap \"seiring\" menjadi につれて.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>に伴って</b>: maknanya sangat dekat, tapi lebih formal dan sering dipakai di berita dan pengumuman; di depannya juga boleh ada <b>hal yang terjadi sekali saja</b>.<br>・<span class='gd-jp'>人口が増えるにつれて、ゴミの問題が深刻になった。</span>（Seiring bertambahnya penduduk, masalah sampah jadi makin serius）<br>・<span class='gd-jp'>人口が増えるに伴って、ゴミの問題が深刻になった。</span>（Sama seperti di atas, nadanya lebih formal）<br>Kedua kalimat itu boleh. Tapi untuk hal sekali jadi seperti pindah rumah:<br>・<span class='gd-jp'>引っ越しに伴って、住所が変わります。</span>（Karena pindah rumah, alamat akan berubah）<br>Di sini につれて tidak bisa dipakai.</div><div class='gd-sec'><b>に応じて</b>: \"berbeda sesuai dengan ~\", fokusnya pada hubungan kesesuaian, bukan perubahan seiring waktu.<br>・<span class='gd-jp'>年齢に応じて、料金が違います。</span>（Tarif berbeda sesuai usia）<br>Kalimat ini berarti orang dengan usia berbeda membayar harga berbeda, bukan satu orang yang makin besar lalu harganya ikut berubah, jadi につれて tidak bisa dipakai.</div><div class='gd-warn'>Trik menentukan: kalau bisa diucapkan \"seiring ~, perlahan jadi ~\", pakai につれて; kalau lebih formal atau di depannya peristiwa sekali jadi, pakai に伴って; kalau artinya \"berbeda sesuai ~\", pakai に応じて.</div>","n2-2":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「bentuk kamus＋ばかりだ」artinya kira-kira <b>「makin lama makin ～」「terus bertambah parah」「cuma bisa makin ～」</b>. Keadaan terus bergerak ke satu arah tanpa tanda-tanda membaik atau berbalik. Orang yang mengatakannya biasanya merasa pasrah atau khawatir.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Makin lama makin buruk</span>Ini pemakaian yang paling umum. Kamu akan sering mendengarnya saat orang mengeluh soal harga, ekonomi, kesehatan, atau beban kerja.</div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がるばかりだ。</span>(Harga-harga naik terus, tidak pernah turun)</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなるばかりだった。</span>(Penyakit ayahku makin parah dari hari ke hari)</div><div class='gd-sec'><span class='gd-tag'>Di tengah kalimat</span>Ubah jadi「ばかりで」, lalu sambung dengan hal lain yang membuat makin pasrah.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は増えるばかりで、給料は全然上がらない。</span>(Pekerjaan terus bertambah, tapi gajinya sama sekali tidak naik)</div><div class='gd-sec'><span class='gd-tag'>Kadang untuk arah yang baik</span>Bisa, tapi jarang. Biasanya dipakai untuk menggambarkan tren secara objektif.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店の人気は高まるばかりだ。</span>(Toko ini makin lama makin populer)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk kamus (bentuk dasar yang kamu temukan di kamus)＋ばかりだ. Di depannya harus ada <b>kata kerja yang menyatakan perubahan</b>, seperti <span class='gd-jp'>増える</span>, <span class='gd-jp'>減る</span>, <span class='gd-jp'>上がる</span>, <span class='gd-jp'>広がる</span>, <span class='gd-jp'>悪化する</span>.<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えるばかりだ</span></span><br>Kata sifat harus diubah dulu dengan「なる」menjadi 「jadi ～」, baru disambung dengan ばかりだ:<br><span class='gd-pair'><span class='gd-jp'>悪い</span> → <span class='gd-jp'>悪くなる</span> → <span class='gd-jp'>悪くなるばかりだ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便になる</span> → <span class='gd-jp'>不便になるばかりだ</span></span><br>Untuk hal yang sudah lewat, pakai <b>ばかりだった</b>.</div><div class='gd-h'>Yang sering bikin salah</div><div class='gd-warn'>・Kalau di depannya bukan kata kerja perubahan, artinya bergeser jadi 「hanya terus ～」: <span class='gd-jp'>彼女はただ泣くばかりだった。</span>(Dia hanya menangis terus) Ini bukan 「makin lama makin」.<br>・「<span class='gd-jp'>あとは</span>～ばかりだ」artinya 「tinggal ～ saja」: <span class='gd-jp'>準備はできた。あとは出発するばかりだ。</span>(Persiapan sudah selesai, tinggal berangkat)<br>・Kata benda＋ばかり artinya 「melulu ～」: <span class='gd-jp'>甘い物ばかり食べている。</span>(Makan yang manis-manis melulu) Ini lain urusan dengan 「makin lama makin」 di sini.<br>・Pola ini kurang cocok untuk membicarakan kemajuan diri sendiri. Untuk bilang 「bahasa Jepangku makin bagus」, lebih natural pakai <span class='gd-jp'>日本語がどんどん上手になっている</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>Sama-sama ばかり, tapi bentuk di depannya beda, artinya juga beda total:</b></div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりだ。</span>(Aku baru saja datang ke Jepang: bentuk た＋ばかり＝baru saja ～)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日ゲームをしてばかりいる。</span>(Tiap hari main game melulu: bentuk て＋ばかりいる＝terus-terusan ～)</div><div class='gd-ex-line'>・<span class='gd-jp'>帰国してから、日本語は忘れるばかりだ。</span>(Sejak pulang ke negara asal, bahasa Jepangku cuma makin lupa: bentuk kamus＋ばかりだ＝makin lama makin ～)</div><div class='gd-sec'><b>Bandingkan dengan「～つつある」:</b> keduanya membicarakan perubahan, tapi nuansanya beda.</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は回復しつつある。</span>(Ekonomi perlahan sedang pulih)</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は悪くなるばかりだ。</span>(Ekonomi cuma makin lama makin buruk)</div><div class='gd-sec'>つつある hanya menggambarkan dengan tenang bahwa 「perubahan sedang berlangsung」. Gayanya lebih tulisan dan bisa untuk hal baik maupun buruk. ばかりだ menekankan 「tidak bisa berhenti, cuma bergerak ke satu arah」, dengan nuansa pasrah.<br>Ada juga <span class='gd-jp'>～一方だ</span>, yang artinya hampir sama dengan ばかりだ dan sering bisa saling menggantikan: <span class='gd-jp'>人口は減る一方だ。</span>(Jumlah penduduk terus berkurang, tidak pernah bertambah)</div><div class='gd-warn'>Trik cepat: lihat apa yang ada sebelum ばかり. Bentuk た artinya 「baru saja ～」, bentuk て artinya 「melulu ～」, dan bentuk kamus dengan kata kerja perubahan artinya 「makin lama makin ～」.</div>","n2-5":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜たとたん（に）」artinya <b>「begitu baru saja ～, langsung tiba-tiba ～」</b>. Misalnya begitu kamu membuka pintu, kucing langsung melesat keluar; begitu berdiri, kepala langsung pusing. Tindakan pertama baru saja selesai, lalu <b>muncul hal yang tidak kamu duga</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk た (bentuk lampau「～た」), lalu tambahkan とたん. 「に」boleh dipakai boleh tidak, artinya sama.<br><span class='gd-pair'><span class='gd-jp'>開ける</span> → <span class='gd-jp'>開けたとたん</span></span><span class='gd-pair'><span class='gd-jp'>出る</span> → <span class='gd-jp'>出たとたん</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだとたんに</span></span><br>Di depannya biasanya tindakan yang selesai seketika, seperti membuka pintu, keluar rumah, berdiri, atau melihat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kejadian mendadak di luar dirimu</span>Orang lain, hewan, atau cuaca tiba-tiba bereaksi atau berubah.</div><div class='gd-ex-line'>・<span class='gd-jp'>家を出たとたん、雨が降り出した。</span>(Begitu keluar rumah, hujan langsung turun)</div><div class='gd-ex-line'>・<span class='gd-jp'>窓を開けたとたん、虫が入ってきた。</span>(Begitu jendela dibuka, serangga langsung masuk)</div><div class='gd-sec'><span class='gd-tag'>Reaksi tubuh dan perasaan yang tak terkendali</span>Reaksi pada dirimu sendiri juga boleh, asalkan bukan sesuatu yang kamu sengaja lakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>立ち上がったとたん、めまいがした。</span>(Begitu berdiri, kepalaku langsung pusing)</div><div class='gd-ex-line'>・<span class='gd-jp'>母の声を聞いたとたん、涙が出てきた。</span>(Begitu mendengar suara ibu, air mataku langsung mengalir)</div><div class='gd-h'>Yang sering bikin salah</div><div class='gd-warn'>・Di depannya harus bentuk た: bilang <span class='gd-jp'>開けたとたん</span>, jangan 「開けるとたん」.<br>・Yang muncul di belakang adalah hal yang <b>sudah terjadi dan di luar dugaan</b>, jadi akhir kalimatnya biasanya bentuk lampau.<br>・Di belakangnya tidak boleh ada kalimat berisi kemauan, ajakan, atau perintah, seperti 「aku akan ～」「ayo ～」「tolong ～」. 「家に着いたとたん、電話してください」salah.<br>・Di belakangnya juga tidak boleh ada <b>tindakan yang sengaja kamu lakukan</b>. 「家に帰ったとたん、シャワーを浴びた」terdengar tidak natural, karena mandi itu keputusanmu sendiri. Untuk itu pakai <span class='gd-jp'>家に帰ってすぐ、シャワーを浴びた。</span>(Begitu pulang, aku langsung mandi)</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>〜次第</b> juga sering diterjemahkan 「begitu ～, langsung ～」, tetapi pemakaiannya justru berlawanan. Lihat situasi yang sama:<br><span class='gd-jp'>駅に着いたとたん、電車が行ってしまった。</span>(Begitu aku sampai di stasiun, keretanya langsung berangkat)<br>→ Sudah terjadi dan tidak terduga, pakai とたん.<br><span class='gd-jp'>駅に着き次第、連絡します。</span>(Begitu sampai di stasiun, aku akan menghubungimu)<br>→ Belum terjadi dan itu hal yang <b>akan kamu lakukan</b>, pakai 次第.<br>次第 disambung dengan bentuk ます tanpa ます (<span class='gd-pair'><span class='gd-jp'>着きます</span> → <span class='gd-jp'>着き次第</span></span>), dan sering dipakai dalam urusan kerja atau situasi formal.</div><div class='gd-warn'>Trik cepat: kalau di belakangnya 「hal yang tiba-tiba muncul dan tak bisa kukendalikan」, pakai とたん. Kalau 「hal yang akan kulakukan selanjutnya」, pakai 次第.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>「とたん」juga bisa ditaruh di awal kalimat dalam bentuk「その途端」, artinya 「tepat pada saat itu」:<br><span class='gd-jp'>ドアを開けた。その途端、猫が飛び出した。</span>(Aku membuka pintu. Tepat saat itu, kucing melesat keluar)</div>","n2-6":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜次第」artinya <b>“begitu ～, langsung ～”</b>. Seperti yang sering diucapkan customer service: “Begitu barangnya tiba, langsung kami kabari” atau “Begitu hasilnya keluar, langsung kami sampaikan”. Ini pola “begitu ～ langsung” yang <b>formal dan agak berkesan bisnis</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: ubah dulu ke bentuk ます, buang ます, lalu langsung sambung 次第.<br><span class='gd-pair'><span class='gd-jp'>届きます</span> → buang ます → <span class='gd-jp'>届き次第</span></span><br><span class='gd-pair'><span class='gd-jp'>終わります</span> → <span class='gd-jp'>終わり次第</span></span><span class='gd-pair'><span class='gd-jp'>わかります</span> → <span class='gd-jp'>わかり次第</span></span><span class='gd-pair'><span class='gd-jp'>見つけます</span> → <span class='gd-jp'>見つけ次第</span></span></div><div class='gd-sec'><b>Kata benda aksi yang bisa ditambah する</b> (seperti <span class='gd-jp'>到着する</span>, <span class='gd-jp'>決定する</span>): biasanya する dibuang, lalu kata bendanya langsung disambung 次第.<br><span class='gd-pair'><span class='gd-jp'>到着する</span> → <span class='gd-jp'>到着次第</span></span><span class='gd-pair'><span class='gd-jp'>決定する</span> → <span class='gd-jp'>決定次第</span></span><br>(Kamu juga akan menemukan <span class='gd-jp'>到着し次第</span>, artinya sama saja.)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Aku akan langsung bertindak</span>Bagian depan adalah hal yang belum terjadi tapi sedang ditunggu, dan bagian belakang adalah hal yang akan dilakukan si pembicara.</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物が届き次第、ご連絡いたします。</span>(Begitu paketnya tiba, kami akan menghubungi Anda)</div><div class='gd-ex-line'>・<span class='gd-jp'>詳しいことがわかり次第、お知らせします。</span>(Begitu detailnya sudah jelas, kami akan memberi tahu Anda)</div><div class='gd-sec'><span class='gd-tag'>Meminta lawan bicara langsung bertindak</span>Bagian belakang juga bisa berupa permintaan atau instruksi.</div><div class='gd-ex-line'>・<span class='gd-jp'>到着次第、お電話ください。</span>(Begitu sampai, tolong telepon saya)</div><div class='gd-ex-line'>・<span class='gd-jp'>準備ができ次第、始めてください。</span>(Begitu sudah siap, silakan mulai)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>Tidak bisa untuk hal yang sudah terjadi</b>: kalimat seperti “begitu sampai stasiun, hujan turun” tidak bisa pakai 次第. Setelah 次第 harus ada hal yang “akan dilakukan selanjutnya”, bukan bentuk lampau.<br>・Bagian belakang harus berupa hal yang <b>bisa diputuskan oleh orang</b> (menghubungi, berangkat, meminta lawan bicara melakukan sesuatu). Hasil di luar kendali seperti “hujan turun” atau “kaget” tidak bisa dipasang.<br>・Tidak bisa disambung dengan bentuk kamus: yang benar <span class='gd-jp'>届き次第</span>, bukan 届く次第.<br>・Nuansanya sangat formal, jadi kalau dipakai ke teman akan terdengar kaku. Antarteman cukup bilang <span class='gd-jp'>着いたらすぐ連絡するね</span> (nanti begitu sampai langsung kukabari ya).</div><div class='gd-h'>Arti lain: tergantung ～</div><div class='gd-sec'><span class='gd-tag'>Kata benda＋次第だ／次第で</span>「次第」punya satu pemakaian umum lagi, yaitu “tergantung ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>成功するかどうかは、君の努力次第だ。</span>(Berhasil atau tidak, tergantung usahamu)</div><div class='gd-ex-line'>・<span class='gd-jp'>天気次第で、予定が変わるかもしれません。</span>(Tergantung cuacanya, rencana mungkin berubah)</div><div class='gd-sec'>Ini hal yang berbeda dari “begitu ～ langsung” di atas. Kalau di depannya <b>kata benda biasa</b> (usaha, cuaca, uang, dan sebagainya), biasanya dipakai <b>次第だ／次第で</b> dengan arti “tergantung”. Kalau di depannya <b>kata benda aksi yang bisa ditambah する</b> seperti <span class='gd-jp'>到着</span> atau <span class='gd-jp'>決定</span>, dan di belakangnya ada hal yang akan dilakukan, artinya “begitu ～ langsung”.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama “begitu sampai rumah, ～”:<br><b>次第</b> = belum terjadi, <b>nanti saat itu tiba aku akan langsung melakukannya</b>: <span class='gd-jp'>家に着き次第、電話します。</span> (Begitu sampai rumah, aku langsung telepon kamu)<br><b>たとたん</b> = sudah terjadi, <b>pada saat itu tiba-tiba muncul hal tak terduga</b>: <span class='gd-jp'>家に着いたとたん、雨が降り出した。</span> (Begitu sampai rumah, tiba-tiba hujan turun)</div><div class='gd-warn'>Trik cepat: kalau “belum terjadi, dan begitu siap aku langsung bertindak”, pakai 次第. Kalau “sudah terjadi, dan seketika ada kejadian tak terduga”, pakai たとたん.</div>","n2-11":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ものの」artinya <b>“memang sudah ～, tapi…”</b>. Seperti “Tiketnya sih sudah dibeli, tapi akhirnya tidak jadi pergi”. Hal di bagian depan itu benar dan kamu akui, tapi perkembangan setelahnya tidak sesuai dugaan. Sering ada nuansa “yah, ujungnya nggak terlaksana”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sudah dilakukan tapi tidak berlanjut</span>Ini pemakaian yang paling umum. Kamu sudah melakukan sesuatu, tapi bagian belakang tidak berjalan seperti yang diharapkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>チケットを買ったものの、結局行けなかった。</span>(Tiketnya sih sudah dibeli, tapi akhirnya tetap tidak bisa pergi)</div><div class='gd-ex-line'>・<span class='gd-jp'>ジムに入会したものの、忙しくて一度しか行っていない。</span>(Memang sudah daftar gym, tapi karena sibuk baru sekali datang)</div><div class='gd-ex-line'>・<span class='gd-jp'>やると言ったものの、正直自信がない。</span>(Memang aku bilang akan melakukannya, tapi jujur aku nggak begitu yakin)</div><div class='gd-sec'><span class='gd-tag'>Ada kesenjangan antara depan dan belakang</span>Ciri di bagian depan membuat orang membayangkan suatu hasil, tapi bagian belakang ternyata tidak begitu. Bagian belakang tidak selalu hal buruk.</div><div class='gd-ex-line'>・<span class='gd-jp'>このアパートは駅から遠いものの、家賃が安い。</span>(Apartemen ini memang jauh dari stasiun, tapi sewanya murah)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat い</b>: sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>買った</span> → <span class='gd-jp'>買ったものの</span></span><span class='gd-pair'><span class='gd-jp'>遠い</span> → <span class='gd-jp'>遠いものの</span></span><br><b>Kata sifat な</b>: ganti「だ」dengan「な」, atau ganti dengan「である」.<br><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単なものの</span></span><span class='gd-pair'><span class='gd-jp'>簡単だ</span> → <span class='gd-jp'>簡単であるものの</span></span><br><b>Kata benda</b>: ganti「だ」dengan「である」.<br><span class='gd-pair'><span class='gd-jp'>学生だ</span> → <span class='gd-jp'>学生であるものの</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>とはいうものの</span>“Memang benar begitu, tapi…”. Bisa ditaruh di akhir kalimat, atau berdiri sendiri di awal kalimat.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に十年住んでいるとはいうものの、敬語はまだ苦手だ。</span>(Meski sudah sepuluh tahun tinggal di Jepang, aku masih kurang pandai bahasa sopan)</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエット中だ。とはいうものの、甘いものはやめられない。</span>(Aku sedang diet. Tapi ya begitulah, makanan manis tetap tidak bisa kutinggalkan)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda dan kata sifat な tidak bisa langsung disambung dengan「だ」: bukan <span class='gd-jp'>静かだものの</span>, tapi <span class='gd-jp'>静かなものの</span>; untuk kata benda pakai <span class='gd-jp'>学生であるものの</span>.<br>・Bagian belakang <b>tidak bisa berisi niat sendiri, perintah, atau permintaan</b>. Tidak bisa bilang <span class='gd-jp'>高いものの、買おう</span> atau <span class='gd-jp'>高いものの、買ってください</span>. Dalam kasus ini pakai「けど」: <span class='gd-jp'>高いけど、買おう</span>.<br>・Bagian depan harus berupa hal yang <b>sudah menjadi fakta</b>. Hal yang belum terjadi atau cuma pengandaian tidak bisa dipakai.<br>・Nuansanya cenderung formal, sering muncul di tulisan, berita, dan situasi resmi. Saat ngobrol dengan teman, <span class='gd-jp'>買ったけど、行けなかった</span> terdengar lebih natural.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ものの</b> = “memang sudah ～, tapi…”, intinya <b>mengakui bagian depan, tapi hasilnya ada kesenjangan</b>, sering dengan nuansa menyesal:<br><span class='gd-jp'>チケットを買ったものの、行けなかった。</span> (Tiketnya sih sudah dibeli, tapi tidak bisa pergi)<br><b>にもかかわらず</b> = “padahal ～, tetapi ～”, intinya <b>kontras antara depan dan belakang sangat besar</b>, sering dengan nuansa heran atau tidak puas, dan sering dipakai untuk membicarakan orang lain:<br><span class='gd-jp'>チケットを買ったにもかかわらず、彼は来なかった。</span> (Padahal sudah beli tiket, dia malah tidak datang)<br><b>ものなら</b> hanya mirip bentuknya, artinya sama sekali berbeda, yaitu “kalau bisa ～”:<br><span class='gd-jp'>行けるものなら、行きたかった。</span> (Kalau bisa pergi, aku ingin sekali pergi)</div><div class='gd-warn'>Trik cepat: kalau mau bilang “memang sudah ～, tapi…” pakai ものの. Kalau mau bilang “padahal ～, tapi ～” pakai にもかかわらず. Kalau melihat arti “kalau bisa ～”, itu ものなら, bukan pertentangan.</div><div class='gd-h'>Setelah ini, lanjut pelajari</div><div class='gd-sec'>Yang artinya mirip, yaitu “walaupun”, masih ada <span class='gd-jp'>とはいえ</span>, <span class='gd-jp'>つつも</span>, dan <span class='gd-jp'>ながらも</span>. Coba bandingkan semuanya sekaligus.</div>","n2-15":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜にしても」setara dengan <b>「biarpun ～, tetap ～」</b>. Kamu mengalah dulu dan mengakui alasan lawan bicara (oke, biarpun kamu sibuk), tapi kesimpulannya tidak berubah (setidaknya kabari dulu dong). Nadanya sering berupa keluhan atau kritik: “tetap saja itu tidak masuk akal”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat-い</b>: sambung langsung dengan bentuk biasa.<br><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいにしても</span></span><span class='gd-pair'><span class='gd-jp'>知らなかった</span> → <span class='gd-jp'>知らなかったにしても</span></span><br><b>Kata benda, kata sifat-な</b>: untuk bentuk sekarang, <b>jangan tambahkan だ</b>, sambung langsung. Untuk bentuk lampau pakai だった.<br><span class='gd-pair'><span class='gd-jp'>冗談</span> → <span class='gd-jp'>冗談にしても</span></span><span class='gd-pair'><span class='gd-jp'>大変</span> → <span class='gd-jp'>大変にしても</span></span><span class='gd-pair'><span class='gd-jp'>冗談だった</span> → <span class='gd-jp'>冗談だったにしても</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Biarpun ～ tetap</span>Mengalah dulu, lalu di belakang menyampaikan pendapat atau rasa tidak puas. Di depannya sering ditambah 「いくら」 (sebanyak apa pun).</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら忙しいにしても、返事ぐらいはしてほしい。</span>(Sesibuk apa pun, setidaknya balas dong.)</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にしても、言っていいことと悪いことがある。</span>(Biarpun cuma bercanda, ada hal yang boleh dan tidak boleh dikatakan.)</div><div class='gd-sec'><span class='gd-tag'>Apa pun ～ tetap</span>Di depannya ditaruh kata tanya seperti 「何、どこ、誰」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何をするにしても、健康が一番だ。</span>(Apa pun yang kamu lakukan, kesehatan yang paling penting.)</div><div class='gd-sec'><span class='gd-tag'>AにしてもBにしても</span>Entah A maupun B, hasilnya sama saja. A dan B biasanya hal yang sejenis, atau dua pilihan yang berlawanan.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにしても行かないにしても、早めに連絡してください。</span>(Pergi atau tidak, tolong kabari aku lebih awal.)</div><div class='gd-ex-line'>・<span class='gd-jp'>電車にしてもバスにしても、朝は混む。</span>(Baik kereta maupun bus, pagi hari selalu ramai.)</div><div class='gd-sec'><span class='gd-tag'>それにしても</span>Sudah menjadi satu kata tetap yang artinya “biarpun begitu” atau “ngomong-ngomong”. Sangat sering dipakai saat mengobrol.</div><div class='gd-ex-line'>・<span class='gd-jp'>「バスが遅れたんだって。」「それにしても遅すぎるよ。」</span>(“Katanya busnya terlambat.” “Biarpun begitu, ini terlalu lama, tahu.”)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Setelah kata benda jangan tambahkan だ: yang benar <span class='gd-jp'>冗談にしても</span>, tidak boleh 「冗談だにしても」.<br>・Bagian belakang kalimat biasanya berisi <b>pendapatmu</b>: kritik, ketidakpuasan, saran, atau penilaian. Sering dipasangkan dengan 「はずだ」「べきだ」「〜てほしい」「〜ない」.<br>・Kata “biarpun” dalam bahasa Indonesia bisa terdengar netral, tapi 「にしても」 sering membawa nuansa “aku mengerti, tapi tetap tidak bisa”. Kalau diucapkan langsung kepada orang yang lebih tua, bisa terdengar seperti menyalahkan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にしては</b> = “untuk ukuran ～, kok ～”, hasilnya <b>berbeda dari perkiraan</b>:<br><span class='gd-jp'>初めてにしては上手だね。</span>(Untuk ukuran yang pertama kali, hebat juga ya.)<br><b>にしても</b> = “biarpun ～, tetap ～”, alasannya <b>tidak bisa dijadikan dalih</b>:<br><span class='gd-jp'>初めてにしても、これはひどすぎる。</span>(Biarpun baru pertama kali, ini terlalu parah.)</div><div class='gd-sec'><b>にしろ・にせよ</b>: arti dan cara pakainya hampir sama dengan にしても, hanya lebih formal. <b>にしても</b> paling lisan, sedangkan <b>にせよ</b> condong ke bahasa tulis dan situasi formal.<br><span class='gd-jp'>いずれにしても、明日また連絡します。</span>／<span class='gd-jp'>いずれにせよ、明日また連絡します。</span>(Bagaimanapun, besok aku hubungi lagi.)</div><div class='gd-warn'>Tips menentukan: kalau mau bilang “biarpun ～ tetap”, pakai にしても. Kalau mau bilang “untuk ukuran ～, kok ～”, pakai にしては. Bedanya cuma satu huruf, tapi artinya jauh berbeda.</div><div class='gd-h'>Bisa lanjut belajar setelah ini</div><div class='gd-sec'>Padanan yang lebih formal: <span class='gd-jp'>〜にしろ・〜にせよ</span>.</div>","n2-18":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ものなら」punya dua arti, dan kamu bisa membedakannya dari <b>bentuk kata kerja di depannya</b>:<br>・Kalau di depannya <b>bentuk potensial</b> (<span class='gd-jp'>行ける</span>、<span class='gd-jp'>戻れる</span>): “<b>andai bisa ～</b> (tapi sulit)”. Seperti saat kamu menghela napas, “Andai bisa mengulang sekali lagi…”.<br>・Kalau di depannya <b>bentuk volisional</b> (〜よう、〜おう): “<b>kalau sampai ～, gawat</b>”. Seperti saat memperingatkan orang, “Coba saja kalau berani telat semenit.”</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Pemakaian ①: bentuk potensial + ものなら</b> (bentuk potensial adalah bentuk “bisa ～”)<br><span class='gd-pair'><span class='gd-jp'>戻る</span> → <span class='gd-jp'>戻れるものなら</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられるものなら</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できるものなら</span></span></div><div class='gd-sec'><b>Pemakaian ②: bentuk volisional + ものなら</b> (bentuk volisional adalah bentuk 「〜よう／〜おう」, makanya sering muncul 「〜ようものなら」)<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言おうものなら</span></span><span class='gd-pair'><span class='gd-jp'>遅れる</span> → <span class='gd-jp'>遅れようものなら</span></span><span class='gd-pair'><span class='gd-jp'>失敗する</span> → <span class='gd-jp'>失敗しようものなら</span></span></div><div class='gd-sec'>Dalam percakapan, ものなら sering diucapkan jadi <b>もんなら</b>: <span class='gd-jp'>戻れるもんなら戻りたいよ。</span>(Kalau bisa kembali, aku juga mau kembali.)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Harapan sambil menghela napas</span>Pemakaian ①. Kamu tahu itu sulit, hampir mustahil, tapi tetap saja bilang “andai bisa…”. Di belakangnya biasanya ada ungkapan keinginan seperti 「〜たい」「〜てあげたい」.</div><div class='gd-ex-line'>・<span class='gd-jp'>戻れるものなら、高校時代に戻りたい。</span>(Andai bisa kembali, aku ingin kembali ke masa SMA.)</div><div class='gd-ex-line'>・<span class='gd-jp'>代われるものなら、代わってあげたい。</span>(Andai bisa menggantikanmu, aku ingin menggantikanmu dan menanggungnya.)</div><div class='gd-ex-line'>・<span class='gd-jp'>休めるものなら、一週間ぐらい休みたい。</span>(Andai bisa cuti, aku ingin cuti seminggu.)</div><div class='gd-sec'><span class='gd-tag'>Menantang</span>Ini juga pemakaian ①, tapi di belakangnya diikuti bentuk perintah 「〜てみろ」. Artinya “kalau kamu bisa, coba saja!”. Kamu yakin lawan bicara tidak akan sanggup, lalu sengaja memancingnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>やれるものなら、やってみろ。</span>(Kalau memang bisa, coba saja lakukan!)</div><div class='gd-sec'><span class='gd-tag'>Peringatan</span>Pemakaian ②. Artinya “begitu melakukan ～, urusannya jadi gawat”. Sering dipakai bersama 「<span class='gd-jp'>少しでも</span>」「<span class='gd-jp'>一度でも</span>」「<span class='gd-jp'>一分でも</span>」 untuk menekankan, dengan agak berlebihan, betapa seramnya akibatnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの父は、門限を一分でも過ぎようものなら、すごく怒る。</span>(Ayahku itu, kalau pulang telat semenit saja dari jam malam, langsung marah besar.)</div><div class='gd-ex-line'>・<span class='gd-jp'>部長の前でそんなことを言おうものなら、大変なことになるよ。</span>(Kalau sampai ngomong begitu di depan kepala departemen, urusannya bisa runyam, lho.)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Di pemakaian ① wajib pakai <b>bentuk potensial</b>: yang benar <span class='gd-jp'>行けるものなら</span>, bukan 行くものなら.<br>・Di pemakaian ② pakai <b>bentuk volisional</b>: <span class='gd-jp'>言おうものなら</span>、<span class='gd-jp'>遅れようものなら</span>. Jangan campur dua cara sambung ini.<br>・Pemakaian ① membawa kesan “sulit dilakukan”. Kalau hal itu sebenarnya mudah, memakainya akan terdengar aneh. 「〜たら」 biasa saja sudah cukup.<br>・Di belakang pemakaian ① biasanya ada ungkapan keinginan (〜たい) atau perintah (〜てみろ), jarang diikuti kalimat pernyataan biasa.<br>・「<span class='gd-jp'>やれるものならやってみろ</span>」 itu kalimat menantang. Kalau diucapkan kepada orang yang lebih tua atau atasan, pasti bertengkar.<br>・Kalau diterjemahkan ke bahasa Indonesia, kedua pemakaian bisa jadi “kalau ～”, tapi maknanya jauh berbeda: bentuk potensial berarti “ingin sekali, tapi tidak bisa”, sedangkan bentuk volisional berarti “jangan sekali-kali lakukan”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama “ingin pergi”, tapi kalau diungkapkan dengan <b>〜たら</b> dan <b>〜ものなら</b>, tingkat keyakinan di hatimu berbeda:<br><b>〜たら</b> = pengandaian biasa, memang ada kemungkinan terjadi: <span class='gd-jp'>時間があったら、行きたい。</span>(Kalau ada waktu, aku mau pergi.)<br><b>〜ものなら</b> = kamu sendiri merasa hampir mustahil, hanya sekadar berandai-andai: <span class='gd-jp'>行けるものなら、行きたい。</span>(Andai bisa pergi, aku mau pergi… tapi sepertinya tidak bisa.)</div><div class='gd-warn'>Tips menentukan: kalau merasa “masih ada kemungkinan”, pakai たら. Kalau merasa “hampir tidak ada harapan, cuma berandai-andai”, pakai bentuk potensial + ものなら. Kalau mau memperingatkan orang “berani lakukan, tamat riwayatmu”, pakai 〜ようものなら.</div>","n2-19":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ないことには」artinya kira-kira <b>「kalau tidak ～ dulu, mustahil bisa ～」</b>. Hal di bagian depan itu <b>ambang pintu</b>. Kalau belum dilewati, bagian belakang tidak usah dibahas. Rasanya seperti ungkapan kita: “Belum dicoba, mana tahu enak atau tidak?” atau “Kalau bos belum setuju, tidak ada yang bisa dikerjakan.”</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Belum dicoba, belum tahu</span>Pemakaian yang paling umum. Bagian depannya hampir selalu berpasangan dengan 「〜てみない」 (tidak mencoba).</div><div class='gd-ex-line'>・<span class='gd-jp'>食べてみないことには、おいしいかどうかわからない。</span>(Kalau tidak dicoba makan, ya tidak tahu enak atau tidak)</div><div class='gd-ex-line'>・<span class='gd-jp'>やってみないことには、何とも言えません。</span>(Kalau belum benar-benar dicoba, saya juga sulit bilang apa-apa)</div><div class='gd-sec'><span class='gd-tag'>Syarat yang harus dipenuhi dulu</span>Kalau sesuatu belum selesai, bagian berikutnya tidak bisa jalan.</div><div class='gd-ex-line'>・<span class='gd-jp'>部長がOKしないことには、この企画は進められない。</span>(Kalau kepala bagian belum setuju, proyek ini tidak bisa dijalankan)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk ない dari verba, lalu langsung tambahkan 「ことには」. Yuk, ulangi dulu cara membentuk ない:<br><b>Golongan 1 (verba godan)</b>: ganti bunyi terakhir dengan bunyi baris 「あ」 di baris yang sama, lalu tambahkan ない.<span class='gd-pair'><span class='gd-jp'>行く</span> → ganti く jadi か → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span>(う berubah jadi わ)<br><b>Golongan 2 (verba ichidan)</b>: buang 「る」, lalu tambahkan ない.<span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見ない</span></span><br><b>Golongan 3</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>(こない)</span><br>Kalau digabung: <span class='gd-pair'><span class='gd-jp'>確認しない</span> → <span class='gd-jp'>確認しないことには</span></span></div><div class='gd-sec'>Ini ungkapan yang paling sering muncul di bagian belakang kalimat. Hafalkan saja sebagai satu paket: <span class='gd-jp'>わからない</span>、<span class='gd-jp'>何とも言えない</span>、<span class='gd-jp'>始まらない</span>、<span class='gd-jp'>決められない</span>、<span class='gd-jp'>話にならない</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bagian belakang harus berupa hasil seperti <b>「tidak bisa, tidak tahu, tidak terwujud」</b>. Tidak boleh diisi hasil yang positif: <span class='gd-jp'>勉強しないことには、合格できる</span> itu salah.<br>・Bagian belakang juga tidak boleh berisi perintah, permintaan, atau ajakan: <span class='gd-jp'>確認しないことには、電話してください</span> terdengar tidak natural.<br>・Jangan tertukar dengan 「<span class='gd-jp'>〜ないことはない</span>」, yang artinya “bukan berarti tidak ～”: <span class='gd-jp'>行けないことはない</span> (bukan berarti tidak bisa pergi). Beda satu kata saja, artinya sudah jauh berbeda.<br>・Nuansanya cukup formal, sering muncul di tempat kerja dan tulisan. Saat ngobrol dengan teman, orang lebih sering bilang 「<span class='gd-jp'>やってみないとわからない</span>」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ないことには</b> = hal itu belum terjadi, dan yang ditekankan adalah <b>“kalau tidak dilakukan dulu, ya tidak akan ada hasilnya”</b>. Bagian belakang hanya diisi hal negatif:<br><span class='gd-jp'>住んでみないことには、その町のよさはわからない。</span>(Kalau belum pernah tinggal di sana, kita tidak akan tahu serunya kota itu)<br><b>てはじめて</b> = hal itu sudah dilakukan, dan <b>baru setelah melakukannya</b> kita menyadari sesuatu untuk pertama kali. Bagian belakang berisi hal yang “baru sadar / baru paham” (baik atau buruk, boleh):<br><span class='gd-jp'>住んでみてはじめて、その町のよさがわかった。</span>(Setelah benar-benar tinggal di sana, baru aku tahu serunya kota itu)<br><b>ないと／なければ</b> = bentuk “kalau tidak ～” yang paling umum. Batasan di bagian belakang lebih longgar, bisa berisi peringatan, hasil, penilaian, dan sebagainya (tapi setelah 「<span class='gd-jp'>〜ないと</span>」 tidak boleh ada kalimat berisi kemauan atau permintaan seperti 「～ましょう」「～てください」):<br><span class='gd-jp'>予約しないと、入れないよ。</span>(Kalau tidak reservasi, kamu tidak bisa masuk lho)<br>Diganti jadi 「<span class='gd-jp'>予約しないことには、入れない</span>」 juga boleh, tapi nadanya lebih tegas, seakan menekankan bahwa “reservasi itu syarat mutlak”.</div><div class='gd-warn'>Tips menentukan: kalau mau bilang “sebelum dilakukan, tidak akan ada hasilnya”, pakai ないことには. Kalau “baru tahu setelah melakukannya”, pakai てはじめて. Kalau cuma “kalau tidak ～” biasa, cukup pakai ないと／なければ.</div>","n2-29":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にすぎない」artinya kira-kira <b>「hanya ～ saja」「tidak lebih dari ～」</b>. Pembicara sengaja <b>mengecilkan</b> sesuatu, maksudnya “ya cuma segitu, bukan hal besar”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina</b>: sambung langsung, tanpa だ di tengah.<br><span class='gd-pair'><span class='gd-jp'>噂</span> → <span class='gd-jp'>噂にすぎない</span></span>(hanya gosip)<br><b>Verba</b>: sambung dengan bentuk biasa (bentuk kamus, bentuk た).<br><span class='gd-pair'><span class='gd-jp'>従った</span> → <span class='gd-jp'>従ったにすぎない</span></span>(hanya menjalankan perintah)<br>Untuk bentuk lampau, jadi <b>にすぎなかった</b>, dan untuk bentuk sopan, jadi <b>にすぎません</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengecilkan sesuatu</span>Menekankan “ya cuma begitu, jangan dipikirkan terlalu jauh”.</div><div class='gd-ex-line'>・<span class='gd-jp'>それはただの噂にすぎない。</span>(Itu hanya gosip saja)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は命令に従ったにすぎない。</span>(Dia hanya menjalankan perintah)</div><div class='gd-sec'><span class='gd-tag'>Jumlahnya sedikit</span>Sering muncul bersama 「わずか」 (hanya sedikit), untuk menekankan angka yang kecil.</div><div class='gd-ex-line'>・<span class='gd-jp'>参加者はわずか5人にすぎなかった。</span>(Pesertanya hanya 5 orang saja)</div><div class='gd-sec'><span class='gd-tag'>Rendah hati saat dipuji</span>Kalau dipakai untuk diri sendiri, artinya “aku tidak melakukan sesuatu yang istimewa”.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は当たり前のことをしたにすぎません。</span>(Saya hanya melakukan hal yang memang seharusnya dilakukan)</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'>Di depannya sering ditambahkan <span class='gd-jp'>ただの</span>、<span class='gd-jp'>単なる</span> (sekadar), <span class='gd-jp'>ほんの</span> (hanya sedikit), atau <span class='gd-jp'>わずか</span> untuk memperkuat kesan “hanya”.<br>Kalau kalimatnya belum selesai dan masih berlanjut, ditulis jadi <b>にすぎず</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>これは一つの例にすぎず、問題はほかにもたくさんある。</span>(Ini hanya salah satu contoh, masih banyak masalah lainnya)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah nomina <b>jangan tambahkan だ</b>: yang benar <span class='gd-jp'>噂にすぎない</span>, bukan 「噂だにすぎない」.<br>・Ini dua hal yang berbeda dengan 「〜すぎる」 (terlalu ～). <span class='gd-jp'>高すぎない</span> artinya “tidak terlalu mahal”, sedangkan <span class='gd-jp'>にすぎない</span> pasti punya 「に」 di depannya dan artinya “hanya ... saja”.<br>・Nuansanya cukup formal, sangat umum di berita, laporan, dan pidato. Saat ngobrol dengan teman, <span class='gd-jp'>ただの噂だよ</span> atau <span class='gd-jp'>〜だけだよ</span> terdengar lebih natural.<br>・Ungkapan ini membawa penilaian “tidak layak dibahas”. Kalau dipakai untuk orang lain, seperti <span class='gd-jp'>彼はまだ新入社員にすぎない</span>, bisa terdengar agak meremehkan. Kalau dipakai untuk diri sendiri, barulah jadi rendah hati.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にすぎない</b> = <b>mengecilkan</b> sesuatu, “hanya ～ saja”:<br><span class='gd-jp'>今回の成功は偶然にすぎない。</span>(Keberhasilan kali ini hanya kebetulan saja)<br><b>にほかならない</b> = <b>menegaskan dengan pasti</b>, “tidak lain adalah ～, bukan yang lain”:<br><span class='gd-jp'>今回の成功はみんなの努力の結果にほかならない。</span>(Keberhasilan kali ini tidak lain adalah hasil kerja keras semuanya)<br>Keduanya berbentuk 「〜にＸない」 dan dalam bahasa Indonesia sama-sama bisa terdengar seperti “tidak lain / tidak lebih dari ～”, jadi gampang tertukar. Padahal nuansanya justru berlawanan: yang pertama merendahkan, yang kedua menegaskan dengan kuat.</div><div class='gd-warn'>Tips menentukan: kalau mau bilang “bukan hal yang hebat”, pakai にすぎない. Kalau mau bilang “ya itu dia, tidak ada yang lain”, pakai にほかならない.</div>","n2-41":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に違いない」artinya <b>「pasti ～」「tak diragukan lagi ～」</b>. Kamu melihat sebuah petunjuk, lalu menyimpulkan dengan sangat yakin, seperti detektif yang sedang menalar: \"Lampunya menyala, di dalam <b>pasti</b> ada orang.\" Yang diungkapkan adalah <b>dugaanmu</b>, bukan fakta yang sudah pasti.</div><div class='gd-h'>Dipakai kapan?</div><div class='gd-sec'><span class='gd-tag'>Menyimpulkan dari petunjuk</span>Ada bukti atau situasi di depan matamu yang membuatmu yakin.</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がついている。誰かいるに違いない。</span>（Lampunya menyala, pasti ada orang di dalam.）</div><div class='gd-ex-line'>・<span class='gd-jp'>顔がそっくりだ。あの二人は兄弟に違いない。</span>（Wajahnya mirip sekali, dua orang itu pasti kakak-adik.）</div><div class='gd-sec'><span class='gd-tag'>Menduga hal yang sudah terjadi</span>Bentuk lampau di depan, untuk menebak \"waktu itu pasti ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女はもう知っていたに違いない。</span>（Dia pasti sudah tahu dari tadi.）</div><div class='gd-sec'>Sering muncul bersama <span class='gd-jp'>きっと</span>, nadanya jadi lebih yakin: <span class='gd-jp'>きっと疲れているに違いない。</span>（Dia pasti capek sekali.）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja dan kata sifat-い</b>: sambung langsung. Bentuk sekarang, lampau, dan negatif semuanya bisa.<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るに違いない</span></span><span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たに違いない</span></span><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ないに違いない</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いに違いない</span></span></div><div class='gd-sec'><b>Kata sifat-な dan kata benda</b>: buang 「だ」 lalu sambung.<br><span class='gd-pair'><span class='gd-jp'>大変だ</span> → <span class='gd-jp'>大変に違いない</span></span><span class='gd-pair'><span class='gd-jp'>犯人だ</span> → <span class='gd-jp'>犯人に違いない</span></span><br>Dalam tulisan yang lebih formal, kadang juga ditulis <span class='gd-jp'>犯人であるに違いない</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata sifat-な dan kata benda, 「だ」 tidak boleh tetap ada: <span class='gd-jp'>大変だに違いない</span> itu salah.<br>・Dalam bahasa Indonesia, \"pasti\" kadang dipakai untuk meminta atau berjanji (\"Kamu pasti datang, ya!\"). Tapi 「に違いない」 hanya berarti \"menebak dengan sangat yakin\", jadi tidak bisa dipakai untuk menyuruh orang lain.<br>・Untuk hal yang kamu sendiri tahu jelas, jangan pakai pola ini. Kalau bilang soal identitas atau perasaan sendiri, <span class='gd-jp'>私は学生に違いない</span> terdengar seperti kamu menebak dirimu sendiri, jadi aneh.<br>・Pola ini agak berbau tulisan dan novel. Saat mengobrol dengan teman, orang Jepang lebih sering bilang <span class='gd-jp'>きっと〜だよ</span> atau <span class='gd-jp'>〜に決まってる</span>.<br>・Bentuk sopannya adalah <span class='gd-jp'>〜に違いありません</span>.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>はず</b> = berdasarkan fakta atau rencana yang sudah diketahui, \"seharusnya ～\":<br><span class='gd-jp'>昨日送ったから、今日届くはずだ。</span>（Dikirim kemarin, jadi seharusnya sampai hari ini.）<br><b>に違いない</b> = melihat petunjuk, lalu menalar sampai ke kesimpulan:<br><span class='gd-jp'>窓が割れている。泥棒が入ったに違いない。</span>（Jendelanya pecah, pasti ada maling yang masuk.）<br>Kalau kalimat ini diganti dengan はず, hasilnya tidak natural. Kamu tidak sedang menghitung berdasarkan rencana yang sudah diketahui, tapi menilai setelah melihat kejadian di tempat. Selain itu, はず bisa disambung dengan \"padahal kenyataannya tidak begitu\": <span class='gd-jp'>来るはずなのに来ない。</span>（Seharusnya datang, tapi nyatanya tidak datang.） に違いない tidak punya pemakaian seperti ini.</div><div class='gd-sec'><b>に決まっている</b> = \"ya jelas ～ lah\", lebih subjektif dan lisan, sering bernada emosi:<br><span class='gd-jp'>そんな話、嘘に決まってるよ。</span>（Cerita seperti itu ya jelas bohong lah.）<br><b>に相違ない</b> = artinya sama dengan に違いない, tapi lebih kaku dan lebih tertulis, kebanyakan muncul di dalam teks.</div><div class='gd-warn'>Kiat memilih: kalau menghitung berdasarkan logika atau rencana, pakai 「はず」; kalau menyimpulkan dari petunjuk, pakai 「に違いない」; kalau ingin bilang \"ya jelas lah\" dengan emosi saat ngobrol, pakai 「に決まってる」.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Lanjut lihat <span class='gd-jp'>〜に決まっている</span> dan <span class='gd-jp'>〜に相違ない</span> yang sama-sama menyatakan keyakinan, supaya kamu bisa membedakan nuansa dan situasi pemakaiannya.</div>","n2-43":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に相違ない」adalah <b>versi berjas</b> dari 「〜に違いない」, artinya \"pasti ～\" \"tak diragukan lagi ～\". Kamu sangat yakin, tapi ini <b>tetap dugaan</b>. Nuansanya mirip \"pastilah ～\" atau \"niscaya ～\" dalam laporan atau tajuk berita, dan tidak dipakai dalam obrolan sehari-hari.</div><div class='gd-sec'>Kenali dulu kata ini: <span class='gd-jp'>相違</span> dibaca <b>そうい</b>, artinya \"berbeda, ada selisih\". Jadi <span class='gd-jp'>相違ない</span> secara harfiah \"tidak ada selisih\", yaitu \"tidak mungkin salah\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja dan kata sifat-い: sambung langsung dengan bentuk biasa (bentuk tanpa ます dan です).<br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>知っているに相違ない</span></span>（pasti tahu）<br><span class='gd-pair'><span class='gd-jp'>高かった</span> → <span class='gd-jp'>高かったに相違ない</span></span>（waktu itu pasti mahal）</div><div class='gd-sec'>Kata benda dan kata sifat-な: <b>tanpa だ</b>, sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼に相違ない</span></span>（pasti dia）<br><span class='gd-pair'><span class='gd-jp'>有名</span> → <span class='gd-jp'>有名に相違ない</span></span>（pasti terkenal）<br>Untuk bentuk lampau, pakai <span class='gd-jp'>だった</span>: <span class='gd-jp'>彼だったに相違ない</span>（waktu itu pasti dia）</div><div class='gd-h'>Dipakai kapan?</div><div class='gd-sec'><span class='gd-tag'>Dugaan dalam tulisan</span>Dalam laporan, makalah, tajuk berita, dan novel detektif, untuk menilai berdasarkan petunjuk.</div><div class='gd-ex-line'>・<span class='gd-jp'>犯人はこの近くに住んでいるに相違ない。</span>（Pelakunya pasti tinggal di dekat sini.）</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は全員の努力の賜物に相違ない。</span>（Hasil ini pasti buah dari kerja keras semua orang.）</div><div class='gd-sec'><span class='gd-tag'>Versi sopan</span>Diubah jadi <span class='gd-jp'>〜に相違ありません</span>, untuk menyampaikan dugaanmu di situasi formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>犯人はあの男に相違ありません。</span>（Pelakunya pasti pria itu.）</div><div class='gd-sec'><span class='gd-tag'>Menegaskan fakta: kesaksian, dokumen</span>Jenis ini <b>bukan dugaan</b>. Saat memberi kesaksian, menjawab polisi, atau mengisi dokumen, <span class='gd-jp'>相違ありません</span> adalah ungkapan baku yang artinya \"memang begitu, tidak salah\", untuk hal yang memang sudah kamu ketahui sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは私の財布に相違ありません。</span>（Ini memang dompet saya.）</div><div class='gd-ex-line'>・<span class='gd-jp'>上記のとおり相違ありません。</span>（Hal-hal di atas benar adanya.）</div><div class='gd-sec'>Kalimat kedua sering tercetak di bagian paling bawah formulir permohonan atau surat pernyataan. Di depannya tidak ada に, karena artinya \"tidak ada selisih dengan yang tertulis di atas\".</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata benda dan kata sifat-な, <b>tidak boleh pakai だ</b>: yang benar <span class='gd-jp'>彼に相違ない</span>, bukan 彼だに相違ない.<br>・「相」 dalam <span class='gd-jp'>相違</span> dibaca <b>そう</b>, jadi keseluruhannya dibaca そういない.<br>・Kalau kamu bilang <span class='gd-jp'>あの店、おいしいに相違ない</span> ke teman, kedengarannya aneh, seperti sedang main drama detektif. Untuk lisan, pakai <span class='gd-jp'>おいしいに違いない</span> atau <span class='gd-jp'>きっとおいしいよ</span>.<br>・Saat dipakai sebagai dugaan, intinya adalah dugaan yang diyakini. Untuk hal yang sudah kamu pastikan sendiri dengan mata kepala atau memang sudah kamu tahu, 「〜に相違ない」 tidak dipakai untuk menduga. Pengecualiannya adalah saat <span class='gd-jp'>相違ありません</span> dipakai sebagai ungkapan baku untuk konfirmasi atau pembuktian (yaitu jenis kesaksian dan dokumen di atas).</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Situasinya sama: dia berhasil, apa penyebabnya?<br><b>に違いない</b> = \"pasti ～\" yang umum, bisa dipakai di lisan maupun tulisan:<br><span class='gd-jp'>彼が成功したのは、努力したからに違いない。</span>（Dia berhasil pasti karena sudah berusaha keras.）<br><b>に相違ない</b> = artinya sama, tapi lebih kaku dan lebih formal, hampir hanya muncul di dalam teks:<br><span class='gd-jp'>彼が成功したのは、努力したからに相違ない。</span>（Keberhasilannya niscaya karena kerja keras.）<br><b>に決まっている</b> = lisan, secara subjektif \"ya jelas begitu lah\", sering bernada tak mau dibantah:<br><span class='gd-jp'>努力したからに決まってるよ。</span>（Ya jelas karena dia sudah berusaha keras lah.）<br><b>にほかならない</b> = bukan dugaan, tapi pembicara <b>menegaskan</b> \"bukan yang lain, melainkan ～\", dipakai untuk menjelaskan sebab atau hakikat:<br><span class='gd-jp'>彼の成功は、努力の結果にほかならない。</span>（Keberhasilannya tak lain adalah hasil kerja keras.）</div><div class='gd-warn'>Kiat memilih: untuk dugaan biasa pakai に違いない; untuk dugaan yang sama tapi ditulis di laporan atau artikel, pakai に相違ない; untuk bilang \"ya jelas lah\" ke teman, pakai に決まっている; untuk menekankan \"justru ini, bukan yang lain\", pakai にほかならない.</div>","n2-50":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に伴って」artinya <b>「seiring dengan ～」「bersamaan dengan ～」</b>, sering muncul di berita dan pengumuman. Kalau satu hal terjadi atau berubah, hal lain ikut terjadi atau berubah. Kalimat pengumuman seperti 「Karena kantor pindah, nomor telepon akan berubah」 dalam bahasa Jepang sangat sering memakai pola ini.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Berubah bersama-sama</span>Kalau hal pertama berubah, hal kedua ikut berubah. Biasanya dipakai untuk perubahan yang berjalan pelan-pelan, seperti jumlah penduduk, ekonomi, atau suhu.</div><div class='gd-ex-line'>・<span class='gd-jp'>年を取るに伴って、体力が落ちてきた。</span>（Seiring bertambahnya usia, stamina jadi menurun）</div><div class='gd-ex-line'>・<span class='gd-jp'>気温の上昇に伴い、電気の使用量が増えている。</span>（Seiring naiknya suhu, pemakaian listrik terus bertambah）</div><div class='gd-sec'><span class='gd-tag'>Sekalian memunculkan hal lain</span>Bagian depan adalah peristiwa yang terjadi sekali saja, dan akibatnya ada hal lain yang ikut terjadi. Ini sangat sering muncul di pengumuman dan berita.</div><div class='gd-ex-line'>・<span class='gd-jp'>地震に伴い、津波が発生した。</span>（Bersamaan dengan gempa, terjadi tsunami）</div><div class='gd-ex-line'>・<span class='gd-jp'>事務所の移転に伴い、電話番号が変わります。</span>（Karena kantor pindah, nomor telepon akan berubah）</div><div class='gd-ex-line'>・<span class='gd-jp'>工事に伴って、この道は来週から通れなくなります。</span>（Karena ada pembangunan, jalan ini tidak bisa dilewati mulai minggu depan）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina＋に伴って</b>: bentuk yang paling umum, dan biasanya nomina yang menyatakan perubahan atau peristiwa seperti 「peningkatan, perkembangan, penyebaran, pemindahan」.<br><span class='gd-pair'><span class='gd-jp'>人口の増加</span> → <span class='gd-jp'>人口の増加に伴って</span></span><br><b>Verba bentuk kamus＋に伴って</b>, atau dengan の di tengah menjadi <b>のに伴って</b>. Dua-duanya sering kamu temui.<br><span class='gd-pair'><span class='gd-jp'>人口が増える</span> → <span class='gd-jp'>人口が増えるに伴って</span></span><br><span class='gd-pair'><span class='gd-jp'>年を取る</span> → <span class='gd-jp'>年を取るのに伴って</span></span></div><div class='gd-sec'><b>に伴って</b> dan <b>に伴い</b> artinya sama, tetapi <span class='gd-jp'>に伴い</span> lebih formal dan paling disukai untuk judul berita dan pengumuman.<br>Kalau langsung diikuti nomina, bentuknya jadi <b>に伴う＋nomina</b>: <span class='gd-jp'>台風に伴う大雨</span>（hujan lebat yang menyertai topan）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・「伴」dibaca <b>ともなって</b>. Jangan terbawa bacaan on-yomi-nya dan membacanya ばん.<br>・Pola ini sangat formal, dipakai di berita, laporan, dan pengumuman. Kalau ngobrol dengan teman, misalnya 「cuaca jadi dingin, semua mulai pakai jaket」, memakainya akan terdengar seperti membaca naskah berita. Dalam percakapan, <span class='gd-jp'>〜につれて</span> atau <span class='gd-jp'>〜と</span> terdengar lebih alami.<br>・Kalau memakai nomina, biasanya bentuknya 「〜の〜」: yang benar <span class='gd-jp'>経済の発展に伴って</span>, jangan ditulis 経済が発展に伴って.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>につれて</b> juga berarti 「seiring dengan ～」, tetapi hanya dipakai untuk <b>「berubah sedikit demi sedikit, dan sisi lainnya juga ikut berubah sedikit demi sedikit」</b>.<br>Untuk topik jumlah penduduk, dua-duanya bisa dipakai, hanya nuansanya berbeda:<br><span class='gd-jp'>人口が増えるにつれて、町がにぎやかになった。</span>（Seiring bertambahnya penduduk, kota jadi ramai: cocok untuk penjelasan maupun obrolan）<br><span class='gd-jp'>人口の増加に伴って、住宅不足が深刻化した。</span>（Seiring bertambahnya penduduk, kekurangan rumah makin parah: nuansa berita atau laporan）<br>Tetapi kalau bagian depan adalah <b>peristiwa yang terjadi sekali saja</b>, hanya に伴って yang bisa dipakai:<br>○<span class='gd-jp'>地震に伴い、津波が発生した。</span><br>×地震につれて、津波が発生した。（Gempa bukan 「perubahan pelan-pelan」, jadi につれて tidak bisa dipakai）</div><div class='gd-warn'>Trik menentukan: untuk hal yang 「terjadi sekali」 seperti gempa, pindahan, atau pembangunan, hanya に伴って yang bisa dipakai. Kalau kedua sisi sama-sama berubah pelan-pelan, dua-duanya boleh: untuk obrolan lebih condong ke につれて, untuk berita dan pengumuman lebih condong ke に伴って.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Pola lain yang juga menyatakan 「hubungan sebelum dan sesudah」 adalah <span class='gd-jp'>〜に応じて</span> (menyesuaikan dengan ～), misalnya <span class='gd-jp'>人数に応じて、部屋を選べます。</span>（Kamu bisa memilih kamar sesuai jumlah orang）. Intinya adalah 「menyesuaikan diri dengan situasi yang berbeda」, bukan 「ikut berubah」, jadi bagus untuk dihafalkan sebagai pembanding に伴って.</div>","n2-57":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜まい」bisa kamu bayangkan sebagai <b>kebalikan</b> dari bentuk ajakan/niat 「〜よう」, dan ini ungkapan kaku yang biasa muncul di tulisan. <span class='gd-jp'>行こう</span> artinya 「aku mau pergi」, sedangkan <span class='gd-jp'>行くまい</span> artinya 「aku tidak akan pergi lagi」. Ada juga arti kedua, yaitu 「kemungkinan besar tidak ～」. Keduanya terasa seperti ragam tulis dalam bahasa Indonesia, misalnya 「tidak akan pernah」 dan 「rasanya tidak mungkin」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bertekad tidak melakukan</span>Kamu sendiri yang memutuskan 「tidak akan ～ lagi」. Sering muncul bersama <span class='gd-jp'>二度と</span> (tidak akan lagi), dan di belakangnya sering ada <span class='gd-jp'>と思う</span>, <span class='gd-jp'>と心に誓う</span>, atau <span class='gd-jp'>と決める</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店には二度と行くまい。</span>（Aku tidak akan pernah pergi ke toko itu lagi）</div><div class='gd-ex-line'>・<span class='gd-jp'>二度とあのようなミスは犯すまいと心に誓った。</span>（Aku bersumpah dalam hati untuk tidak mengulangi kesalahan seperti itu lagi）</div><div class='gd-sec'><span class='gd-tag'>Menduga tidak akan</span>Artinya sama dengan <span class='gd-jp'>ないだろう</span>, dipakai untuk menebak bahwa orang lain atau suatu hal 「kemungkinan besar tidak ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は今さら戻ってくるまい。</span>（Setelah semua ini, dia kemungkinan besar tidak akan kembali）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことはあるまい。</span>（Rasanya tidak mungkin ada hal seperti itu）</div><div class='gd-sec'>Cara membedakannya: kalau subjeknya 「aku」 dan sedang bicara soal tekad, itu arti pertama. Kalau subjeknya orang lain atau suatu hal, itu arti kedua.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: bentuk kamus langsung ditambah まい.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くまい</span></span><span class='gd-pair'><span class='gd-jp'>乗る</span> → <span class='gd-jp'>乗るまい</span></span><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あるまい</span></span></div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: hilangkan 「る」 lalu tambah まい. Boleh juga tidak dihilangkan, yaitu bentuk kamus + まい. Dua-duanya benar.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べまい</span></span>／<span class='gd-jp'>食べるまい</span></div><div class='gd-sec'><b>Kelompok 3 (する・来る)</b>: bentuknya lebih bervariasi, jadi kenali semuanya kalau bertemu.<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>するまい</span></span>／<span class='gd-jp'>すまい</span>（ada juga yang memakai <span class='gd-jp'>しまい</span>）<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るまい</span></span>／<span class='gd-jp'>来まい</span><br>「来まい」secara tradisional dibaca こまい, tetapi zaman sekarang きまい juga sering dipakai. Kamu akan menemui dua-duanya.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Untuk kelompok 1, yang ditambah まい adalah <b>bentuk kamus</b>. Jangan disambung seperti bentuk 「ない」: yang benar <span class='gd-jp'>行くまい</span>, bukan 「行かまい」, apalagi 「行かないまい」.<br>・まい sendiri sudah bermakna negatif dan tidak punya versi positif. Kalau mau bilang 「aku akan melakukannya」, pakai bentuk niat <span class='gd-jp'>行こう</span>.<br>・Pola ini <b>tidak bisa dipakai untuk menyuruh orang lain tidak melakukan sesuatu</b>. <span class='gd-jp'>あなたは行くまい</span> bukan 「jangan pergi」, melainkan terdengar seperti 「kamu kemungkinan besar tidak akan pergi」. Untuk melarang, katakan <span class='gd-jp'>行かないで</span>.<br>・Kalau 「〜まい」 dipakai di akhir kalimat untuk menyatakan tekad, yang bertekad adalah si pembicara sendiri.<br>・Pola ini sangat tertulis dan kaku. Kalau kamu bilang <span class='gd-jp'>もう行くまい</span> ke teman, akan terdengar seperti narasi novel. Dalam percakapan, cukup <span class='gd-jp'>もう二度と行かない</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasi yang sama: menebak apakah dia akan datang besok.<br><b>ないだろう</b>: ungkapan umum, bisa dipakai untuk bicara maupun menulis.<br>・<span class='gd-jp'>彼は明日来ないだろう。</span>（Dia besok mungkin tidak datang）<br><b>まい</b>: artinya sama, tetapi tertulis dan kaku, dan nuansanya tetap hati-hati, yaitu 「kemungkinan besar」.<br>・<span class='gd-jp'>彼は明日来るまい。</span>（Dia besok sepertinya tidak akan datang）<br><b>っこない</b>: bahasa lisan dan sangat yakin, artinya 「mana mungkin」.<br>・<span class='gd-jp'>あんなに怒っていたんだから、来っこないよ。</span>（Dia semarah itu, mana mungkin dia datang）</div><div class='gd-warn'>Trik menentukan: untuk bicara sehari-hari pakai ないだろう. Untuk 「kemungkinan besar tidak」 yang bernuansa hati-hati di dalam tulisan, pakai まい. Untuk 「mana mungkin」 yang tegas saat mengobrol, pakai っこない.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>まい sering muncul dalam dua ungkapan tetap:<br>「〜うが〜まいが」artinya 「mau melakukan atau tidak」: <span class='gd-jp'>行こうが行くまいが、私の自由だ。</span>（Mau pergi atau tidak, itu hakku）<br>「〜ではあるまいし」artinya 「kan bukan ～」: <span class='gd-jp'>子どもじゃあるまいし、一人で行けるよ。</span>（Aku kan bukan anak kecil, bisa pergi sendiri kok）</div>","n2-62":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に越したことはない」artinya <b>\"kalau bisa, tentu lebih baik\"</b> atau <b>\"tidak ada yang lebih baik dari ini\"</b>. Pola ini menyatakan hal yang disetujui semua orang, seperti bilang \"ya iyalah\". Nadanya lembut dan bukan perintah.</div><div class='gd-sec'>Secara harfiah, <span class='gd-jp'>越す</span> berarti \"melampaui\". Seluruh kalimatnya berarti \"tidak ada hal yang melebihi ini\", jadi maknanya \"begini yang paling baik\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja: bentuk kamus atau bentuk ない + に越したことはない<br><span class='gd-pair'><span class='gd-jp'>確認する</span> → <span class='gd-jp'>確認するに越したことはない</span></span>(dicek dulu tentu lebih baik)<br><span class='gd-pair'><span class='gd-jp'>使わない</span> → <span class='gd-jp'>使わないに越したことはない</span></span>(kalau bisa tidak dipakai, tentu lebih baik)<br>Kata sifat-い: langsung disambung<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いに越したことはない</span></span><br>Kata sifat-な dan kata benda: langsung disambung, atau tambahkan である (lebih formal)<br><span class='gd-pair'><span class='gd-jp'>安全</span> → <span class='gd-jp'>安全に越したことはない</span></span>／<span class='gd-jp'>安全であるに越したことはない</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Pendapat umum</span>Dipakai sendirian, artinya \"kalau begini, pasti tidak salah\".</div><div class='gd-ex-line'>・<span class='gd-jp'>準備は早いに越したことはない。</span>(Persiapan tentu lebih baik kalau lebih awal)</div><div class='gd-ex-line'>・<span class='gd-jp'>薬は飲まないに越したことはない。</span>(Obat, kalau bisa tidak diminum, tentu lebih baik)</div><div class='gd-sec'><span class='gd-tag'>Diikuti けど・が</span>Ini pemakaian yang paling umum. Kamu mengakui dulu \"kalau bisa begitu tentu lebih baik\", lalu lanjut dengan \"tapi kenyataannya…\".</div><div class='gd-ex-line'>・<span class='gd-jp'>経験はあるに越したことはないが、なくても大丈夫です。</span>(Punya pengalaman tentu lebih baik, tapi kalau tidak punya juga tidak apa-apa)</div><div class='gd-ex-line'>・<span class='gd-jp'>値段は安いに越したことはないけど、品質も大事だよ。</span>(Harga memang lebih murah lebih baik, tapi kualitas juga penting, lho)</div><div class='gd-sec'>Kalimat seperti contoh pertama tadi sering muncul di iklan lowongan kerja. Artinya \"bukan syarat wajib, tapi kalau punya jadi nilai tambah\".</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Harus ditulis <b>越した</b>, bukan 越す: <span class='gd-jp'>越すことはない</span> itu salah.<br>・Di depannya dipakai <b>bentuk kamus</b>, bukan bentuk た: <span class='gd-jp'>早く行ったに越したことはない</span> itu salah. Yang benar <span class='gd-jp'>早く行くに越したことはない</span>.<br>・Jangan hanya melihat \"ことはない\" di belakang lalu mengira artinya \"tidak perlu\". Maknanya jauh berbeda (lihat perbandingan di bawah).<br>・Artinya \"kalau bisa tentu bagus\", <b>bukan \"harus\"</b>. Kalau mau menuntut orang lain melakukan sesuatu dengan tegas, pola ini tidak dipakai.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasi yang sama: \"buru-buru atau tidak\".<br><b>ことはない</b> = tidak perlu: <span class='gd-jp'>そんなに急ぐことはない。</span>(Tidak perlu buru-buru begitu)<br><b>に越したことはない</b> = tentu lebih baik: <span class='gd-jp'>急ぐに越したことはない。</span>(Kalau bisa lebih cepat, tentu lebih baik)</div><div class='gd-sec'>Situasi yang sama: \"berangkat lebih awal\".<br><b>ほうがいい</b> = langsung memberi saran ke lawan bicara: <span class='gd-jp'>早く出たほうがいいよ。</span>(Sebaiknya kamu berangkat lebih awal)<br><b>に越したことはない</b> = membicarakan hal yang berlaku umum, lebih halus dan memberi ruang: <span class='gd-jp'>早く出るに越したことはない。</span>(Berangkat lebih awal tentu lebih baik)</div><div class='gd-sec'>Ada satu lagi yang maknanya mirip: <b>に限る</b> = \"~ itu yang terbaik, pilih itu saja\", yaitu rekomendasi kuat dari pembicara sendiri: <span class='gd-jp'>暑い日は冷たいビールに限る。</span>(Hari panas ya paling pas minum bir dingin). に越したことはない adalah akal sehat yang disetujui semua orang, jadi nadanya lebih tenang.</div><div class='gd-warn'>Trik cepat: kalau kamu lihat 「に越した」, ingat \"tidak ada yang lebih baik\". Kalau hanya 「ことはない」, artinya \"tidak perlu\". Kalau mau langsung menyarankan lawan bicara, pakai 「ほうがいい」.</div>","n2-1":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜つつある」artinya <b>\"sedang makin ~\"</b> atau <b>\"semakin ~\"</b>. Pola ini menyatakan <b>perubahan yang sedang terjadi dan belum selesai</b>, seperti di berita: \"suhu terus naik\" atau \"ekonomi berangsur pulih\". Nadanya cukup formal dan biasanya muncul di berita, laporan, dan artikel.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Perubahan sedang berlangsung</span>Sesuatu berubah perlahan ke satu arah, dan sekarang masih terus berubah.</div><div class='gd-ex-line'>・<span class='gd-jp'>景気は少しずつ回復しつつある。</span>(Ekonomi sedang pulih sedikit demi sedikit)</div><div class='gd-ex-line'>・<span class='gd-jp'>この町の人口は減りつつある。</span>(Jumlah penduduk kota ini sedang berkurang perlahan)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本でもキャッシュレス決済が広がりつつある。</span>(Di Jepang juga, pembayaran nontunai semakin meluas)</div><div class='gd-sec'><span class='gd-tag'>Selangkah demi selangkah menuju hasil</span>Dipakai dengan kata kerja seperti \"menghilang\" atau \"mendekat\" yang biasanya terjadi sekali jadi. Artinya \"sedang selangkah demi selangkah menuju hasil itu, tapi belum sampai\".</div><div class='gd-ex-line'>・<span class='gd-jp'>台風が日本に近づきつつある。</span>(Topan sedang mendekati Jepang)</div><div class='gd-ex-line'>・<span class='gd-jp'>伝統的な祭りが消えつつある。</span>(Festival tradisional sedang berangsur menghilang)</div><div class='gd-sec'><span class='gd-tag'>Untuk masa lalu</span>Ubah jadi 「つつあった」, artinya pada saat itu sedang berubah.</div><div class='gd-ex-line'>・<span class='gd-jp'>当時、この町は大きく変わりつつあった。</span>(Saat itu, kota ini sedang mengalami perubahan besar)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます, lalu <b>buang ます</b> dan tambahkan 「つつある」.<br><span class='gd-pair'><span class='gd-jp'>増えます</span> → <span class='gd-jp'>増えつつある</span></span><span class='gd-pair'><span class='gd-jp'>進みます</span> → <span class='gd-jp'>進みつつある</span></span><br><span class='gd-pair'><span class='gd-jp'>回復します</span> → <span class='gd-jp'>回復しつつある</span></span><span class='gd-pair'><span class='gd-jp'>失われます</span> → <span class='gd-jp'>失われつつある</span></span><br>Kalau mau lebih sopan, pakai 「つつあります」: <span class='gd-jp'>景気は回復しつつあります。</span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Yang disambung adalah bentuk ます (tanpa ます), bukan bentuk kamus. Yang benar <span class='gd-jp'>増えつつある</span>, bukan 「増えるつつある」. Yang benar <span class='gd-jp'>回復しつつある</span>, bukan 「回復するつつある」.<br>・Akhirnya adalah <b>ある</b>, bukan いる.<br>・Hanya bisa dipakai dengan kata kerja yang \"mengalami perubahan\", seperti <span class='gd-jp'>増える</span>, <span class='gd-jp'>減る</span>, <span class='gd-jp'>変わる</span>, <span class='gd-jp'>広がる</span>, <span class='gd-jp'>進む</span>, dan 「〜化する」. Tindakan biasa tidak bisa: \"Aku sedang makan\" adalah <span class='gd-jp'>ご飯を食べている</span>, bukan 「ご飯を食べつつある」.<br>・Pola ini bergaya tulisan. Kalau ngobrol dengan teman dan ingin bilang \"akhir-akhir ini makin dingin ya\", yang natural adalah <span class='gd-jp'>最近、だんだん寒くなってきたね。</span> Kalau kamu bilang 「寒くなりつつある」, kedengarannya seperti pembaca berita.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜ている</b>: dengan kata kerja seperti \"hilang\", artinya <b>perubahan sudah selesai</b>.<br>・<span class='gd-jp'>その技術はもう失われている。</span>(Teknologi itu sudah hilang)<br><b>〜つつある</b>: artinya <b>masih berubah dan belum selesai</b>.<br>・<span class='gd-jp'>その技術は失われつつある。</span>(Teknologi itu sedang berangsur hilang)<br>Untuk kata kerja seperti \"bertambah\" atau \"berkurang\", <span class='gd-jp'>人口が減っている</span> juga bisa berarti \"sedang berkurang\", maknanya sangat dekat. Bedanya, つつある lebih menekankan proses \"terus berubah\" dan lebih formal.</div><div class='gd-sec'><b>〜ばかりだ</b> (disambung bentuk kamus): hanya berubah ke satu arah, dan hampir selalu ke arah yang buruk, dengan nada khawatir atau mengeluh.<br>・<span class='gd-jp'>景気は悪くなるばかりだ。</span>(Ekonomi hanya terus memburuk)<br><b>〜つつある</b>: hanya menggambarkan perubahan, bisa ke arah baik maupun buruk.<br>・<span class='gd-jp'>景気は回復しつつある。</span>(Ekonomi sedang berangsur pulih)</div><div class='gd-sec'><b>〜つつ(も)</b>: tanpa ある di belakang, artinya sama sekali berbeda, yaitu \"sambil ~\" atau \"padahal ~ tapi\".<br>・<span class='gd-jp'>体に悪いと知りつつ、タバコがやめられない。</span>(Tahu itu buruk untuk tubuh, tapi tetap tidak bisa berhenti merokok)</div><div class='gd-warn'>Trik cepat: kalau kamu lihat 「つつ＋ある」, artikan \"sedang makin ~\". Untuk \"sudah menjadi ~\", pakai ている. Untuk \"hanya makin buruk\", pakai ばかりだ. Kalau hanya 「つつ」 tanpa ある, artinya \"sambil ~\" atau \"padahal ~\".</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Masih soal perubahan, kamu bisa lanjut belajar 「〜につれて」 (seiring ~), misalnya <span class='gd-jp'>年をとるにつれて、体力が落ちてきた。</span>(Seiring bertambahnya usia, stamina jadi menurun)</div>","n2-3":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「AからBにかけて」artinya <b>「dari A sampai B (sekitar itu / selama kurun itu)」</b>. Kuncinya ada di kata <b>「kira-kira」</b>: titik awal dan titik akhirnya bukan garis yang tepat, tapi rentang yang agak kabur. Misalnya prakiraan cuaca bilang \"malam ini sampai besok akan hujan\". Tidak disebut jam berapa mulai dan jam berapa berhenti, nah, di bahasa Jepang kamu pakai にかけて.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Rentang waktu</span>Sesuatu terjadi dalam kurun waktu yang kira-kira saja. Bisa berlangsung terus-menerus, bisa juga putus-putus.</div><div class='gd-ex-line'>・<span class='gd-jp'>今夜から明日の朝にかけて、強い雨が降るでしょう。</span>(Dari malam ini sampai besok pagi akan turun hujan deras)</div><div class='gd-ex-line'>・<span class='gd-jp'>この辺りは、年末から正月にかけてとても混む。</span>(Daerah sini sangat ramai dari akhir tahun sampai masa Tahun Baru)</div><div class='gd-sec'><span class='gd-tag'>Rentang tempat</span>Satu area luas dari suatu tempat ke tempat lain. Sering dipakai di prakiraan cuaca dan berita.</div><div class='gd-ex-line'>・<span class='gd-jp'>九州から四国にかけて、大雨に注意してください。</span>(Dari Kyushu sampai Shikoku, waspadai hujan lebat)</div><div class='gd-sec'><span class='gd-tag'>Bagian tubuh</span>Sering terdengar juga dalam kehidupan sehari-hari, dan sangat berguna saat menjelaskan bagian yang sakit ke dokter.</div><div class='gd-ex-line'>・<span class='gd-jp'>首から肩にかけてが痛いんです。</span>(Dari leher sampai bahu saya sakit)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Pola dasar: Nomina＋から＋Nomina＋にかけて<br><span class='gd-pair'><span class='gd-jp'>3月から4月</span> → <span class='gd-jp'>3月から4月にかけて</span></span><br><br>Bagian 「から」 kadang boleh dihilangkan, jadi artinya hanya \"menuju ~ / sekitar ~\":</div><div class='gd-ex-line'>・<span class='gd-jp'>週末にかけて、天気が崩れるでしょう。</span>(Menjelang akhir pekan, cuaca akan memburuk)</div><div class='gd-sec'>Kalau setelahnya mau disambung dengan nomina, bentuknya jadi <b>にかけての</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>春から夏にかけての季節が一番好きだ。</span>(Aku paling suka musim dari musim semi sampai musim panas)</div><div class='gd-h'>Hal yang mudah keliru</div><div class='gd-warn'>・Dalam bahasa Indonesia, \"dari A sampai B\" dipakai untuk semua situasi, tapi di bahasa Jepang harus dibedakan: kalau <b>waktunya tepat</b>, misalnya jam kerja atau jam buka, pakai <b>から～まで</b>.<br>　×<span class='gd-jp'>9時から6時にかけて働きます。</span><br>　○<span class='gd-jp'>9時から6時まで働きます。</span><br>・Di depannya hanya boleh <b>nomina</b> yang \"bisa digambar rentangnya\", seperti waktu, tempat, atau bagian tubuh. Tidak bisa verba, dan tidak bisa orang: untuk \"dari Pak A sampai Pak B\" kamu tidak pakai にかけて.<br>・Saat disambung ke nomina, jangan lupa 「の」: yang benar <span class='gd-jp'>夏にかけての旅行</span>, bukan 夏にかけて旅行.<br>・Nuansanya agak tulisan dan formal, paling sering muncul di berita, prakiraan cuaca, dan teks penjelasan. Dalam obrolan sehari-hari juga terdengar, tapi untuk waktu, bahasa lisan lebih sering langsung pakai から～まで.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>から～まで</b> = titik awal dan akhir <b>jelas</b>: <span class='gd-jp'>会議は1時から3時までです。</span>(Rapatnya dari jam satu sampai jam tiga)<br><b>にかけて</b> = <b>kira-kira</b> di dalam rentang itu: <span class='gd-jp'>午後から夕方にかけて雨が降る。</span>(Dari siang sampai sore akan turun hujan)<br><b>にわたって</b> = menekankan bahwa <b>seluruh rentangnya tercakup dan skalanya besar</b>, sering dipakai dengan kata yang menunjukkan panjang atau luas seperti 「3日間」「10年」「全国」: <span class='gd-jp'>雨が3日間にわたって降り続いた。</span>(Hujan turun terus selama tiga hari penuh)</div><div class='gd-sec'>Selain itu, <b>にかけては</b> ada tambahan 「は」 dan artinya sama sekali berbeda, yaitu \"soal ~ / dalam hal ~\": <span class='gd-jp'>料理の腕にかけては、彼に勝てる人はいない。</span>(Soal keahlian memasak, tidak ada yang bisa mengalahkannya). Kalau kamu melihat 「は」 dan setelahnya memuji kehebatan seseorang, itulah pola ini.</div><div class='gd-warn'>Tips cepat: waktu tepat pakai まで, rentang kira-kira pakai にかけて, menekankan \"seluruh rentang yang panjang\" pakai にわたって; kalau ada 「は」 tambahan dan membahas kemampuan, itu にかけては.</div>","n2-4":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜末（に）」artinya <b>「setelah melalui proses panjang ~, akhirnya …」</b>. Di depannya ada proses yang menghabiskan waktu dan tenaga (berdiskusi lama, galau lama, berusaha keras), dan di belakangnya datang <b>hasil akhirnya</b>. Mirip dengan kamu bilang, \"Debat semalaman, akhirnya memutuskan liburan ke Jepang.\"</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Nomina</span>Nomina＋の＋末（に）<br><span class='gd-pair'><span class='gd-jp'>議論</span> → <span class='gd-jp'>議論の末に</span></span>(setelah berdiskusi)<br><span class='gd-pair'><span class='gd-jp'>苦労</span> → <span class='gd-jp'>苦労の末に</span></span>(setelah melalui banyak kesulitan)</div><div class='gd-sec'><span class='gd-tag'>Verba</span>Verba bentuk た＋末（に）<br><span class='gd-pair'><span class='gd-jp'>悩む</span> → <span class='gd-jp'>悩んだ</span> → <span class='gd-jp'>悩んだ末に</span></span>(setelah lama galau)<br><span class='gd-pair'><span class='gd-jp'>考える</span> → <span class='gd-jp'>考えた</span> → <span class='gd-jp'>考えた末に</span></span>(setelah lama berpikir)</div><div class='gd-sec'>「に」boleh dihilangkan, artinya tetap sama. Kalau setelahnya disambung dengan nomina, pakai「末の」: <span class='gd-jp'>悩んだ末の決断</span>(keputusan yang diambil setelah lama galau).</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'>Di belakangnya sering ada 「<span class='gd-jp'>ようやく</span>」「<span class='gd-jp'>やっと</span>」「<span class='gd-jp'>ついに</span>」 untuk menekankan arti \"akhirnya\".</div><div class='gd-ex-line'>・<span class='gd-jp'>長い話し合いの末、やっと契約が決まった。</span>(Setelah perundingan yang panjang, akhirnya kontraknya disepakati)</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も迷った末に、この部屋に決めた。</span>(Setelah beberapa kali bimbang, akhirnya memutuskan memilih kamar ini)</div><div class='gd-sec'>Hasilnya tidak harus hal baik, <b>hasil buruk pun boleh</b>. 「末」hanya menyampaikan secara objektif bagaimana akhirnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>長い闘病の末に亡くなった。</span>(Setelah lama berjuang melawan penyakit, akhirnya beliau meninggal dunia)</div><div class='gd-ex-line'>・<span class='gd-jp'>悩んだ末、進学を諦めた。</span>(Setelah lama galau, akhirnya melepaskan niat melanjutkan sekolah)</div><div class='gd-h'>Hal yang mudah keliru</div><div class='gd-warn'>・Verba harus memakai <b>bentuk た</b>: yang benar <span class='gd-jp'>悩んだ末</span>, bukan 「悩む末」.<br>・Di sini 末 dibaca <b>すえ</b>, bukan まつ.<br>・Di depannya harus ada \"sebuah proses\", yaitu hal yang memakan waktu seperti diskusi, usaha, kegalauan, atau negosiasi. Hanya menulis durasi tidak bisa: 「3時間の末」terdengar tidak natural, harus <span class='gd-jp'>3時間の議論の末</span>.<br>・「Nomina waktu＋の末」punya arti lain, yaitu \"akhir ~\": <span class='gd-jp'>来月の末に引っ越す</span> artinya \"pindah rumah di akhir bulan depan\", bukan \"setelah melewati bulan depan\".<br>・Di belakangnya adalah <b>hasil yang sudah keluar</b>, biasanya bentuk lampau (決めた、決まった、出た), dan tidak dipakai untuk ajakan \"ayo ~\" atau permintaan \"tolong ~\".<br>・Nuansanya cukup formal, sering muncul di berita, laporan, dan penjelasan resmi; kalau mengobrol dengan teman, lebih sering bilang 「<span class='gd-jp'>結局</span>」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>「<b>〜あげく（に）</b>」yang selevel punya cara sambung yang sama (bentuk た／nomina の) dan juga berarti \"setelah melalui proses panjang ~, akhirnya …\". Bedanya ada di <b>perasaan si pembicara</b>.<br><b>末</b> = menyampaikan hasil akhir secara objektif, baik, buruk, atau netral boleh:<br><span class='gd-jp'>さんざん迷った末、何も買わなかった。</span>(Setelah lama bimbang, akhirnya tidak membeli apa-apa)<br><b>あげく</b> = ada rasa tidak puas atau pasrah, terasa seperti \"capek-capek, eh ujung-ujungnya malah …\":<br><span class='gd-jp'>さんざん迷ったあげく、何も買わなかった。</span>(Bimbang lama sekali, eh ujung-ujungnya tidak beli apa-apa)<br>Jadi kalau hasilnya hal baik, seperti <span class='gd-jp'>努力の末に合格した</span>(setelah berusaha keras, akhirnya lulus), biasanya tidak diganti dengan あげく.</div><div class='gd-warn'>Tips cepat: kalau hanya menyampaikan hasil, pakai 末; kalau ada nada mengeluh atau pasrah, merasa \"capek-capek malah begini\", pakai あげく.</div><div class='gd-h'>Lanjut belajar</div><div class='gd-sec'>Selanjutnya kamu bisa belajar <span class='gd-jp'>〜あげく（に）</span>. Kalau dilatih berdampingan, perbedaan nuansanya lebih mudah ditangkap.</div>","n2-7":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜て以来」setara dengan <b>「sejak ~, (sampai sekarang) terus…」</b>. Di depan, kamu taruh satu kejadian di masa lalu sebagai <b>titik awal</b>. Di belakang, kamu jelaskan <b>keadaan apa yang berlangsung terus</b> dari saat itu sampai sekarang. Contohnya kalimat seperti 'Sejak pindah rumah, setiap pagi aku lari pagi'.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk て＋<span class='gd-jp'>以来</span> (dibaca いらい). Kamu sudah bisa bentuk て, jadi tinggal sambungkan saja:<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来て以来</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会って以来</span></span><span class='gd-pair'><span class='gd-jp'>卒業する</span> → <span class='gd-jp'>卒業して以来</span></span><br>Bentuk pasif juga bisa: <span class='gd-pair'><span class='gd-jp'>導入される</span> → <span class='gd-jp'>導入されて以来</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Keadaan yang berlanjut sampai sekarang</span>Bagian belakang sering dipasangkan dengan「ている」dan「ずっと」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来て以来、ずっとこのアパートに住んでいる。</span>(Sejak datang ke Jepang, aku terus tinggal di apartemen ini)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが生まれて以来、ゆっくり映画を見る時間がない。</span>(Sejak anakku lahir, aku tidak punya waktu untuk menonton film dengan santai)</div><div class='gd-sec'><span class='gd-tag'>Sejak itu tidak pernah lagi…</span>Bagian belakang sering dipasangkan dengan「一度も」dan「〜ていない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼とけんかして以来、一度も話していない。</span>(Sejak bertengkar dengannya, kami tidak pernah bicara sekali pun)</div><div class='gd-sec'><span class='gd-tag'>Sejak itu jadi…</span>Dipasangkan dengan「〜ようになった」: setelah berubah, keadaan baru itu bertahan sampai sekarang.</div><div class='gd-ex-line'>・<span class='gd-jp'>留学して以来、字幕なしでドラマが見られるようになった。</span>(Sejak belajar di luar negeri, aku jadi bisa menonton drama tanpa teks)</div><div class='gd-h'>Hal yang gampang salah</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk て</b>, bukan bentuk た: katakan <span class='gd-jp'>卒業して以来</span>, jangan 「卒業した以来」.<br>・Di belakangnya <b>tidak boleh ada kejadian yang hanya terjadi sekali</b>. 'Sejak datang ke Jepang, aku pergi ke Kyoto satu kali' tidak boleh pakai 以来: ×日本に来て以来、一度京都へ行った。 Untuk 'setelah itu melakukan sesuatu' seperti ini, pakai <span class='gd-jp'>日本に来てから、京都へ行った。</span><br>・Di depannya harus kejadian yang <b>sudah terjadi</b>. Tidak bisa dipakai untuk rencana masa depan.<br>・Titik awalnya biasanya sudah berjarak cukup lama dari sekarang. 'Sejak baru saja selesai makan siang' terdengar aneh dalam bahasa Indonesia, dan dalam bahasa Jepang sama anehnya.<br>・Nuansanya cukup formal dan lebih ke bahasa tulis. Saat ngobrol dengan teman, banyak orang memakai <span class='gd-jp'>〜てから、ずっと</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama tentang 'pindah rumah':<br><b>てから</b> = hanya menyatakan urutan, 'setelah A, lalu B':<br><span class='gd-jp'>引っ越してから、ジョギングを始めた。</span>(Setelah pindah rumah, aku mulai jogging)<br><b>て以来</b> = sejak saat itu <b>sampai sekarang</b> keadaannya begitu terus:<br><span class='gd-jp'>引っ越して以来、毎朝ジョギングしている。</span>(Sejak pindah rumah, setiap pagi aku jogging)<br><b>をきっかけに</b> = menekankan kejadian itu sebagai <b>pemicu</b>, karena itulah sesuatu dimulai:<br><span class='gd-jp'>引っ越しをきっかけに、ジョギングを始めた。</span>(Berawal dari pindah rumah, aku mulai jogging)</div><div class='gd-warn'>Trik untuk menentukan: kalau kalimat di belakang bisa ditambah 'sampai sekarang pun masih begitu', pakai て以来. Kalau cuma 'lalu', pakai てから. Kalau mau bilang 'karena kejadian ini, aku mulai', pakai をきっかけに.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'><span class='gd-jp'>以来</span> juga bisa langsung dipasang setelah kata benda waktu, atau pakai <span class='gd-jp'>それ以来</span> (sejak itu) untuk menyambung ke kalimat sebelumnya:</div><div class='gd-ex-line'>・<span class='gd-jp'>去年の春以来、彼から連絡がない。</span>(Sejak musim semi tahun lalu, dia tidak menghubungiku lagi)</div><div class='gd-ex-line'>・<span class='gd-jp'>一度飲みすぎて倒れた。それ以来、お酒は飲んでいない。</span>(Dulu aku pernah minum terlalu banyak sampai pingsan. Sejak itu aku tidak minum alkohol lagi)</div>","n2-9":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜からこそ」setara dengan <b>「justru karena ~, makanya ~」</b>. 「から」biasa hanya menyebutkan alasan. Dengan tambahan「こそ」, alasan itu seperti distabilo, artinya <b>'alasannya ya ini, bukan yang lain'</b>. Pola ini sering dipakai saat hasilnya berlawanan dengan pikiran umum. Orang biasanya merasa A membuat malas melakukan sesuatu, tapi kamu justru melakukannya karena A.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>「普通形」adalah bentuk biasa tanpa です・ます.<br><b>Kata kerja dan kata sifat い</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>思う</span> → <span class='gd-jp'>思うからこそ</span></span><span class='gd-pair'><span class='gd-jp'>頑張った</span> → <span class='gd-jp'>頑張ったからこそ</span></span><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいからこそ</span></span><br><b>Kata benda dan kata sifat な</b>: harus ditambah「だ」di tengah.<br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族だからこそ</span></span><span class='gd-pair'><span class='gd-jp'>大切</span> → <span class='gd-jp'>大切だからこそ</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menekankan alasan yang sebenarnya</span>Kamu memberi tahu lawan bicara: alasan aku melakukan ini ada di sini.</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたのことを思うからこそ、厳しく言うんです。</span>(Justru karena memikirkanmu, aku bicara sekeras ini)</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日練習したからこそ、本番で落ち着いていられた。</span>(Justru karena latihan setiap hari, aku bisa setenang itu saat tampil sungguhan)</div><div class='gd-sec'><span class='gd-tag'>Berlawanan dengan pikiran umum</span>Menurut logika biasa orang akan berpikir ke arah lain, tapi kamu bilang 'justru karena itulah aku ~'.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいからこそ、休みの日を大切にしている。</span>(Justru karena sibuk, aku sangat menghargai hari libur)</div><div class='gd-ex-line'>・<span class='gd-jp'>失敗したからこそ、わかったこともある。</span>(Justru karena pernah gagal, ada hal yang akhirnya kupahami)</div><div class='gd-sec'><span class='gd-tag'>だからこそ</span>Ditaruh di awal kalimat untuk menyambung isi kalimat sebelumnya, artinya 'dan justru karena itu'. Pemakaian ini sangat umum.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は大変です。だからこそ、やりがいがあります。</span>(Pekerjaan ini berat. Justru karena itu, pekerjaan ini terasa bermakna)</div><div class='gd-sec'>Bagian belakang kalimat sering diakhiri dengan「<span class='gd-jp'>のだ</span>」atau「<span class='gd-jp'>んです</span>」. Dengan itu nuansanya jadi 'sebenarnya begini lho', dan cocok sekali dengan からこそ.</div><div class='gd-h'>Hal yang gampang salah</div><div class='gd-warn'>・Jangan lupa「だ」untuk kata benda dan kata sifat な: yang benar <span class='gd-jp'>家族だからこそ</span>, bukan 「家族からこそ」.<br>・Hanya bisa dengan「から」, tidak bisa diganti「ので」: tidak ada bentuk「ので＋こそ」.<br>・Jangan dipakai untuk alasan kecil yang biasa saja atau negatif. Misalnya 'Aku bangun kesiangan, jadi terlambat', cukup pakai <span class='gd-jp'>寝坊したから遅刻した</span>. Kalau dibilang 「寝坊したからこそ遅刻した」, terdengar aneh, seolah-olah bangun kesiangan adalah alasan yang luar biasa.<br>・Dalam bahasa Indonesia kita bilang 'justru karena… maka…', tapi dalam bahasa Jepang bagian belakang tidak perlu kata khusus untuk 'justru'. こそ sudah membawa nuansanya.<br>・Ungkapan ini emosinya kuat, jadi lebih sering muncul saat bicara dari hati, dalam pidato, atau dalam tulisan. Kalau dipakai terus untuk hal kecil dalam obrolan sehari-hari, kesannya jadi dramatis.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>から</b> = sekadar menyebutkan alasan.<br>・<span class='gd-jp'>心配だから、電話した。</span>(Karena khawatir, aku meneleponmu)<br><b>からこそ</b> = menekankan 'justru alasan inilah', sering dipakai saat lawan bicara salah paham atau saat kamu ingin menegaskan perkataanmu.<br>・<span class='gd-jp'>心配だからこそ、何度も電話したんです。</span>(Justru karena khawatir, aku meneleponmu berkali-kali)</div><div class='gd-sec'><b>からには</b> = karena sudah ~, maka harus ~, di belakangnya ada tekad atau hal yang harus dilakukan.<br>・<span class='gd-jp'>留学するからには、しっかり勉強したい。</span>(Karena sudah memutuskan untuk belajar di luar negeri, aku mau belajar dengan sungguh-sungguh)<br><b>からこそ</b> = justru karena ~, makanya ~, di belakangnya ada hasil atau tindakan yang muncul karenanya.<br>・<span class='gd-jp'>留学したからこそ、台湾の良さに気づいた。</span>(Justru karena belajar di luar negeri, aku sadar betapa bagusnya Taiwan)</div><div class='gd-warn'>Trik untuk menentukan: kalau bisa diucapkan 'karena sudah ~, maka harus ~', pakai からには. Kalau bisa diucapkan 'justru karena ~, makanya ~', pakai からこそ. Kalau hanya 'karena ~, jadi ~' biasa, cukup pakai から.</div>","n2-16":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜つつも」artinya <b>「meskipun tahu ～, tetap saja ～」「di hati berpikir ～, tapi ternyata tetap ～」</b>. Rasanya seperti kalimat \"tahu begadang itu merusak badan, tapi tetap saja main HP sampai jam tiga\", yaitu <b>hati sudah tahu, tapi tindakan tidak mengikuti</b>. Pola ini cenderung <b>bahasa tulis</b>, lebih sering muncul di artikel, berita, dan situasi formal.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ambil bentuk ます dari kata kerja, buang ます, lalu tambahkan つつ（も）.<br><span class='gd-pair'><span class='gd-jp'>思う</span> → <span class='gd-jp'>思います</span> → <span class='gd-jp'>思いつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>知る</span> → <span class='gd-jp'>知ります</span> → <span class='gd-jp'>知りつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言います</span> → <span class='gd-jp'>言いつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べつつ</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>します</span> → <span class='gd-jp'>しつつ</span></span><br>Hanya bisa dipakai dengan <b>kata kerja</b>. Kata sifat dan kata benda tidak bisa langsung disambung.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Meskipun ～ tapi ～</span>Bagian depan berisi pikiran di hati, bagian belakang berisi tindakan yang bertentangan dengan pikiran itu. Yang paling umum adalah「<span class='gd-jp'>〜と知りつつ</span>」「<span class='gd-jp'>〜と思いつつ</span>」「<span class='gd-jp'>〜と言いつつ</span>」. Di belakangnya sering muncul <span class='gd-jp'>てしまう</span> atau <span class='gd-jp'>られない</span>, dengan nuansa menyesal atau tidak bisa melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>体に悪いと知りつつも、夜更かしがやめられない。</span>（Tahu itu tidak baik untuk badan, tapi tetap tidak bisa berhenti begadang）</div><div class='gd-ex-line'>・<span class='gd-jp'>早く返事をしなきゃと思いつつ、一週間たってしまった。</span>（Terus kepikiran harus cepat membalas, tapi tahu-tahu seminggu sudah lewat）</div><div class='gd-ex-line'>・<span class='gd-jp'>ダイエット中だと言いつつ、ケーキを二つも食べた。</span>（Katanya sedang diet, tapi malah makan dua potong kue）</div><div class='gd-sec'><span class='gd-tag'>Sambil ～ sambil ～</span>「つつ」tanpa「も」punya arti lain: dua hal berlangsung bersamaan. Ini versi bahasa tulis dari「ながら」.</div><div class='gd-ex-line'>・<span class='gd-jp'>景色を楽しみつつ、山道を歩いた。</span>（Sambil menikmati pemandangan, aku berjalan di jalan setapak gunung）</div><div class='gd-ex-line'>・<span class='gd-jp'>皆さんの意見を聞きつつ、計画を進めていきます。</span>（Kami akan menjalankan rencana sambil mendengarkan pendapat semuanya）</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Sambungkan dengan bentuk ます, bukan bentuk kamus: yang benar <span class='gd-jp'>知りつつ</span>, tidak boleh 「知るつつ」.<br>・Subjek bagian depan dan belakang harus <b>orang yang sama</b>. Kalimat \"Ibu menentang, tapi aku tetap pergi kuliah ke luar negeri\" melibatkan dua orang, jadi tidak bisa pakai つつ. Pakai <span class='gd-jp'>母は反対したが、私は留学した。</span><br>・Kalau ada 「も」, artinya pasti \"meskipun ～ tapi ～\". Kalau hanya 「つつ」, kamu harus lihat konteksnya untuk menentukan apakah artinya \"meskipun\" atau \"sambil\".<br>・Pola ini cenderung bahasa tulis. Saat ngobrol dengan teman, biasanya cukup pakai 「<span class='gd-jp'>〜けど</span>」「<span class='gd-jp'>〜のに</span>」. Tapi ungkapan tetap seperti 「<span class='gd-jp'>〜と思いつつ</span>」「<span class='gd-jp'>〜と知りつつ</span>」 juga sering terdengar dalam percakapan.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>つつも dan ながらも</b>: artinya hampir sama, dan dalam satu kalimat sering bisa saling menggantikan.<br><span class='gd-jp'>悪いと知りつつも、やってしまった。</span><br><span class='gd-jp'>悪いと知りながらも、やってしまった。</span>（Tahu itu salah, tapi tetap melakukannya）<br>Bedanya: つつも <b>hanya bisa dipakai dengan kata kerja</b> dan nuansanya lebih seperti bahasa tulis. ながらも bisa juga dipakai dengan kata sifat dan kata benda, misalnya <span class='gd-jp'>狭いながらも楽しい我が家</span> (kecil, tapi rumah yang menyenangkan). Di sini tidak bisa diganti dengan つつも.</div><div class='gd-sec'><b>つつも dan つつある</b>: bedanya hanya satu kata, tapi artinya sama sekali berbeda. つつある berarti \"sedang perlahan menjadi ～\", dan tidak punya arti \"meskipun\".<br><span class='gd-jp'>景気は回復しつつある。</span>（Perekonomian sedang perlahan pulih）</div><div class='gd-warn'>Tips menentukan: untuk \"meskipun tahu ～ tapi ～\" pakai つつも; kalau bagian depannya kata sifat atau kata benda, ganti ke ながらも; kalau kamu melihat つつある, pikirkan \"sedang perlahan berubah\".</div>","n2-17":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ながら（も）」di sini artinya <b>「meskipun ～ tapi ～」「padahal ～ kok masih ～」</b>. Bagian depan menyebut satu keadaan, lalu bagian belakang menyambung dengan hasil yang \"seharusnya tidak begitu\".<br>Di N4 kamu sudah belajar「<span class='gd-jp'>音楽を聞きながら勉強する</span>」(belajar sambil mendengarkan musik), yaitu <b>melakukan dua hal bersamaan</b>. Bentuknya persis sama, tapi artinya sama sekali berbeda.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: pakai bentuk ます, buang ます, lalu tambahkan ながら. Yang paling umum berbentuk「〜ている」.<br><span class='gd-pair'><span class='gd-jp'>住んでいます</span> → <span class='gd-jp'>住んでいながら</span></span><span class='gd-pair'><span class='gd-jp'>知ります</span> → <span class='gd-jp'>知りながら</span></span><br><b>Kata sifat-い</b>: sambung langsung, い tidak berubah. <span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いながら</span></span><br><b>Kata sifat-な</b>: buang な lalu sambungkan. <span class='gd-pair'><span class='gd-jp'>残念な</span> → <span class='gd-jp'>残念ながら</span></span><br><b>Kata benda</b>: sambung langsung. <span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どもながら</span></span><br>Kalau ditambah「も」di belakangnya menjadi「ながらも」, artinya sama, hanya saja kesan \"meskipun\"-nya sedikit lebih kuat.</div><div class='gd-ex-line'>・<span class='gd-jp'>近くに住んでいながら、一度も行ったことがない。</span>（Padahal tinggal di dekat sana, sekali pun belum pernah pergi）</div><div class='gd-ex-line'>・<span class='gd-jp'>悪いと知りながら、うそをついてしまった。</span>（Tahu itu salah, tapi tetap berbohong）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は学生ながら、自分で会社を経営している。</span>（Meskipun masih mahasiswa, dia mengelola perusahaan sendiri）</div><div class='gd-ex-line'>・<span class='gd-jp'>狭いながらも、住み心地のいい部屋だ。</span>（Meskipun sempit, ini kamar yang nyaman ditinggali）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Ada beberapa yang sudah menjadi ungkapan tetap, sangat sering terdengar di kehidupan sehari-hari maupun di tempat kerja. Menghafal seluruh kalimatnya adalah cara tercepat.</div><div class='gd-sec'><span class='gd-tag'>残念ながら</span>Sayangnya / dengan menyesal. Sering dipakai saat menyampaikan kabar buruk.</div><div class='gd-ex-line'>・<span class='gd-jp'>残念ながら、明日の試合は中止になりました。</span>（Sayangnya, pertandingan besok dibatalkan）</div><div class='gd-sec'><span class='gd-tag'>勝手ながら</span>Sering muncul di pengumuman toko, artinya \"mohon maaf, kami dengan seenaknya ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>勝手ながら、本日は休業させていただきます。</span>（Mohon maaf, hari ini kami tutup）</div><div class='gd-sec'><span class='gd-tag'>陰ながら</span>Diam-diam dari belakang layar.</div><div class='gd-ex-line'>・<span class='gd-jp'>陰ながら応援しています。</span>（Aku diam-diam mendukungmu）</div><div class='gd-sec'><span class='gd-tag'>我ながら</span>Bahkan aku sendiri merasa begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>我ながらよくできたと思う。</span>（Aku sendiri pun merasa ini hasilnya bagus）</div><div class='gd-h'>Hal yang sering salah</div><div class='gd-warn'>・Jangan menambah-nambah saat menyambung: yang benar <span class='gd-jp'>狭いながら</span>, bukan 狭くながら; <span class='gd-jp'>残念ながら</span>, bukan 残念なながら; <span class='gd-jp'>子どもながら</span>, bukan 子どものながら.<br>・Selain ungkapan tetap di atas, pola ini <b>cenderung bahasa tulis dan formal</b>, dipakai di artikel, berita, dan wawancara kerja. Saat ngobrol dengan teman, 「<span class='gd-jp'>狭いけど、いい部屋だよ</span>」 terdengar lebih natural.<br>・<span class='gd-jp'>昔ながらの</span> dan <span class='gd-jp'>生まれながらの</span> bukan berarti \"meskipun\": <span class='gd-jp'>昔ながらの町並み</span> artinya \"deretan jalan yang masih mempertahankan suasana zaman dulu\", sedangkan <span class='gd-jp'>生まれながらの才能</span> artinya \"bakat bawaan sejak lahir\". Hafalkan terpisah.<br>・Bagian depan dan belakang biasanya membicarakan <b>orang yang sama atau hal yang sama</b>, misalnya \"Meskipun dia mahasiswa, (dia) membuka perusahaan\".</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>ながら untuk hal bersamaan</b> = sambil ～ sambil ～: <span class='gd-jp'>テレビを見ながらご飯を食べる。</span>（Makan sambil menonton TV）<br><b>ながら untuk pertentangan</b> = padahal ～ tapi ～: <span class='gd-jp'>毎日テレビを見ていながら、そのニュースを知らなかった。</span>（Padahal setiap hari menonton TV, tapi tidak tahu berita itu）</div><div class='gd-sec'><b>つつ（も）</b>: artinya hampir sama dengan ながら（も） yang bermakna pertentangan, tapi lebih bersifat bahasa tulis dan <b>hanya bisa dipakai dengan kata kerja</b>.<br><span class='gd-jp'>悪いと知りつつも、うそをついてしまった。</span>（Tahu itu salah, tapi tetap berbohong）<br>Tidak bisa dipakai dengan kata sifat dan kata benda: harus bilang <span class='gd-jp'>狭いながらも</span>, tidak boleh 狭いつつも.</div><div class='gd-sec'><b>くせに</b>: juga berarti \"padahal ～\", tapi mengandung nuansa <b>menyalahkan dan tidak puas</b>, yaitu keluhan dalam bahasa lisan.<br><span class='gd-jp'>知っているくせに、教えてくれない。</span>（Padahal jelas-jelas tahu, kok tidak mau kasih tahu aku!）<br><span class='gd-jp'>知っていながら、教えてくれなかった。</span>（Padahal tahu, tapi tidak memberi tahu: lebih seperti pernyataan yang tenang）</div><div class='gd-warn'>Tips menentukan: kalau bagian depannya kata sifat atau kata benda, atau di belakangnya ada 「も」, artinya \"meskipun\". Kalau bagian depannya kata kerja, lihat apakah paruh kalimat belakang \"bertentangan dengan dugaan\". Kalau iya, artinya \"meskipun\"; kalau tidak, artinya \"sambil ～ sambil ～\". Kalau mau mengeluh ke lawan bicara pakai くせに, kalau menulis pakai ながら atau つつ.</div>","n2-10":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にもかかわらず」artinya <b>「meskipun ～, tetap saja ～」</b>. Bagian depan menyebut satu fakta, lalu bagian belakang menyambung hasil yang <b>berlawanan dengan dugaan</b>. Artinya mirip「のに」, tapi nuansanya lebih <b>resmi dan objektif</b>. Pola ini sering muncul di berita, laporan, pidato, dan situasi bisnis, dan jarang dipakai saat ngobrol dengan teman.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Hasil di luar dugaan</span>Seharusnya terjadi A, tapi kenyataannya tidak begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も確認したにもかかわらず、同じミスをしてしまった。</span>（Meskipun sudah memeriksa berkali-kali, aku tetap membuat kesalahan yang sama）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が集まった。</span>（Meskipun hujan, banyak orang yang tetap berkumpul）</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan keadaan saat ini</span>Bagian belakang tidak harus bentuk lampau. Hal yang sedang berlangsung juga bisa.</div><div class='gd-ex-line'>・<span class='gd-jp'>反対が多いにもかかわらず、政府は計画を進めている。</span>（Meskipun banyak yang menentang, pemerintah tetap melanjutkan rencana itu）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はお金持ちであるにもかかわらず、質素な生活をしている。</span>（Meskipun dia kaya, dia menjalani hidup yang sederhana）</div><div class='gd-sec'><span class='gd-tag'>Ucapan terima kasih di acara resmi</span>Ungkapan baku yang sering terdengar di pidato dan surat bisnis.</div><div class='gd-ex-line'>・<span class='gd-jp'>本日はお忙しいにもかかわらず、お集まりいただきありがとうございます。</span>（Terima kasih banyak karena hari ini Anda semua tetap berkenan hadir di tengah kesibukan）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat い</b>：sambung langsung dengan bentuk biasa (bentuk kamus, bentuk た, atau bentuk ない).<br><span class='gd-pair'><span class='gd-jp'>努力した</span> → <span class='gd-jp'>努力したにもかかわらず</span></span><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いにもかかわらず</span></span></div><div class='gd-sec'><b>Kata benda, kata sifat な</b>：jangan tambahkan「だ」. Sambung langsung, atau tambahkan「である」.<br><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨にもかかわらず</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生であるにもかかわらず</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便にもかかわらず</span></span>（bisa juga <span class='gd-jp'>不便であるにもかかわらず</span>）<br>Untuk bentuk lampau, cukup pakai「だった」：<span class='gd-jp'>学生だったにもかかわらず</span>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda, <b>jangan tambahkan だ</b>: yang benar <span class='gd-jp'>雨にもかかわらず</span>, bukan「雨だにもかかわらず」.<br>・Bagian belakang harus berisi <b>fakta</b> (sudah terjadi atau sedang berlangsung). Jadi tidak bisa diikuti kalimat kehendak, ajakan, perintah, atau permintaan seperti 「ayo ～」「tolong ～」「aku akan ～」. Untuk bilang 「Meskipun hujan, ayo kita tetap pergi」, pakai ても: <span class='gd-jp'>雨でも出かけよう。</span><br>・Bagian depan juga harus berupa <b>fakta</b>. Kata seperti 「sekalipun」「biarpun」「andaikan」 sering dipakai untuk hal yang belum terjadi (pengandaian). Untuk yang seperti itu pakai「ても」, bukan にもかかわらず.<br>・Pola ini sangat resmi. Kalau mau mengeluh ke teman, misalnya 「Kan sudah kubilang, kok kamu tetap tidak dengar」, のに terdengar lebih alami. Kalau pakai にもかかわらず, kedengarannya seperti sedang membaca siaran pers.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>のに</b> = membawa <b>perasaan pribadi</b> (kesal, sayang, kaget). Sering dipakai dalam percakapan, dan bisa dipakai di akhir kalimat tanpa dilanjutkan. Padanan terdekatnya 「padahal」.<br><b>にもかかわらず</b> = menyampaikan dengan <b>tenang dan objektif</b>, resmi, dan lebih ke bahasa tulis.</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も説明したのに、全然わかってくれない！</span>（Padahal sudah kujelaskan berkali-kali, kok kamu tetap tidak mengerti!）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も説明したにもかかわらず、理解してもらえなかった。</span>（Meskipun sudah dijelaskan berkali-kali, dia tetap tidak bisa memahaminya）</div><div class='gd-sec'>Kalimat yang berhenti di tengah seperti <span class='gd-jp'>せっかく作ったのに。</span>（Padahal aku sudah susah payah membuatnya）hanya bisa dengan のに, tidak bisa dengan にもかかわらず.</div><div class='gd-sec'>Satu lagi yang sangat gampang salah baca: <b>にかかわらず</b> tanpa「も」. Artinya sama sekali berbeda, yaitu <b>「tidak peduli ～」</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢にかかわらず、誰でも参加できます。</span>（Berapa pun usianya, siapa saja boleh ikut）</div><div class='gd-ex-line'>・<span class='gd-jp'>天気にかかわらず、試合は行います。</span>（Bagaimana pun cuacanya, pertandingan tetap diadakan）</div><div class='gd-warn'>Tips membedakan: kalau mau mengeluh atau membawa perasaan, pakai のに. Kalau mau bilang 「meskipun ～ tetap ～」 secara resmi dan objektif, pakai にもかかわらず. Kalau melihat「にかかわらず」, cek dulu ada「も」-nya atau tidak: kalau ada も artinya 「meskipun」, kalau tidak ada も artinya 「tidak peduli」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau ditaruh di awal kalimat menjadi「<span class='gd-jp'>それにもかかわらず</span>」, artinya 「meskipun begitu」, dipakai untuk menyambung kalimat sebelumnya: <span class='gd-jp'>何度も注意された。それにもかかわらず、彼は遅刻を続けた。</span>（Dia sudah ditegur berkali-kali. Meskipun begitu, dia terus saja terlambat）<br><span class='gd-jp'>ものの</span> dan <span class='gd-jp'>とはいえ</span> di level yang sama juga berarti 「meskipun ～, tetapi ～」. Pelajari sekalian sambil dibandingkan.</div>","n2-12":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜とはいえ」artinya <b>「Memang ～, tapi…」「Meskipun dibilang begitu, tapi…」</b>. Bagian depan mengakui satu fakta, lalu bagian belakang menambahkan: 「Tapi, tidak sesederhana yang kamu bayangkan.」<br>Contohnya kamu bilang 「Biarpun sudah musim semi, pagi harinya tetap dingin」. Kamu mengakui sekarang musim semi, tapi kesan 「musim semi = hangat」 tidak sepenuhnya benar.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memang ～</span>Bagian depan berisi fakta yang menimbulkan kesan tertentu saat didengar, lalu bagian belakang menjelaskan kenyataan yang berbeda dari kesan itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>春とはいえ、朝晩はまだ寒い。</span>（Biarpun sudah musim semi, pagi dan malam masih dingin）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に5年住んでいるとはいえ、敬語はまだ苦手だ。</span>（Memang sudah lima tahun tinggal di Jepang, tapi aku masih kurang pandai menggunakan bahasa sopan）</div><div class='gd-ex-line'>・<span class='gd-jp'>安いとはいえ、毎日買うと結構な金額になる。</span>（Memang murah, tapi kalau dibeli setiap hari jumlahnya lumayan juga）</div><div class='gd-sec'><span class='gd-tag'>Di awal kalimat</span>Kalau ditaruh sendiri di awal kalimat, artinya 「meskipun begitu」, dipakai untuk menyambung kalimat sebelumnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事は大変だ。とはいえ、辞めるつもりはない。</span>（Pekerjaannya berat. Meskipun begitu, aku tidak berniat berhenti）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja, kata sifat い: sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>慣れている</span> → <span class='gd-jp'>慣れているとはいえ</span></span><span class='gd-pair'><span class='gd-jp'>合格した</span> → <span class='gd-jp'>合格したとはいえ</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いとはいえ</span></span><br>Kata benda, kata sifat な:「だ」di belakangnya <b>biasanya dihilangkan</b>, langsung sambung とはいえ (boleh juga pakai だ).<br><span class='gd-pair'><span class='gd-jp'>春</span> → <span class='gd-jp'>春とはいえ</span></span><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利とはいえ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>便利とはいえ、スマホばかり見るのはよくない。</span>（Memang praktis, tapi terus-terusan menatap ponsel itu tidak baik）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・「は」dibaca <b>wa</b>: とはいえ dibaca「とわいえ」.<br>・Bagian depan harus berupa <b>fakta yang sudah berlaku</b>, tidak bisa berisi pengandaian yang belum terjadi. Untuk 「Sekalipun besok hujan」 katakan <span class='gd-jp'>明日雨が降っても</span>, bukan とはいえ.<br>・Bagian belakang harus berisi hal yang 「berbeda dari dugaan」, dan sering muncul bersama <span class='gd-jp'>まだ</span> atau <span class='gd-jp'>やはり</span>. Ini bukan 「jadi」, jadi bagian belakang tidak boleh berupa kelanjutan yang searah dengan bagian depan.<br>・とはいえ agak bernuansa bahasa tulis dan resmi. Kalau ngobrol dengan teman, lebih sering dipakai <span class='gd-jp'>とは言っても</span> atau <span class='gd-jp'>って言っても</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ものの</b> juga berarti 「meskipun ～ tetapi」, tapi pemakaian yang paling alami adalah 「<b>sudah melakukan sesuatu, tapi hasilnya tidak sesuai harapan</b>」:<br>・<span class='gd-jp'>チケットを買ったものの、結局行けなかった。</span>（Tiketnya sudah dibeli, tapi akhirnya tidak jadi pergi）<br>Kalau bagian depannya kata benda, ものの harus ditulis 「kata benda + である + ものの」, yang terasa agak kaku. Di situasi itu, とはいえ lebih luwes:<br>・<span class='gd-jp'>プロとはいえ、ミスすることもある。</span>（Meskipun profesional, ada kalanya juga membuat kesalahan）</div><div class='gd-sec'><b>にもかかわらず</b> berarti 「meskipun ～, ternyata…」, menekankan hasil yang <b>di luar dugaan</b>, sering dengan nuansa kaget atau menyalahkan:<br>・<span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（Meskipun hujan, banyak orang yang tetap datang）<br>とはいえ tidak punya rasa kaget sekuat itu. Lebih seperti mengakui fakta di depan, lalu dengan tenang menambahkan 「tapi…」.</div><div class='gd-warn'>Tips membedakan: 「Memang berstatus/berkeadaan ～, tapi bukan berarti…」 pakai とはいえ; 「Sudah melakukan ～, tapi hasilnya tidak…」 pakai ものの; 「Meskipun ～, ternyata masih…」 pakai にもかかわらず.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'><span class='gd-jp'>とはいうものの</span>, yang artinya hampir sama, juga bisa ditaruh di awal kalimat sebagai 「meskipun begitu」: <span class='gd-jp'>とはいうものの、やはり心配だ。</span>（Meskipun begitu, tetap saja khawatir）</div>","n2-13":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜くせに」 kira-kira berarti <b>\"padahal ～ masih saja ～\"</b> atau <b>\"sudah ～ tapi kok masih ～\"</b>, dan diucapkan dengan nada kesal. Kalau ada yang bilang 「<span class='gd-jp'>知ってるくせに</span>」, artinya bukan sekadar \"padahal tahu\". Di baliknya ada maksud \"kamu keterlaluan deh\". Ini bukan deskripsi yang objektif, tapi untuk <b>menegur dan menyindir orang</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja dan kata sifat-い: disambung langsung (bentuk sekarang maupun lampau bisa)<br><span class='gd-pair'><span class='gd-jp'>知っている</span> → <span class='gd-jp'>知っているくせに</span></span><span class='gd-pair'><span class='gd-jp'>若い</span> → <span class='gd-jp'>若いくせに</span></span><span class='gd-pair'><span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったくせに</span></span><br>Kata sifat-な: pertahankan <b>な</b> lalu sambungkan　<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なくせに</span></span><br>Kata benda: tambahkan <b>の</b> lalu sambungkan　<span class='gd-pair'><span class='gd-jp'>子ども</span> → <span class='gd-jp'>子どものくせに</span></span></div><div class='gd-h'>Pola yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Menyindir orang</span>Bagian depan menyebut kondisi lawan bicara, bagian belakang menyebut tindakannya yang tidak pantas.</div><div class='gd-ex-line'>・<span class='gd-jp'>知っているくせに、教えてくれない。</span>(Padahal tahu, tapi tidak mau memberi tahu aku)</div><div class='gd-ex-line'>・<span class='gd-jp'>行くって言ったくせに、来なかった。</span>(Katanya mau pergi, tapi ternyata tidak datang)</div><div class='gd-ex-line'>・<span class='gd-jp'>下手なくせに、いつも自慢する。</span>(Padahal payah, tapi selalu pamer)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものくせに、生意気なことを言うな。</span>(Masih anak kecil, jangan ngomong sok pintar begitu)</div><div class='gd-sec'><span class='gd-tag'>Kalimat menggantung</span>Bagian belakang tidak diucapkan, langsung berhenti di くせに. Nadanya sering terdengar manja atau menggoda.</div><div class='gd-ex-line'>・<span class='gd-jp'>本当は好きなくせに。</span>(Padahal sebenarnya suka, kan)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata benda dan kata sifat-な <b>tidak boleh disambung dengan だ</b>: yang benar <span class='gd-jp'>子どものくせに</span> dan <span class='gd-jp'>下手なくせに</span>, bukan 「子どもだくせに」 atau 「下手だくせに」.<br>・Subjek di bagian depan dan belakang harus <b>orang yang sama</b>. \"Dia padahal tahu, tapi <b>dia</b> tidak mau bilang\" boleh. Kalau subjeknya beda, くせに tidak bisa dipakai.<br>・Nadanya keras, hampir seperti memarahi orang. <b>Jangan dipakai ke atasan, pelanggan, atau orang yang lebih tua</b>, dan tidak cocok untuk dokumen resmi.<br>・Biasanya dipakai untuk menegur orang lain. Kalau dipakai untuk diri sendiri, artinya menyindir diri sendiri: <span class='gd-jp'>日本人のくせに、漢字が苦手なんです。</span>(Padahal orang Jepang, aku kurang jago kanji)</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasinya sama: dia padahal tahu jawabannya, tapi tidak memberi tahu aku.<br><b>くせに</b>＝kesal, menyalahkan dia: <span class='gd-jp'>彼は知っているくせに、教えてくれない。</span><br><b>のに</b>＝merasa heran atau sayang, nadanya lebih netral: <span class='gd-jp'>彼は知っているのに、教えてくれない。</span><br><b>にもかかわらず</b>＝formal, tulisan, tanpa emosi: <span class='gd-jp'>彼は事情を知っているにもかかわらず、説明しなかった。</span>(Padahal dia paham situasinya, dia tidak menjelaskan)</div><div class='gd-sec'>のに bisa dipakai di lebih banyak situasi. Dua kasus berikut tidak bisa memakai くせに:<br>Subjek depan dan belakang berbeda: <span class='gd-jp'>雨なのに、彼は出かけた。</span>(Padahal hujan, dia tetap pergi keluar)<br>Menyatakan penyesalan sendiri tanpa menyalahkan siapa pun: <span class='gd-jp'>一生懸命勉強したのに、落ちた。</span>(Sudah belajar mati-matian, tapi tetap gagal)</div><div class='gd-warn'>Trik cepat: kalau mau <b>menegur seseorang</b>, pakai くせに. Kalau hanya merasa <b>sayang atau heran</b>, pakai のに. Untuk <b>situasi formal</b>, tulis にもかかわらず.</div>","n2-14":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜一方で」mirip dengan <b>\"di satu sisi ..., di sisi lain ...\"</b>. Dua hal diletakkan berdampingan: satu sisi A, sisi lain B. Sering dipakai di berita, laporan, dan artikel, dengan nada yang cukup formal.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Membandingkan dua sisi</span>Satu hal punya sisi baik dan buruk, atau dua orang atau tempat berada dalam keadaan yang berlawanan. Letakkan keduanya berdampingan untuk dibandingkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は大変な一方で、やりがいもある。</span>(Pekerjaan ini berat, tapi di sisi lain juga memuaskan)</div><div class='gd-ex-line'>・<span class='gd-jp'>都市部の人口が増える一方で、地方の人口は減っている。</span>(Penduduk kota bertambah, sementara penduduk daerah berkurang)</div><div class='gd-ex-line'>・<span class='gd-jp'>兄はスポーツが得意な一方で、弟は本を読むのが好きだ。</span>(Kakaknya jago olahraga, sedangkan adiknya suka membaca buku)</div><div class='gd-sec'><span class='gd-tag'>Melakukan dua hal sekaligus</span>Seseorang melakukan A dan juga B. Di sini tidak ada arti \"berlawanan\", hanya menunjukkan bahwa dia mengurus kedua sisi.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は会社で働く一方で、週末は小説を書いている。</span>(Dia bekerja di kantor, dan di akhir pekan juga menulis novel)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中先生は研究を続ける一方で、学生の指導にも力を入れている。</span>(Pak Tanaka terus meneliti, dan juga sungguh-sungguh membimbing mahasiswa)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di bagian depan taruh 「普通形」, yaitu bentuk biasa tanpa ます/です. Kata kerja dan kata sifat-い disambung langsung, tapi <b>kata sifat-な dan kata benda perlu hati-hati</b>.<br>Kata kerja: <span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増える一方で</span></span>, bentuk lampau juga bisa: <span class='gd-pair'><span class='gd-jp'>伸びた</span> → <span class='gd-jp'>伸びた一方で</span></span><br>Kata sifat-い: <span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しい一方で</span></span><br>Kata sifat-な: pertahankan 「な」: <span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な一方で</span></span> (bisa juga <span class='gd-jp'>便利である一方で</span>)<br>Kata benda: tambahkan 「である」: <span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生である一方で</span></span><br>「で」boleh dihilangkan sehingga hanya 「一方」, dan terasa lebih seperti bahasa tulisan.</div><div class='gd-sec'>Bentuk ini juga bisa berdiri sendiri di awal kalimat dengan arti \"di sisi lain\": <span class='gd-jp'>その一方で</span>、<span class='gd-jp'>一方、</span>。</div><div class='gd-ex-line'>・<span class='gd-jp'>給料は上がった。その一方で、残業も増えた。</span>(Gajinya naik. Tapi di sisi lain, lemburnya juga bertambah)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata sifat-な tidak boleh disambung dengan だ: 「便利だ一方で」 itu salah, yang benar <span class='gd-jp'>便利な一方で</span>. Kata benda juga sama: bukan 「学生だ一方で」, tapi <span class='gd-jp'>学生である一方で</span>.<br>・Bentuk ini sangat formal. Kalau ngobrol dengan teman dan bilang 「仕事は大変な一方で…」, kedengarannya seperti membacakan siaran pers. Dalam percakapan sehari-hari cukup pakai <span class='gd-jp'>けど</span>: <span class='gd-jp'>仕事は大変だけど、楽しいよ。</span>(Kerjaannya capek, tapi seru lho)<br>・<b>Kalau 「一方」 ditaruh di akhir kalimat menjadi 「一方だ」, artinya sama sekali berbeda</b>. Lihat di bawah.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama soal jumlah penduduk:<br><b>一方で (di tengah kalimat)</b>＝membandingkan dua sisi</div><div class='gd-ex-line'>・<span class='gd-jp'>都市の人口は増える一方で、地方は減っている。</span>(Penduduk kota bertambah, sedangkan di daerah berkurang)</div><div class='gd-sec'><b>一方だ (di akhir kalimat)</b>＝terus berubah ke satu arah saja</div><div class='gd-ex-line'>・<span class='gd-jp'>都市の人口は増える一方だ。</span>(Penduduk kota terus bertambah)</div><div class='gd-sec'>Di depan 一方だ hanya bisa ditaruh kata kerja yang menyatakan \"perubahan\", seperti <span class='gd-jp'>増える</span>, <span class='gd-jp'>減る</span>, <span class='gd-jp'>悪くなる</span>, dan kebanyakan menuju arah yang tidak baik.</div><div class='gd-sec'><b>ばかりだ (perubahan)</b> artinya hampir sama dengan 一方だ, tapi lebih condong ke \"makin lama makin buruk\", sering dengan nuansa khawatir atau pasrah.</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなるばかりだ。</span>(Penyakit ayah terus memburuk)</div><div class='gd-warn'>Trik cepat: kalau setelah 「一方」 masih ada lanjutan dan sedang membandingkan dua hal, itu 一方で. Kalau 「一方」 ada di akhir dan kalimatnya selesai di situ, itu 一方だ yang artinya \"terus ～\".</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>一方で hanya menaruh dua hal berdampingan untuk dibandingkan. Kalau kamu mau bilang \"meskipun A, ternyata B\" dengan nuansa berbeda dari yang diharapkan, lanjut belajar <span class='gd-jp'>〜ものの</span> dan <span class='gd-jp'>〜にもかかわらず</span>.</div>","n2-20":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に限らず」artinya <b>「bukan hanya ～」「tidak terbatas pada ～」</b>. Di depan, kamu taruh hal yang biasanya langsung terpikir oleh semua orang. Lalu di belakang kamu bilang: sebenarnya cakupannya lebih luas, yang lain juga sama.<br>Seperti dalam bahasa Indonesia: “Bukan cuma akhir pekan, hari biasa pun ramai.” Dalam bahasa Jepang jadinya <span class='gd-jp'>週末に限らず、平日も混んでいる。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan taruh <b>kata benda</b>, lalu sambung langsung dengan 「に限らず」.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生に限らず</span></span>（bukan hanya pelajar）<br><span class='gd-pair'><span class='gd-jp'>日本</span> → <span class='gd-jp'>日本に限らず</span></span>（bukan hanya Jepang）<br>「限らず」dibaca <b>かぎらず</b>, artinya “tidak dibatasi pada”. Di paruh kalimat berikutnya sering muncul kata seperti <span class='gd-jp'>も</span>、<span class='gd-jp'>誰でも</span>、<span class='gd-jp'>何でも</span> yang memperluas cakupan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Cakupannya lebih luas dari dugaanmu</span>Orang mengira hanya A yang begitu, padahal B dan C juga.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は週末に限らず、平日もいつも混んでいる。</span>（Toko ini bukan hanya akhir pekan, hari biasa pun selalu ramai）</div><div class='gd-ex-line'>・<span class='gd-jp'>この公園は子どもに限らず、大人にも人気がある。</span>（Taman ini bukan hanya disukai anak-anak, orang dewasa juga suka）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に限らず、アジア全体で少子化が進んでいる。</span>（Bukan hanya Jepang, seluruh Asia mengalami penurunan angka kelahiran）</div><div class='gd-sec'><span class='gd-tag'>Tanpa batasan, siapa saja boleh</span>Sering muncul di pengumuman dan keterangan acara.</div><div class='gd-ex-line'>・<span class='gd-jp'>学生に限らず、誰でも参加できます。</span>（Tidak terbatas untuk pelajar, siapa saja boleh ikut）</div><div class='gd-h'>Yang sering keliru</div><div class='gd-warn'>・<b>Artinya berlawanan dengan 「に限り」「に限って」</b>: <span class='gd-jp'>本日に限り半額</span> artinya “setengah harga hanya hari ini”, sedangkan <span class='gd-jp'>本日に限らず</span> artinya “bukan hanya hari ini”. Hanya dengan tambahan 「ず」, artinya berbalik total, jadi hati-hati saat membaca pengumuman.<br>・Di depan pada dasarnya kata benda. Kata kerja tidak bisa langsung disambung: kamu tidak bisa bilang 「食べるに限らず」. Kalau mau membicarakan tindakan, 「〜ばかりでなく」 lebih natural.<br>・Nuansanya cukup formal dan tertulis, sering dipakai di berita, pengumuman, dan esai. Saat ngobrol dengan teman, cukup pakai <span class='gd-jp'>〜だけじゃなくて</span>.<br>・Yang ditaruh di depan sebaiknya “hal yang memang langsung terpikir oleh semua orang”, baru di belakang “hal yang sebenarnya juga termasuk”. Kalau urutannya terbalik, kalimatnya jadi aneh.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>に限らず</b> = di depan ada <b>satu hal yang konkret</b>, artinya “bukan hanya itu”:<br><span class='gd-jp'>学生に限らず、社会人も参加できる。</span>（Bukan hanya pelajar, pekerja juga boleh ikut）<br><b>を問わず</b> = di depan ada <b>kategori yang bisa dibagi jadi beberapa jenis</b>, artinya “apa pun jenisnya”:<br><span class='gd-jp'>このイベントは年齢を問わず、誰でも参加できる。</span>（Acara ini tanpa memandang usia, siapa saja boleh ikut）<br>「年齢」bisa dibagi menjadi berbagai usia, jadi pakai を問わず; 「学生」adalah satu kelompok yang konkret, jadi pakai に限らず.</div><div class='gd-warn'>Trik membedakan: kalau bagian depan bisa diganti dengan “apa pun ○○-nya” (年齢、性別、国籍、経験、天候), pakai を問わず. Kalau bagian depan adalah satu orang/hal/benda yang konkret (学生、日本、週末), pakai に限らず.</div><div class='gd-sec'><b>とは限らない</b>: ini juga memakai 「限」, tetapi ditaruh di akhir kalimat dan artinya <b>“belum tentu”</b>: <span class='gd-jp'>高い物がいい物とは限らない。</span>（Barang mahal belum tentu bagus）. Ini sama sekali berbeda dari “bukan hanya ～”.</div><div class='gd-sec'>Selain itu, <span class='gd-jp'>のみならず</span> dan <span class='gd-jp'>ばかりでなく</span> juga berarti “bukan hanya ～, tetapi juga ～”, dan kalau di depannya kata benda, sering bisa saling menggantikan dengan に限らず. Bedanya, に限らず hanya bisa disambung dengan kata benda, dan titik beratnya pada “cakupannya tidak terbatas di sini”.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Lanjutkan dengan <span class='gd-jp'>〜を問わず</span> (tanpa memandang ～), lalu <span class='gd-jp'>〜のみならず</span> dan <span class='gd-jp'>〜ばかりか</span> yang juga berarti “bukan hanya ～”. Dengan begitu, satu kelompok pola tentang “cakupan” ini beres sekaligus.</div>","n2-21":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を問わず」artinya <b>“tanpa memandang ～” “tidak peduli ～”</b>. <span class='gd-jp'>問う</span> artinya “menanyakan, mempermasalahkan”, jadi <span class='gd-jp'>問わず</span> berarti “tidak mempermasalahkan”. Di iklan lowongan kerja sering ada tulisan “usia bebas, pengalaman tidak diwajibkan”; dalam bahasa Jepang jadinya <span class='gd-jp'>年齢を問わず</span>、<span class='gd-jp'>経験を問わず</span>. Maksudnya, apa pun kondisi itu, hasilnya sama saja.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Rekrutmen・pengumuman</span>Paling sering muncul di lowongan kerja, pendaftaran acara, dan pengumuman toko, untuk bilang “syarat ini tidak dibatasi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢を問わず、どなたでもご参加いただけます。</span>（Tanpa memandang usia, siapa saja boleh ikut）</div><div class='gd-ex-line'>・<span class='gd-jp'>このアルバイトは経験を問わず、誰でも応募できます。</span>（Kerja paruh waktu ini tidak mensyaratkan pengalaman, siapa saja boleh melamar）</div><div class='gd-sec'><span class='gd-tag'>Menggambarkan keadaan</span>Menyatakan bahwa sesuatu tidak terpengaruh kondisi, dan berlaku dalam keadaan apa pun.</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌は世代を問わず愛されている。</span>（Lagu ini disukai semua generasi）</div><div class='gd-ex-line'>・<span class='gd-jp'>昼夜を問わず、工事の音がうるさい。</span>（Siang maupun malam, suara pembangunannya berisik）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Tambahkan <span class='gd-jp'>を問わず</span> langsung setelah kata benda. Kata benda di depannya ada dua macam:<br><b>Kata yang memang punya banyak jenis</b>: <span class='gd-jp'>年齢</span>、<span class='gd-jp'>性別</span>、<span class='gd-jp'>国籍</span>、<span class='gd-jp'>経験</span>、<span class='gd-jp'>天候</span><br><b>Pasangan kata yang berlawanan</b>: <span class='gd-jp'>男女</span>、<span class='gd-jp'>昼夜</span>、<span class='gd-jp'>経験の有無</span>（ada atau tidaknya pengalaman）<br>Bisa juga disambung dengan 「〜かどうか」: <span class='gd-pair'><span class='gd-jp'>経験があるかどうか</span> → <span class='gd-jp'>経験があるかどうかを問わず</span></span></div><div class='gd-h'>Bentuk yang paling sering muncul</div><div class='gd-sec'><span class='gd-tag'>は問いません</span>Ditaruh di akhir kalimat, sangat umum di iklan lowongan kerja.</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢は問いません。</span>（Usia bebas）</div><div class='gd-sec'><span class='gd-tag'>を dihilangkan</span>Di poster dan pengumuman lowongan, supaya singkat sering ditulis <span class='gd-jp'>年齢問わず</span>、<span class='gd-jp'>経験問わず</span>.</div><div class='gd-h'>Yang sering keliru</div><div class='gd-warn'>・Di depan harus ada kata yang “punya berbagai jenis”. <span class='gd-jp'>学生を問わず</span> tidak natural, karena “pelajar” hanya satu jenis, jadi tidak ada yang bisa “dikesampingkan”. Katakan <span class='gd-jp'>学生かどうかを問わず</span>, atau <span class='gd-jp'>学生・社会人を問わず</span>.<br>・「問わず」dibaca <b>とわず</b>, bentuk negatif dari <span class='gd-jp'>問う</span>. Jangan menulisnya 問えず.<br>・Ini ungkapan tertulis yang sangat formal. Saat ngobrol dengan teman, <span class='gd-jp'>関係なく</span> lebih natural: <span class='gd-jp'>年とか関係なく、誰でも楽しめるよ。</span>（Berapa pun umurnya, siapa saja bisa menikmatinya lho）<br>・Partikelnya selalu 「を」, jangan diganti dengan に atau が.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>に限らず</b> = <b>bukan hanya A, B juga ～</b> (ambil satu contoh, lalu perluas cakupannya):<br><span class='gd-jp'>このアプリは若者に限らず、お年寄りにも人気だ。</span>（Aplikasi ini bukan hanya populer di kalangan anak muda, tetapi juga di kalangan lansia）<br><b>を問わず</b> = <b>apa pun jenis A-nya, hasilnya sama</b> (syarat itu sama sekali tidak dipertimbangkan):<br><span class='gd-jp'>このアプリは年齢を問わず人気だ。</span>（Aplikasi ini populer di segala usia）</div><div class='gd-sec'>Selain itu, <span class='gd-jp'>にかかわらず</span> artinya hampir sama dengan を問わず: <span class='gd-jp'>天候にかかわらず実施します。</span>（Acara tetap dilaksanakan bagaimanapun cuacanya）<br>Kalau di tengahnya ditambah 「も」 jadi <b>にもかかわらず</b>, artinya sama sekali lain, yaitu “meskipun ～, tetap ～”: <span class='gd-jp'>雨にもかかわらず、たくさんの人が来た。</span>（Meskipun hujan, banyak orang tetap datang）</div><div class='gd-warn'>Trik membedakan: “bukan hanya A, B juga” pakai に限らず; “apa pun A-nya” pakai を問わず; “meskipun A, tetap ～” pakai にもかかわらず.</div>","n2-22":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にわたって」kira-kira sama seperti <b>「selama…」「sepanjang…」「meliputi…」「di seluruh…」</b> yang sering kamu dengar di berita. Misalnya \"hujan deras turun selama tiga hari\" atau \"pemadaman listrik meliputi seluruh Taiwan\". Intinya menekankan <b>waktu yang panjang atau cakupan yang luas</b>, dan semuanya tercakup dari awal sampai akhir, dari ujung ke ujung.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda ＋ にわたって. Kata benda di depannya harus berupa <b>rentang waktu/panjang</b> atau <b>wilayah yang luas</b>. Ada tiga jenis yang paling umum:</div><div class='gd-sec'><span class='gd-tag'>Waktu yang panjang</span>3日間、10年、長年、長期間</div><div class='gd-ex-line'>・<span class='gd-jp'>会議は5時間にわたって続いた。</span>(Rapatnya berlangsung selama lima jam penuh)</div><div class='gd-sec'><span class='gd-tag'>Wilayah yang luas</span>全国、広範囲、関東全域、多方面</div><div class='gd-ex-line'>・<span class='gd-jp'>台風の影響で、関東全域にわたって大雨が降った。</span>(Akibat topan, hujan deras turun di seluruh wilayah Kanto)</div><div class='gd-sec'><span class='gd-tag'>Jumlah kali・volume</span>3回、数ページ</div><div class='gd-ex-line'>・<span class='gd-jp'>この特集は3回にわたって放送されます。</span>(Liputan khusus ini akan ditayangkan dalam tiga episode)</div><div class='gd-h'>Bentuk yang paling sering kamu temui</div><div class='gd-sec'><b>にわたり</b>: artinya sama, tapi lebih formal. Sering dipakai di siaran pers dan pengumuman.</div><div class='gd-ex-line'>・<span class='gd-jp'>調査は全国にわたり実施された。</span>(Survei dilakukan di seluruh negeri)</div><div class='gd-sec'><b>にわたる＋kata benda</b>: kalau mau langsung menyambung ke kata benda, pakai bentuk ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>長年にわたる研究の成果が発表された。</span>(Hasil penelitian selama bertahun-tahun dipublikasikan)</div><div class='gd-sec'><b>にわたった＋kata benda</b>: untuk hal yang sudah selesai.</div><div class='gd-ex-line'>・<span class='gd-jp'>2時間にわたった話し合いは、結論が出ないまま終わった。</span>(Diskusi yang berlangsung dua jam itu berakhir tanpa kesimpulan)</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Di depannya tidak boleh ada <b>titik waktu</b> atau <b>satu tempat saja</b>. Kamu tidak bisa bilang 「3時にわたって」atau 「月曜日にわたって」. Yang dibutuhkan adalah \"satu rentang\" atau \"satu wilayah luas\", seperti <span class='gd-jp'>3時間</span>、<span class='gd-jp'>1週間</span>、<span class='gd-jp'>全国</span>.<br>・Ungkapan ini terkesan \"sangat lama, sangat luas\", jadi kalau dipakai untuk hal sepele akan terdengar aneh. <span class='gd-jp'>10分にわたってシャワーを浴びた</span> terdengar seperti pembaca berita yang melaporkan kamu mandi.<br>・Nuansanya cukup formal, sering muncul di berita, laporan, dan pengumuman. Kalau ngobrol dengan teman, <span class='gd-jp'>3日間ずっと雨だった</span> (hujan terus selama tiga hari) terdengar jauh lebih natural.<br>・Kalau langsung diikuti kata benda, pakai <b>にわたる</b>: bilang <span class='gd-jp'>3時間にわたる会議</span>, jangan 「3時間にわたって会議」.<br>・Tata bahasa ini berasal dari kata kerja <span class='gd-jp'>渡る</span>, jadi kadang kamu akan melihatnya ditulis 「に渡って」, tapi kebanyakan ditulis dengan hiragana.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Yang paling mudah tertukar adalah <b>〜にかけて</b>. Keduanya membahas cakupan, tapi sudut pandangnya berbeda.<br><b>にかけて</b>: menyebut <b>dari mana sampai mana</b>. Yang diberikan adalah titik awal dan titik akhir, dengan cakupan yang kira-kira saja.<br><div class='gd-ex-line'>・<span class='gd-jp'>3月から5月にかけて工事が行われる。</span>(Pembangunan akan dilakukan kira-kira dari Maret sampai Mei)</div><b>にわたって</b>: menyebut <b>total seberapa panjang, seberapa luas</b>, dengan penekanan pada panjang dan luasnya.<br><div class='gd-ex-line'>・<span class='gd-jp'>3か月にわたって工事が行われる。</span>(Pembangunan akan berlangsung selama tiga bulan penuh)</div>Untuk tempat juga sama: <span class='gd-jp'>九州から関西にかけて雨が降る</span> (hujan akan turun dari Kyushu sampai sekitar Kansai) menjelaskan batas wilayahnya; sedangkan <span class='gd-jp'>西日本全域にわたって雨が降る</span> (hujan akan turun di seluruh Jepang Barat) menekankan betapa luas wilayahnya.</div><div class='gd-warn'>Trik cepat: kalau di kalimat ada dua ujung \"A から B\", biasanya pakai にかけて. Kalau di depannya hanya ada satu \"total panjang\" atau \"satu wilayah utuh\", seperti <span class='gd-jp'>3か月</span>、<span class='gd-jp'>全国</span>, pakai にわたって.</div>","n2-23":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜をもとに」kira-kira sama seperti <b>「berdasarkan～」「dengan ～ sebagai dasar」「bersumber dari～」</b>. Yang ada di depan adalah <b>bahan atau titik awal</b>, dan yang ada di belakang adalah <b>sesuatu yang baru yang kamu buat</b> dari bahan itu. Contohnya \"film yang diadaptasi dari kisah nyata\" atau \"kari yang dibuat dengan mengacu pada resep nenek\". Nuansanya seperti itu.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya harus <b>kata benda</b>, lalu tambahkan <span class='gd-jp'>をもとに</span> atau <span class='gd-jp'>をもとにして</span>. Artinya sama, hanya saja versi dengan して terasa sedikit lebih lengkap.<br><span class='gd-pair'><span class='gd-jp'>データ</span> → <span class='gd-jp'>データをもとに</span></span> (berdasarkan data)<br>Kalau mau langsung menyambung ke kata benda, ubah jadi <b>をもとにした＋kata benda</b>:<br><span class='gd-pair'><span class='gd-jp'>実話</span> → <span class='gd-jp'>実話をもとにした映画</span></span> (film yang diadaptasi dari kisah nyata)</div><div class='gd-h'>Bentuk yang paling sering kamu temui</div><div class='gd-sec'><span class='gd-tag'>をもとに＋tindakan</span>Di belakangnya sering muncul kata kerja yang menghasilkan sesuatu, seperti \"membuat, menulis, memikirkan, memutuskan, memprediksi\".</div><div class='gd-ex-line'>・<span class='gd-jp'>アンケートの結果をもとに、新しいメニューを考えた。</span>(Berdasarkan hasil kuesioner, aku memikirkan menu baru)</div><div class='gd-ex-line'>・<span class='gd-jp'>祖母のレシピをもとにして、カレーを作ってみた。</span>(Dengan resep nenek sebagai dasar, aku coba membuat kari)</div><div class='gd-sec'><span class='gd-tag'>をもとに作られた</span>Sangat umum dipakai untuk menjelaskan sumber sebuah karya.</div><div class='gd-ex-line'>・<span class='gd-jp'>このドラマは人気漫画をもとに作られた。</span>(Drama ini dibuat berdasarkan manga populer)</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Kalau ditulis dengan kanji, jadi <span class='gd-jp'>基に</span> atau <span class='gd-jp'>元に</span>, dan dibaca <b>もとに</b>, jangan dibaca 「きに」. Ditulis dengan hiragana sehari-hari juga sama sekali tidak masalah.<br>・Di depannya hanya boleh kata benda. Kalau mau memasukkan satu kalimat, ubah dulu jadi kata benda dengan 「こと」: <span class='gd-jp'>調べたことをもとに、レポートを書いた。</span> (Aku menulis laporan berdasarkan hal yang sudah kucari tahu)<br>・\"Menurut laporan cuaca, besok akan hujan\", yaitu \"menurut\" untuk <b>menyebut sumber informasi</b>, tidak memakai をもとに dalam bahasa Jepang, melainkan <span class='gd-jp'>によると</span>: <span class='gd-jp'>天気予報によると、明日は雨だそうだ。</span><br>・Di belakangnya harus ada tindakan atau hasil seperti \"membuat/memikirkan/memutuskan\". Kalimat yang hanya bermakna \"ada di sana\" atau \"suka\" tidak bisa dipasangkan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>をもとに</b> ＝ dipakai sebagai <b>bahan atau titik awal</b>, yang setelahnya boleh diolah, dikembangkan, atau diadaptasi:<br><span class='gd-jp'>このデータをもとに、新しい企画を考えた。</span> (Dengan data ini sebagai titik awal, aku memikirkan rencana baru)<br><b>に基づいて</b> ＝ <b>mengikuti</b> suatu dasar tanpa menyimpang darinya:<br><span class='gd-jp'>このデータに基づいて、結論を出した。</span> (Berdasarkan data ini, aku menarik kesimpulan)<br>Untuk menilai sesuatu sesuai hukum atau aturan, <span class='gd-jp'>法律に基づいて判断する</span> lebih natural dan formal. をもとに lebih menekankan \"memakai sesuatu sebagai bahan lalu membuat sesuatu\", jadi kalau dipakai untuk hukum atau aturan nuansanya lebih lemah. Di situasi formal, sebaiknya pakai に基づいて.</div><div class='gd-warn'>Trik cepat: kalau hasilnya \"menjadikannya dasar lalu membuat sesuatu yang baru\", pakai をもとに. Kalau hasilnya \"mengikuti ketentuan atau bukti darinya\", pakai に基づいて.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Pola \"kata benda ＋ を ＋ 〜に\" yang sama juga ada pada <span class='gd-jp'>をきっかけに</span>, yang berarti \"dengan ～ sebagai pemicu\": <span class='gd-jp'>留学をきっかけに、料理を始めた。</span> (Berawal dari kuliah di luar negeri, aku mulai memasak). Di depannya adalah \"awal dari suatu peristiwa\", bukan \"bahan\", jadi bisa kamu hafalkan sambil membandingkan keduanya.</div>","n2-24":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に応じて」artinya <b>“menyesuaikan dengan ~”</b> atau <b>“tergantung ~”</b>. Bayangkan pemilik toko bento yang “menentukan jumlah bento yang dipesan sesuai jumlah orang”: kalau hal di depannya berbeda, cara di belakangnya juga <b>ikut menyesuaikan</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Langsung dipasang setelah kata benda: <span class='gd-pair'><span class='gd-jp'>収入</span> → <span class='gd-jp'>収入に応じて</span></span> (sesuai pendapatan)<br>Kata benda di depannya biasanya hal yang <b>berbeda-beda tergantung orang atau situasi</b>, misalnya pendapatan, usia, kemampuan, tingkat, anggaran, kondisi, dan kebutuhan.<br>Cara bacanya <b>おうじて</b>. Dalam tulisan kamu juga sering menemukan <span class='gd-jp'>に応じ</span> tanpa 「て」, artinya sama saja.</div><div class='gd-ex-line'>・<span class='gd-jp'>収入に応じて、税金が決まる。</span> (Pajak ditentukan sesuai pendapatan)</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢に応じて、料金が変わります。</span> (Biayanya berubah sesuai usia)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>必要に応じて</span> artinya “sesuai kebutuhan / kalau perlu”. Sangat sering muncul di perusahaan dan pengumuman.</div><div class='gd-ex-line'>・<span class='gd-jp'>必要に応じて、資料を追加してください。</span> (Tolong tambahkan dokumen jika diperlukan)</div><div class='gd-sec'><span class='gd-tag'>に応じた＋名詞</span> Kalau di belakangnya harus langsung diikuti kata benda, inilah bentuk yang paling sering dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>レベルに応じたクラスを選べます。</span> (Kamu bisa memilih kelas yang sesuai dengan levelmu)</div><div class='gd-sec'>Ada juga pola <span class='gd-jp'>に応じての</span>＋kata benda (contoh: <span class='gd-jp'>能力に応じての配置</span>) dengan arti yang sama, tapi lebih jarang dipakai. Untuk pemula, hafalkan <span class='gd-jp'>に応じた</span> dulu saja.</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Di belakangnya harus hal yang <b>ikut menyesuaikan atau berubah</b>. Untuk sekadar berkata “menurut kabar yang kudengar”, pola ini tidak bisa dipakai: <span class='gd-jp'>ニュースによると、明日は雨だ。</span> (Menurut berita, besok hujan) Di sini harus memakai によると.<br>・Nuansanya agak formal, sering muncul di pengumuman, penjelasan, dan dunia kerja. Saat mengobrol dengan teman, kamu lebih sering mendengar <span class='gd-jp'>に合わせて</span> atau <span class='gd-jp'>によって</span>.<br>・Verba <span class='gd-jp'>応じる</span> yang dipakai sendiri sering berarti “menanggapi, menyetujui”: <span class='gd-jp'>インタビューに応じる</span> (bersedia diwawancarai). Jangan dicampuradukkan dengan arti “menyesuaikan dengan ~”.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama membicarakan pendapatan dan pajak:<br><b>に応じて</b> = <b>menyesuaikan</b> dengan hal di depannya: <span class='gd-jp'>収入に応じて、税金が決まる。</span> (Pajak ditentukan sesuai pendapatan)<br><b>によって</b> = <b>berbeda</b> karena hal di depannya, fokusnya pada “tidak sama”: <span class='gd-jp'>収入によって、税金が違う。</span> (Pajaknya berbeda tergantung pendapatan)<br><b>につれて</b> = hal di depan terus berubah, hal di belakang juga <b>ikut berubah pelan-pelan</b>: <span class='gd-jp'>収入が増えるにつれて、税金も増える。</span> (Semakin besar pendapatan, pajaknya juga ikut naik)</div><div class='gd-sec'>Kalau tidak ada pihak yang “menyesuaikan”, によって terdengar lebih alami: <span class='gd-jp'>国によって、習慣が違う。</span> (Kebiasaan berbeda di tiap negara) Kalau kalimat ini diganti に応じて, jadinya terasa aneh.</div><div class='gd-warn'>Trik cepat: “menyesuaikan dengannya” pakai に応じて, “berbeda karenanya” pakai によって, “semakin ~ semakin ~” pakai につれて.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Pola lain yang juga berarti “ikut berubah” adalah <span class='gd-jp'>〜に伴って</span> (seiring dengan ~) dan <span class='gd-jp'>〜につれて</span>. Coba pelajari dan bandingkan ketiganya sekaligus.</div>","n2-27":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜のみならず」adalah versi formal dari <b>“tidak hanya ~, tetapi juga …”</b>. Artinya sama dengan 「<span class='gd-jp'>だけでなく</span>」yang sudah kamu kenal, tapi pola ini dipakai di <b>laporan, berita, dan pidato</b>. Kamu tidak akan mengucapkannya saat mengobrol dengan teman.<br>Kalau dipecah jadi mudah dipahami: <span class='gd-jp'>のみ</span> = <span class='gd-jp'>だけ</span> (hanya), <span class='gd-jp'>ならず</span> = “tidak”, jadi gabungannya “bukan hanya A”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menambah</span> Sebut A dulu, lalu tambahkan B, dan B biasanya cakupannya lebih besar atau lebih luas. Di kalimat belakang sering ada <b>も、でも、にも</b> yang artinya “B juga”.</div><div class='gd-ex-line'>・<span class='gd-jp'>国内のみならず、海外でも高い評価を得ている。</span> (Tidak hanya di dalam negeri, di luar negeri pun mendapat penilaian yang tinggi)</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は学生のみならず、社会人にも人気がある。</span> (Toko ini tidak hanya disukai pelajar, pekerja kantoran pun menyukainya)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b>: langsung disambung. <span class='gd-pair'><span class='gd-jp'>日本</span> → <span class='gd-jp'>日本のみならず</span></span><br><b>Verba dan kata sifat-い</b>: pakai bentuk biasa (bentuk kamus, bentuk た, atau bentuk ない) lalu langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるのみならず</span></span><span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いのみならず</span></span><br><b>Kata sifat-な</b>: harus ditambah <b>である</b>, tidak boleh pakai 「だ」. <span class='gd-pair'><span class='gd-jp'>静かだ</span> → <span class='gd-jp'>静かであるのみならず</span></span><br>Kata benda juga boleh ditambah である kalau ingin menekankan “status atau sifat”: <span class='gd-jp'>医者であるのみならず</span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼は英語が話せるのみならず、中国語も読める。</span> (Dia tidak hanya bisa berbicara bahasa Inggris, tetapi juga bisa membaca bahasa Mandarin)</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は狭いのみならず、駅からも遠い。</span> (Kamar ini tidak hanya sempit, tetapi juga jauh dari stasiun)</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は静かであるのみならず、交通も便利だ。</span> (Kota ini tidak hanya tenang, tetapi transportasinya juga mudah)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ただ〜のみならず</span> Dengan menambahkan 「ただ」di depan, artinya jadi “bukan sekadar ~” dan nuansanya lebih kuat.</div><div class='gd-ex-line'>・<span class='gd-jp'>これはただ個人の問題のみならず、社会全体の問題でもある。</span> (Ini bukan sekadar masalah pribadi, tetapi juga masalah seluruh masyarakat)</div><div class='gd-sec'><span class='gd-tag'>Di awal kalimat</span> Dipakai sendiri sebagai kata sambung, artinya “bukan hanya itu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は仕事が速い。のみならず、ミスもほとんどない。</span> (Dia cepat bekerja. Bukan hanya itu, dia juga hampir tidak pernah membuat kesalahan)</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Kata sifat-な tidak boleh berbentuk <span class='gd-jp'>静かだのみならず</span>, harus <span class='gd-jp'>静かであるのみならず</span>.<br>・Pola ini kaku dan sangat formal. Kalau bilang “tidak hanya ~” ke teman, pakai <span class='gd-jp'>だけじゃなく</span>. Kalau pakai のみならず, kamu akan terdengar seperti sedang membacakan surat resmi.<br>・Pola ini bersifat <b>menambah</b>, bukan “bukan A melainkan B”. Antara A dan B harus sepadan: kalau A tempat, B juga harus tempat; kalau A masalah, B juga harus masalah. Jangan lupa menambahkan 「も」di bagian belakang.<br>・Arah maknanya juga harus sama: hal baik disambung hal baik, hal buruk disambung hal buruk. Tidak bisa dipakai untuk hal yang bertentangan.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Situasi yang sama: game ini disukai orang dewasa dan anak-anak.<br><b>だけでなく</b> = ungkapan paling umum, bisa dipakai dalam percakapan maupun tulisan: <span class='gd-jp'>このゲームは子どもだけでなく、大人にも人気がある。</span><br><b>のみならず</b> = artinya sama, tapi nuansanya formal dan tertulis: <span class='gd-jp'>このゲームは子どものみならず、大人にも人気がある。</span><br><b>ばかりか</b> = ada nuansa kaget, seperti “tak disangka, bahkan ~ pun”: <span class='gd-jp'>このゲームは子どもばかりか、大人まで夢中になっている。</span> (Bukan hanya anak-anak, orang dewasa pun sampai kecanduan)<br><b>に限らず</b> = fokusnya “tidak terbatas pada A”, dan kalimat belakang sering berpasangan dengan <span class='gd-jp'>誰でも</span> atau <span class='gd-jp'>どこでも</span>: <span class='gd-jp'>このゲームは子どもに限らず、誰でも楽しめる。</span> (Game ini tidak terbatas untuk anak-anak, siapa pun bisa menikmatinya)</div><div class='gd-warn'>Trik cepat: untuk mengobrol pakai だけじゃなく, untuk tulisan pakai のみならず; kalau ingin menyampaikan rasa kaget “bahkan ~ pun” pakai ばかりか; kalau ingin bilang “tanpa batas, siapa pun boleh” pakai に限らず.</div>","n2-31":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜に値する」artinya <b>「layak ～ / patut ～」</b>, dengan nuansa yang lebih formal dan khas bahasa tulis. Berita menulis \"temuan ini patut diperhatikan\", resensi menulis \"buku ini layak dibaca\", nah, di bahasa Jepang kamu akan menemukan pola ini. Maknanya: orang atau hal ini <b>pantas dan punya nilai itu</b>, jadi memang layak mendapat penilaian tersebut.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋に値する：<span class='gd-pair'><span class='gd-jp'>尊敬</span> → <span class='gd-jp'>尊敬に値する</span></span>（patut dihormati）<br>Kata kerja bentuk kamus (bentuk dasar yang kamu temukan di kamus)＋に値する：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読むに値する</span></span>（layak dibaca）<br><span class='gd-jp'>値する</span> dibaca <b>あたいする</b>. Ini kata kerja, jadi perubahannya sama seperti <span class='gd-jp'>する</span>：<span class='gd-jp'>値しない</span>、<span class='gd-jp'>値します</span>。</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Penilaian positif</span>Kata yang paling sering ditaruh di depannya：<span class='gd-jp'>尊敬</span>、<span class='gd-jp'>称賛</span>、<span class='gd-jp'>信頼</span>、<span class='gd-jp'>注目</span>、<span class='gd-jp'>一読</span>、<span class='gd-jp'>検討</span>、<span class='gd-jp'>特筆</span>。Hafalkan saja pasangan ini sebagai kolokasi tetap.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の努力は称賛に値する。</span>（Usahanya patut dipuji）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は一読に値する。</span>（Buku ini layak dibaca）</div><div class='gd-ex-line'>・<span class='gd-jp'>このデータは注目に値する。</span>（Data ini patut diperhatikan）</div><div class='gd-sec'><span class='gd-tag'>Negatif: tidak layak</span>Kalau diganti jadi <span class='gd-jp'>値しない</span>, nadanya sangat ketus, kira-kira \"sama sekali tidak layak digubris\".</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな噂は信じるに値しない。</span>（Gosip seperti itu tidak layak dipercaya）</div><div class='gd-ex-line'>・<span class='gd-jp'>その意見は検討に値しない。</span>（Pendapat itu tidak layak dipertimbangkan）</div><div class='gd-sec'><span class='gd-tag'>Di depan kata benda</span>Dipakai langsung untuk menerangkan orang atau benda.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は信頼に値する人物だ。</span>（Dia orang yang layak dipercaya）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Partikelnya selalu <b>に</b>：yang benar <span class='gd-jp'>尊敬に値する</span>, bukan 尊敬を値する。<br>・Bacanya <b>あたいする</b>. 「値」di <span class='gd-jp'>値段</span> dibaca ね, jangan tertukar.<br>・Bentuk ます tidak bisa dipasang di depannya: tidak boleh bilang 「読みますに値する」. Kalau mau sopan, ubah bagian paling belakang: <span class='gd-jp'>読むに値します</span>。<br>・Pola ini kaku dan sangat bahasa tulis. Waktu ngobrol dengan teman, \"ramen ini layak dicoba\" cukup bilang <span class='gd-jp'>このラーメン、食べる価値あるよ</span>; kalau bilang 食べるに値する, kedengarannya seperti sedang menulis ulasan kuliner.<br>・Dalam bahasa Indonesia, \"worth it\" atau \"sepadan\" sering dipakai untuk soal untung atau hemat, misalnya \"Sudah diskon, worth it banget\". Untuk arti seperti ini bahasa Jepang memakai <span class='gd-jp'>お得</span>, bukan に値する。</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>価値がある</b>：artinya hampir sama dengan に値する, tapi bisa dipakai di percakapan sehari-hari maupun tulisan, dan ini yang paling sering diucapkan.<br><span class='gd-jp'>この本は読む価値がある。</span>（Buku ini layak dibaca: bisa dipakai saat ngobrol）<br><span class='gd-jp'>この本は一読に値する。</span>（Buku ini layak sekali dibaca: untuk resensi atau situasi formal）</div><div class='gd-sec'><b>だけのことはある</b>：sama-sama memuji, tapi intinya adalah \"<b>pantas saja ～ / memang layak ～</b>\", yaitu hasilnya sesuai dengan latar belakang dan kerja kerasnya. Dalam situasi yang sama, setelah mendengar pertunjukan piano:<br><span class='gd-jp'>彼の演奏は称賛に値する。</span>（Permainannya patut dipuji: pertunjukan ini memang layak mendapat pujian）<br><span class='gd-jp'>さすが十年ウィーンで学んだだけのことはある。</span>（Pantas saja, dia belajar sepuluh tahun di Wina: hasil bagusnya sesuai dengan pengalamannya）</div><div class='gd-warn'>Kiat membedakan: untuk \"layak ～\", pakai に値する di situasi formal dan 価値がある saat bicara sehari-hari; untuk \"pantas saja ～ / memang ～\", pakai だけのことはある。</div><div class='gd-h'>Bisa dilanjutkan setelah ini</div><div class='gd-sec'>「〜に足る」di N1 maknanya sangat dekat, yaitu \"cukup untuk ～, memenuhi syarat untuk ～\"：<span class='gd-jp'>信頼に足る人物</span>（orang yang cukup layak dipercaya）。</div>","n2-32":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜上は」artinya <b>「karena sudah ～, maka (harus) ～」</b>. Di depan ditaruh hal yang sudah pasti, misalnya statusmu, keputusan yang kamu buat, atau keadaan yang sudah sampai ke titik tertentu; di belakang kamu bilang \"makanya aku akan / harus berbuat begini\". Nuansanya mirip \"Kalau sudah janji, ya harus ditepati\" dalam bahasa Indonesia, hanya saja terdengar lebih <b>formal dan kaku</b>, sering membawa kesan tekad bulat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tanggung jawab karena status</span>Karena berstatus begitu, ya harus melakukan apa yang seharusnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>教師である上は、生徒の手本にならなければならない。</span>（Karena sudah menjadi guru, harus jadi teladan bagi murid）</div><div class='gd-sec'><span class='gd-tag'>Sudah melakukan, harus bertanggung jawab</span>Karena sudah menyanggupi atau memutuskan, ya harus dijalani sampai akhir.</div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた上は、最後まで責任を持ちます。</span>（Karena sudah kuterima, aku akan bertanggung jawab sampai akhir）</div><div class='gd-ex-line'>・<span class='gd-jp'>やると決めた上は、もう迷わない。</span>（Karena sudah memutuskan untuk melakukannya, aku tidak akan ragu lagi）</div><div class='gd-sec'><span class='gd-tag'>Sudah terlanjur begini</span>Keadaan sudah menjadi seperti ini, jadi mau tidak mau dihadapi.</div><div class='gd-ex-line'>・<span class='gd-jp'>こうなった上は、正直に話すしかない。</span>（Karena sudah begini, tidak ada pilihan selain berkata jujur）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>：bentuk kamus atau bentuk た, langsung tambahkan は.<br><span class='gd-pair'><span class='gd-jp'>試合に出る</span> → <span class='gd-jp'>試合に出る上は</span></span>（karena akan ikut pertandingan）<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した上は</span></span>（karena sudah berjanji）<br><b>Kata benda</b>：di tengah harus disisipkan 「である」.<br><span class='gd-pair'><span class='gd-jp'>社会人</span> → <span class='gd-jp'>社会人である上は</span></span>（karena sudah menjadi orang dewasa yang bekerja）</div><div class='gd-h'>Apa yang harus ada di belakangnya</div><div class='gd-sec'>Bagian belakang harus berupa <b>tekadmu, kewajiban, saran, atau penilaian</b>. Akhiran yang paling sering muncul:<br><span class='gd-jp'>〜なければならない</span>（harus）、<span class='gd-jp'>〜べきだ</span>（seharusnya）、<span class='gd-jp'>〜しかない</span>（tidak ada pilihan selain）、<span class='gd-jp'>〜つもりだ</span>（berniat）、<span class='gd-jp'>〜たい</span>（ingin）。</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に出る上は、絶対に勝ちたい。</span>（Karena akan ikut pertandingan, aku pasti ingin menang）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bacanya <b>うえは</b>, bukan じょうは。<br>・Kata benda tidak bisa langsung disambung: yang benar <span class='gd-jp'>学生である上は</span>, tidak boleh bilang 「学生だ上は」。<br>・Yang di depan harus hal yang <b>sudah pasti</b>, bukan pengandaian. Kamu tidak bisa menambahkan 「もし」 seperti 「もし約束した上は」。<br>・Bagian belakang tidak boleh sekadar menyatakan fakta. Kalimat seperti 「日本に来た上は、毎日雨だった」 tidak bisa, karena \"tiap hari hujan\" bukan tekad atau penilaianmu.<br>・Nuansanya formal dan bahasa tulis, jadi kalau dipakai langsung saat ngobrol dengan teman akan terdengar kaku; untuk sehari-hari biasanya dipakai <span class='gd-jp'>からには</span>。</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>からには</b>：artinya hampir sama, yaitu \"karena sudah ～, maka ～\".<br>・<span class='gd-jp'>引き受けた上は、最後まで頑張ります。</span>（Karena sudah menerimanya, aku akan berusaha sampai akhir）<br>・<span class='gd-jp'>引き受けたからには、最後まで頑張ります。</span>（Sama seperti di atas）<br>Bedanya ada di situasi: <span class='gd-jp'>上は</span> lebih kaku, sering muncul di tulisan, pidato, atau pernyataan sikap yang sangat serius; <span class='gd-jp'>からには</span> bisa dipakai di situasi formal juga, dan lebih sering terdengar di percakapan sehari-hari.</div><div class='gd-sec'><b>上に</b>：bedanya cuma satu huruf, tapi artinya sama sekali lain, yaitu \"bukan hanya ～ tapi juga ～\".<br>・<span class='gd-jp'>この店は安い上に、おいしい。</span>（Toko ini bukan hanya murah, tapi juga enak）<br>・<span class='gd-jp'>店長である上は、遅刻はできない。</span>（Karena sudah menjadi kepala toko, tidak boleh terlambat）</div><div class='gd-warn'>Kiat membedakan: kalau di belakang \"menambah satu kelebihan atau kekurangan lagi\", pakai 上に; kalau di belakang \"makanya harus, mesti, tidak ada pilihan lain\", pakai 上は. Saat ngobrol dengan teman, untuk \"karena sudah ～\" ingat dulu からには。</div>","n2-36":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ずにはいられない」artinya <b>「tak tahan untuk ～」「tak bisa menahan diri untuk ～」</b>. Ada perasaan atau dorongan yang muncul di hati dan tidak bisa ditahan, jadi akhirnya kamu melakukannya. Arti harfiahnya kira-kira \"kalau tidak melakukan ～, rasanya tidak bisa tenang\", atau dengan kata lain \"saking tak tahannya, jadi melakukannya\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Perasaan meluap</span>Saat mendengar atau melihat sesuatu, perasaan tertentu muncul dengan sendirinya.</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌を聞くと、昔を思い出さずにはいられない。</span>（Setiap kali mendengar lagu ini, aku tak bisa tidak teringat masa lalu）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の努力には、感心せずにはいられない。</span>（Melihat usahanya yang begitu keras, aku benar-benar tak bisa tidak kagum）</div><div class='gd-sec'><span class='gd-tag'>Refleks bicara atau bertindak</span>Sebenarnya bisa saja tidak dilakukan, tapi kamu tidak bisa menahan diri.</div><div class='gd-ex-line'>・<span class='gd-jp'>困っている人を見ると、声をかけずにはいられない。</span>（Kalau melihat orang yang sedang kesulitan, aku tak tahan untuk menyapa dan bertanya）</div><div class='gd-ex-line'>・<span class='gd-jp'>あまりにひどい話で、一言言わずにはいられなかった。</span>（Ceritanya keterlaluan sekali, aku sampai tak tahan untuk berkomentar）</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'>Ubah dulu kata kerja ke bentuk 「ない」, lalu pilih salah satu versi:<br>・<b>Versi ず</b>: buang 「ない」, lalu sambung dengan <span class='gd-jp'>ずにはいられない</span><br>・<b>Versi ないで</b>: pertahankan 「ない」, lalu sambung dengan <span class='gd-jp'>ではいられない</span><br>Artinya sama saja. Versi ず lebih umum dan lebih bernuansa tulisan; versi ないで sedikit lebih santai.</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>:<br><span class='gd-pair'><span class='gd-jp'>泣く</span> → <span class='gd-jp'>泣かない</span></span> → buang ない → <span class='gd-pair'><span class='gd-jp'>泣か</span> → <span class='gd-jp'>泣かずにはいられない</span></span><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言わずにはいられない</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べずにはいられない</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べないではいられない</span></span></div><div class='gd-sec'><b>Golongan 3 (perlu diingat khusus)</b>:<br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>せずにはいられない</span></span><span class='gd-pair'><span class='gd-jp'>心配する</span> → <span class='gd-jp'>心配せずにはいられない</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ずにはいられない</span>（こずには）</span><br>Versi ないで cukup memakai bentuk ない biasa: <span class='gd-jp'>心配しないではいられない</span>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Versi ず dari する adalah <b>せず</b>, bukan しず: yang benar <span class='gd-jp'>心配せずには</span>. Tapi versi ないで-nya <span class='gd-jp'>心配しないでは</span>, jadi jangan dicampur.<br>・<span class='gd-jp'>来ずには</span> dibaca <b>こずには</b>, bukan きずには.<br>・Bentuk ない dari <span class='gd-jp'>言う</span> adalah <span class='gd-jp'>言わない</span>, jadi yang benar <span class='gd-jp'>言わずには</span>, bukan 言あずには.<br>・Karena ada banyak bentuk negatif, kamu mungkin refleks mengartikannya \"tidak boleh tidak ～\" atau \"harus ～\", seolah-olah dipaksa. Padahal maksudnya <b>kamu sendiri yang tak tahan</b>. Cara mengingat paling pas: \"tak tahan, jadi dilakukan\".<br>・Subjeknya biasanya <b>aku sendiri</b>. Untuk orang lain, tambahkan <span class='gd-jp'>ようだ</span> atau <span class='gd-jp'>らしい</span>: <span class='gd-jp'>彼は文句を言わずにはいられないようだ。</span>（Sepertinya dia tak bisa tahan kalau tidak mengeluh dulu）</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>ざるを得ない</b>＝tidak mau melakukannya, tapi <b>terpaksa karena keadaan</b>:<br><span class='gd-jp'>部長の冗談は全然おもしろくないけど、笑わざるを得なかった。</span>（Lelucon kepala divisi sama sekali tidak lucu, tapi aku terpaksa tertawa）<br><b>ずにはいられない</b>＝muncul dari dalam hati, <b>kamu sendiri tak tahan</b>:<br><span class='gd-jp'>友だちの冗談がおもしろすぎて、笑わずにはいられなかった。</span>（Lelucon temanku lucu sekali, aku tak tahan untuk tertawa）</div><div class='gd-sec'><b>てたまらない</b>＝menekankan <b>perasaan di hati</b> yang sangat kuat, bisa jadi orangnya masih menahan diri:<br><span class='gd-jp'>ケーキが食べたくてたまらない。</span>（Aku ingin sekali makan kue）<br><b>ずにはいられない</b>＝menekankan <b>tindakan yang tak bisa dihentikan</b>, biasanya sudah dilakukan:<br><span class='gd-jp'>ケーキを見ると、食べずにはいられない。</span>（Begitu melihat kue, aku tak tahan untuk memakannya）</div><div class='gd-warn'>Trik membedakan: \"tak tahan, jadi dilakukan\" → ずにはいられない; \"sebenarnya tidak mau tapi terpaksa\" → ざるを得ない; \"perasaan ～ yang luar biasa\" → てたまらない.</div>","n2-38":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜かねない」artinya <b>「kalau begini terus, bisa-bisa ～」</b>, dan yang mengikutinya pasti <b>hal buruk</b>. Seperti saat kamu bilang \"Kalau kamu begadang terus begitu, lama-lama bisa sakit\", nadanya mengingatkan dan memperingatkan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengingatkan hasil yang buruk</span>Biasanya di depan disebut dulu sebab atau syaratnya (<span class='gd-jp'>〜と</span>、<span class='gd-jp'>〜ば</span>、<span class='gd-jp'>このままでは</span>), lalu かねない menyebutkan hal buruk yang mungkin terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>無理を続けると、体を壊しかねない。</span>（Kalau terus memaksakan diri, bisa-bisa kamu jatuh sakit）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな言い方をしたら、誤解されかねないよ。</span>（Kalau bicara seperti itu, bisa-bisa kamu disalahpahami lho）</div><div class='gd-sec'><span class='gd-tag'>Orang itu bisa saja melakukannya</span>Dipakai untuk bilang \"hal seperti itu, dia memang bisa saja melakukannya\", dengan penilaian negatif.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの人なら、約束を忘れかねない。</span>（Kalau orang itu, bisa-bisa dia benar-benar lupa janjinya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah dulu kata kerja ke bentuk ます, buang 「ます」, lalu tambahkan 「かねない」.<br><span class='gd-pair'><span class='gd-jp'>壊す</span> → <span class='gd-jp'>壊します</span> → <span class='gd-jp'>壊しかねない</span></span><br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れます</span> → <span class='gd-jp'>忘れかねない</span></span><br><span class='gd-pair'><span class='gd-jp'>誤解する</span> → <span class='gd-jp'>誤解します</span> → <span class='gd-jp'>誤解しかねない</span></span><br>Kalau mau lebih sopan, pakai <b>かねません</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>このままでは、計画が中止になりかねません。</span>（Kalau begini terus, bisa-bisa rencananya dibatalkan）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Meski berakhir dengan 「ない」, artinya <b>bukan \"tidak\"</b>, melainkan \"<b>mungkin saja terjadi</b>\". Jangan refleks mengartikan ない sebagai \"tidak\".<br>・Hanya untuk hal buruk. Untuk hal baik pakai かもしれない: ×<span class='gd-jp'>合格しかねない</span> → ○<span class='gd-jp'>合格するかもしれない</span>（bisa jadi lulus）.<br>・Di depannya hanya boleh bentuk ます yang dibuang ます-nya, tidak boleh bentuk kamus atau bentuk ない: ×<span class='gd-jp'>壊すかねない</span>、×<span class='gd-jp'>壊さないかねない</span>.<br>・Nuansanya cukup formal, sering dipakai di berita, laporan kantor, dan peringatan dokter. Saat ngobrol dengan teman, lebih sering dipakai <span class='gd-jp'>〜かもしれない</span> atau <span class='gd-jp'>〜ちゃうかも</span>.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>かねる</b>＝\"(karena posisi) tidak bisa ～, kurang pantas untuk ～\", sering dipakai pegawai toko atau customer service untuk menolak dengan sopan.<br><b>かねない</b>＝\"bisa-bisa ～ (hal buruk)\".<br>Contoh saat ditanya pertanyaan yang sensitif:</div><div class='gd-ex-line'>・<span class='gd-jp'>その質問にはお答えしかねます。</span>（Mohon maaf, kami tidak bisa menjawab pertanyaan itu）</div><div class='gd-ex-line'>・<span class='gd-jp'>その質問に答えたら、誤解されかねない。</span>（Kalau menjawab pertanyaan itu, bisa-bisa disalahpahami）</div><div class='gd-sec'><b>かもしれない</b>＝sekadar \"mungkin\", bisa untuk hal baik maupun buruk, nadanya netral. <b>かねない</b> hanya untuk hal buruk, dan ada nuansa peringatan \"hati-hati\".</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は晴れるかもしれない。</span>（Besok mungkin cerah）</div><div class='gd-ex-line'>・<span class='gd-jp'>このまま遊んでいたら、試験に落ちかねない。</span>（Kalau main terus begini, bisa-bisa gagal ujian）</div><div class='gd-warn'>Trik membedakan: \"tidak bisa ～, mohon maaf tidak dapat ～\" adalah かねる (meski tanpa ない, artinya justru tidak bisa); \"kalau begini terus bisa-bisa terjadi sesuatu yang buruk\" adalah かねない; \"mungkin\" yang netral, baik atau buruk, pakai かもしれない.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'><b>〜得る</b> juga berarti \"mungkin terjadi\", tapi tidak membedakan baik atau buruk, dan nadanya lebih objektif: <span class='gd-jp'>これは誰にでも起こり得ることだ。</span>（Ini hal yang bisa terjadi pada siapa saja）</div>","n2-33":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜上に」 setara dengan <b>「tidak hanya ～, tetapi juga ～」「～, ditambah lagi ～」</b>. Sebutkan satu hal dulu, lalu tumpuk hal lain yang <b>searah</b>: yang bagus ditambah yang bagus, yang sial ditambah yang sial.</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から近い上に、家賃も安い。</span>(Kamar ini tidak hanya dekat dari stasiun, sewanya juga murah)</div><div class='gd-ex-line'>・<span class='gd-jp'>道に迷った上に、雨にも降られた。</span>(Sudah tersesat, kehujanan pula)</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Verba</b>: sambung langsung, bentuk sekarang maupun lampau boleh.<br><span class='gd-pair'><span class='gd-jp'>寝坊した</span> → <span class='gd-jp'>寝坊した上に</span></span><br><b>Adjektiva-い</b>: sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安い上に</span></span><br><b>Adjektiva-な</b>: ganti 「だ」 menjadi 「な」.<br><span class='gd-pair'><span class='gd-jp'>親切だ</span> → <span class='gd-jp'>親切な上に</span></span><br><b>Nomina</b>: tambahkan 「である」 atau 「の」. Dalam tulisan, 「である」 lebih umum.<br><span class='gd-pair'><span class='gd-jp'>医者</span> → <span class='gd-jp'>医者である上に</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は親切な上に、仕事も早い。</span>(Dia ramah, kerjanya juga cepat)</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は寝坊した上に、財布まで忘れてしまった。</span>(Hari ini kesiangan, dompet pun sampai terlupa)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者である上に、作家としても有名だ。</span>(Dia seorang dokter, dan juga terkenal sebagai penulis)</div><div class='gd-sec'>Kamu akan sering menemukan <span class='gd-jp'>も</span> atau <span class='gd-jp'>まで</span> di bagian kedua, karena maknanya \"yang ini <b>juga</b> ～\" atau \"bahkan yang ini <b>pun</b> ～\".</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Dibaca <b>うえに</b>, bukan じょうに.<br>・Arah bagian depan dan belakang harus sama. <span class='gd-jp'>安い上に、まずい。</span> itu salah. Murah itu kelebihan, tidak enak itu kekurangan. Kalau yang satu bagus dan yang satu jelek, pakai <span class='gd-jp'>安いけど、まずい。</span>(Murah sih murah, tapi tidak enak)<br>・Adjektiva-な tidak boleh tetap membawa 「だ」: katakan <span class='gd-jp'>便利な上に</span>, bukan 便利だ上に.<br>・Kalimat dengan 「上に」 itu untuk menggambarkan atau menilai sesuatu, jadi di belakangnya jangan langsung diikuti 「tolong ～」 atau 「ayo kita ～」. Kalau mau mengajak orang, selesaikan dulu kedua hal itu, lalu sambungkan dengan <span class='gd-jp'>から</span>: <span class='gd-jp'>寒い上に風も強いから、今日は家にいよう。</span>(Dingin, anginnya juga kencang, hari ini di rumah saja yuk)<br>・「上に」 dalam <span class='gd-jp'>机の上に本がある。</span> artinya \"di atas meja\", yaitu soal posisi. Ini tidak ada hubungannya dengan pola tata bahasa ini, dan dari konteks kamu langsung bisa membedakannya.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Ketiganya punya 「上」 tetapi artinya sama sekali berbeda. Bandingkan dalam situasi \"pekerjaan\":<br><b>上に</b> = lagi pula (dua fakta ditumpuk): <span class='gd-jp'>この仕事は給料が安い上に、残業も多い。</span>(Pekerjaan ini gajinya rendah, lemburnya juga banyak)<br><b>上で</b> = selesaikan A dulu, baru B: <span class='gd-jp'>条件をよく確認した上で、契約します。</span>(Setelah memeriksa syaratnya dengan teliti, baru saya tanda tangani kontraknya)<br><b>上は</b> = karena sudah ～, maka harus ～: <span class='gd-jp'>引き受けた上は、最後までやります。</span>(Karena sudah menerimanya, saya akan mengerjakannya sampai akhir)</div><div class='gd-warn'>Trik membedakan: kalau dalam bahasa Indonesia bisa diganti \"lagi pula / ditambah lagi\", itu 上に. Kalau \"setelah ～ baru\", itu 上で. Kalau \"karena sudah ～, maka harus\", itu 上は.</div><div class='gd-h'>Bisa dipelajari selanjutnya</div><div class='gd-sec'><span class='gd-jp'>その上</span> di awal kalimat juga berarti \"lagi pula\": <span class='gd-jp'>この店は安い。その上、おいしい。</span>(Toko ini murah. Lagi pula enak)<br>Untuk ungkapan yang lebih kuat, \"bukan hanya ～, bahkan ～\", pelajari juga <span class='gd-jp'>〜ばかりか</span> dan <span class='gd-jp'>〜のみならず</span>.</div>","n2-34":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜のことだから」 setara dengan <b>「dengan sifatnya itu, pasti ～」「orang itu kan ya, kayaknya bakal ～」</b>. Kamu tahu betul seperti apa orang itu biasanya, lalu pemahaman itu kamu jadikan dasar untuk menebak apa yang akan dia lakukan kali ini.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak dari sifat</span>Di bagian depan sebut orang yang kamu kenal, sebaiknya sekalian sebut sifatnya. Di bagian belakang tulis dugaanmu.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間に厳しい部長のことだから、もう会議室にいるはずだ。</span>(Kepala divisi kan sangat disiplin soal waktu, jadi sekarang pasti sudah ada di ruang rapat)</div><div class='gd-ex-line'>・<span class='gd-jp'>優しい彼女のことだから、きっと手伝ってくれるよ。</span>(Dia kan baik hati, pasti dia mau membantumu)</div><div class='gd-ex-line'>・<span class='gd-jp'>弟のことだから、どうせまだ寝ているよ。</span>(Adikku itu kan begitu, pasti masih tidur)</div><div class='gd-sec'><span class='gd-tag'>Bisa juga untuk perusahaan atau toko</span>Selama gaya kebiasaannya sudah diketahui banyak orang, pola ini boleh dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの会社のことだから、また値上げするだろう。</span>(Perusahaan itu kan memang begitu, kemungkinan besar bakal menaikkan harga lagi)</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Nomina + 「の」 + 「ことだから」:<br><span class='gd-pair'><span class='gd-jp'>彼</span> → <span class='gd-jp'>彼のことだから</span></span><br><span class='gd-pair'><span class='gd-jp'>あの会社</span> → <span class='gd-jp'>あの会社のことだから</span></span><br>Di depan, sering ditambahkan kata yang menggambarkan sifat supaya dasarnya lebih jelas:<br><span class='gd-pair'><span class='gd-jp'>真面目な彼</span> → <span class='gd-jp'>真面目な彼のことだから</span></span></div><div class='gd-sec'>Bagian belakang biasanya berisi dugaanmu, jadi sering muncul bersama <span class='gd-jp'>だろう</span>, <span class='gd-jp'>きっと</span>, <span class='gd-jp'>はずだ</span>, dan <span class='gd-jp'>に違いない</span>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・「の」 tidak boleh ketinggalan: yang benar <span class='gd-jp'>彼のことだから</span>, bukan 彼ことだから.<br>・Orang di bagian depan harus orang yang kamu tahu betul sifat kesehariannya, dan biasanya pendengar juga tahu sifatnya. Orang yang baru pertama kali kamu temui tidak bisa dipakai, karena kamu belum mengenalnya sama sekali.<br>・Bagian belakang berisi \"menurutku\" atau \"kuduga\", bukan fakta yang sudah terjadi. Untuk hal yang sudah benar-benar pasti, jangan pakai pola ini.<br>・Kalau diartikan \"karena dia\", orang mudah mengira ini cuma alasan biasa. Padahal intinya ada pada <b>\"berdasarkan pemahamanku tentang dia\"</b>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Dalam situasi yang sama, yaitu menebak apakah temanmu akan datang tepat waktu:<br><b>Nomina＋だから</b> = karena dia termasuk jenis atau kelompok tertentu (alasannya berupa fakta atau kategori): <span class='gd-jp'>彼は日本人だから、時間を守るだろう。</span>(Dia orang Jepang, jadi mungkin akan tepat waktu)<br><b>Nomina＋のことだから</b> = berdasarkan pemahamanku tentang <b>orang ini</b>: <span class='gd-jp'>彼のことだから、時間を守るだろう。</span>(Dengan sifatnya, mungkin dia akan tepat waktu)<br>Kalimat pertama memakai status \"orang Jepang\" sebagai alasan. Kalimat kedua memakai alasan bahwa kamu mengenalnya dan tahu dia selalu tepat waktu.</div><div class='gd-warn'>Trik membedakan: kalau alasannya \"dia adalah ～ (status, fakta)\", pakai だから. Kalau alasannya \"aku tahu dia memang orang yang begitu\", pakai のことだから.</div><div class='gd-h'>Bisa dipelajari selanjutnya</div><div class='gd-sec'>Bagian belakang sering dipakai untuk dugaan yang sangat yakin. Pelajari juga <span class='gd-jp'>〜に違いない</span> (pasti ～) dan <span class='gd-jp'>〜に決まっている</span> (sudah pasti ～): <span class='gd-jp'>あの人のことだから、また忘れたに決まっている。</span>(Orang itu kan begitu, sudah pasti lupa lagi)</div>","n2-39":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜得る」artinya <b>“mungkin ～”</b>, dan 「〜得ない」artinya <b>“tidak mungkin ～”</b>. Nuansanya formal, seperti “dapat terjadi” atau “mustahil” di berita dan laporan. Yang paling sering kamu dengar mungkin kalimat di drama Jepang ini: <span class='gd-jp'>ありえない！</span>, artinya “Mana mungkin!” atau “Yang benar saja!”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます, buang ます-nya, lalu sambungkan dengan 「得る」.<br><span class='gd-pair'><span class='gd-jp'>起こります</span> → buang ます → <span class='gd-jp'>起こり得る</span></span> (bisa saja terjadi)<br><span class='gd-pair'><span class='gd-jp'>あります</span> → <span class='gd-jp'>あり得る</span></span> (bisa saja ada)<br><span class='gd-pair'><span class='gd-jp'>考えます</span> → <span class='gd-jp'>考え得る</span></span> (yang terpikirkan)<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>し得る</span></span> (mungkin dilakukan)</div><div class='gd-h'>Cara membacanya: hanya satu bagian yang bisa dipilih</div><div class='gd-sec'><b>Hanya pada bentuk dasar 「得る」</b> (di akhir kalimat atau sebelum kata benda), boleh dibaca <b>うる</b> atau <b>える</b>. <span class='gd-jp'>あり得る</span> boleh dibaca ありうる maupun ありえる, dan ありうる lebih sering terdengar di berita dan tulisan.<br><b>Semua bentuk lainnya selalu dibaca 「え」</b>: <span class='gd-jp'>得ない</span> (えない), <span class='gd-jp'>得ます</span> (えます), <span class='gd-jp'>得た</span> (えた).</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mungkin terjadi</span>Mengatakan secara objektif bahwa sesuatu bisa saja terjadi, baik hal baik maupun buruk.</div><div class='gd-ex-line'>・<span class='gd-jp'>誰にでも起こり得る問題だ。</span>(Ini masalah yang bisa dialami siapa saja)</div><div class='gd-ex-line'>・<span class='gd-jp'>それは十分あり得る話だ。</span>(Itu hal yang sangat mungkin terjadi)</div><div class='gd-sec'><span class='gd-tag'>Tidak mungkin</span>Menegaskan bahwa sesuatu tidak akan terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことは現実的にあり得ない。</span>(Hal seperti itu mustahil terjadi di dunia nyata)</div><div class='gd-sec'><span class='gd-tag'>Yang terpikirkan・yang bisa dilakukan</span>Sering muncul bersama 「限り」atau 「すべて」.</div><div class='gd-ex-line'>・<span class='gd-jp'>考え得る方法は全部試した。</span>(Semua cara yang terpikirkan sudah kucoba)</div><div class='gd-sec'><span class='gd-tag'>Lisan</span><span class='gd-jp'>ありえない</span> adalah pengecualian. Kata ini sering dipakai ngobrol dengan teman untuk menyatakan kaget atau tidak percaya.</div><div class='gd-ex-line'>・<span class='gd-jp'>え、また遅刻？ありえない！</span>(Hah, telat lagi? Yang benar saja!)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Pola ini membahas <b>mungkin tidaknya suatu hal terjadi</b>, bukan bisa tidaknya seseorang melakukan suatu keterampilan. “Aku bisa berenang” harus <span class='gd-jp'>泳げる</span>, tidak bisa泳ぎ得る.<br>・Bentuk negatifnya hanya dibaca えない: yang benar <span class='gd-jp'>ありえない</span>, tidak ada bacaan 「ありうない」.<br>・Selain <span class='gd-jp'>ありえない</span> dan <span class='gd-jp'>ありえる</span>, kata seperti <span class='gd-jp'>起こり得る</span> cenderung bergaya tulisan. Untuk ngobrol sehari-hari, <span class='gd-jp'>起こるかもしれない</span> terdengar lebih natural.<br>・<span class='gd-jp'>ざるを得ない</span> juga mengandung 「得ない」, tetapi artinya sama sekali berbeda: <span class='gd-jp'>行かざるを得ない</span> berarti “terpaksa pergi”, bukan “mustahil pergi”.<br>・Kalau 「得る」berdiri sendiri sebagai kata kerja, dibaca える dan artinya “mendapatkan”, misalnya <span class='gd-jp'>賞を得る</span> (meraih penghargaan). Itu hal yang berbeda dari pola di sini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>得る vs かねない</b>: keduanya berarti “mungkin”, tetapi かねない hanya dipakai saat <b>khawatir hal buruk akan terjadi</b>.<br><span class='gd-jp'>このままでは事故が起こり得る。</span> (Kalau begini terus, kecelakaan bisa saja terjadi: pernyataan yang tenang)<br><span class='gd-jp'>このままでは事故が起こりかねない。</span> (Kalau begini terus, jangan-jangan terjadi kecelakaan: ada rasa khawatir)<br>Untuk hal baik, hanya 得る yang bisa dipakai: <span class='gd-jp'>努力すれば誰でも成功し得る。</span> (Kalau berusaha, siapa pun bisa berhasil) Kalau diganti かねない, kalimatnya jadi salah.</div><div class='gd-sec'><b>得ない vs っこない</b>: keduanya berarti “tidak mungkin”, tetapi っこない sangat lisan dan <b>subjektif</b>, seperti “mana mungkin lah”.<br><span class='gd-jp'>一日で終わることはあり得ない。</span> (Mustahil selesai dalam sehari: formal, objektif)<br><span class='gd-jp'>一日で終わりっこないよ。</span> (Mana mungkin selesai dalam sehari: mengeluh ke teman)</div><div class='gd-warn'>Tips cepat: untuk menyatakan “mungkin/tidak mungkin” secara objektif, pakai 得る・得ない; untuk khawatir hal buruk terjadi, pakai かねない; untuk bilang “mana mungkin lah” ke teman, pakai っこない.</div>","n2-40":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜っこない」setara dengan <b>“mana mungkin ～”</b> atau <b>“masa sih ～”</b> dalam bahasa Indonesia. Si pembicara sudah yakin “hal ini pasti tidak akan terjadi”. Nadanya tegas dan sangat lisan, sering terasa seperti “sudahlah” atau “jangan mimpi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなこと、できっこないよ。</span>(Hal seperti itu, mana mungkin bisa)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ます, <b>buang ます-nya</b>, lalu tambahkan 「っこない」.<br><span class='gd-pair'><span class='gd-jp'>できます</span> → <span class='gd-jp'>できっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>間に合います</span> → <span class='gd-jp'>間に合いっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>分かります</span> → <span class='gd-jp'>分かりっこない</span></span><br><span class='gd-pair'><span class='gd-jp'>勝てます</span> → <span class='gd-jp'>勝てっこない</span></span></div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>Tidak mungkin bisa</span>Paling sering dipasangkan dengan 「できる」「分かる」「間に合う」, atau kata kerja yang menyatakan “bisa atau tidak”, seperti 「勝てる」「受かる」「取れる」. Artinya “sama sekali tidak mungkin”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あんな強いチームに勝てっこない。</span>(Tim sekuat itu, mana mungkin menang)</div><div class='gd-ex-line'>・<span class='gd-jp'>今から走っても間に合いっこないよ。</span>(Sekarang lari pun mana mungkin keburu)</div><div class='gd-ex-line'>・<span class='gd-jp'>説明したって、あの人には分かりっこない。</span>(Biarpun dijelaskan, orang itu mana mungkin ngerti)</div><div class='gd-sec'><span class='gd-tag'>Orang lain tidak akan melakukannya</span>Saat membicarakan perbuatan orang lain, artinya “dia mana mungkin berbuat begitu”.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの頑固な父が謝りっこない。</span>(Ayahku yang keras kepala itu, mana mungkin minta maaf)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk setelah ます dibuang</b>, bukan bentuk kamus: yang benar <span class='gd-jp'>分かりっこない</span>, tidak bisa 「分かるっこない」.<br>・「っこない」sudah bermakna negatif, jadi jangan menambahkan ない di depannya.<br>・Pola ini hanya dipakai dengan kata kerja, tidak langsung dengan kata sifat atau kata benda.<br>・「っこ」punya konsonan rangkap (っ), jadi berhenti sejenak sebelum 「こ」. Jangan dibaca 「こない」saja, karena akan terdengar seperti 「来ない」.<br>・Ini ungkapan antarteman dan nadanya kuat. Tidak cocok untuk atasan atau pelanggan, maupun untuk laporan tertulis.<br>・Kalau kamu bilang 「<span class='gd-jp'>君にはできっこない</span>」(kamu mana mungkin bisa) langsung ke orangnya, itu sama saja meremehkan dia dan sangat menyakitkan, jadi hati-hati.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Untuk hal yang sama, “kerjaan sebanyak ini mana mungkin selesai dalam sehari”, ada tiga cara bilang:<br><span class='gd-jp'>一日で終わりっこない。</span> (<b>っこない</b>: lisan, penuh emosi, seperti mengeluh)<br><span class='gd-jp'>一日で終わるわけがない。</span> (<b>わけがない</b>: “mana mungkin”, bisa dipakai di lisan maupun tulisan)<br><span class='gd-jp'>一日で終わるはずがない。</span> (<b>はずがない</b>: menyimpulkan “tidak mungkin” berdasarkan logika, lebih tenang)<br>Perhatikan juga cara menyambungnya berbeda: わけがない dan はずがない disambung dengan bentuk kamus (<span class='gd-jp'>終わる</span>), sedangkan っこない disambung dengan bentuk tanpa ます (<span class='gd-jp'>終わり</span>).</div><div class='gd-warn'>Tips cepat: untuk bergumam atau curhat ke teman, pakai 「っこない」; untuk nada yang lebih formal, ganti dengan 「わけがない」atau 「はずがない」.</div><div class='gd-h'>Bisa dipelajari selanjutnya</div><div class='gd-sec'>Yang artinya berlawanan adalah 「〜に決まっている」= “pasti ～, tidak salah lagi”: <span class='gd-jp'>そんなの、失敗するに決まっている。</span> (Cara seperti itu, pasti gagal.)</div>","n2-45":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ぶり」punya dua penggunaan yang <b>sama sekali berbeda</b>:<br>① Setelah kata yang menunjukkan tindakan = <b>「gaya ~, cara ~」</b>, mirip dengan “cara makan” atau “etos kerja” dalam bahasa Indonesia.<br>② Setelah kata yang menunjukkan rentang waktu = <b>「sudah lama sekali sejak ~, setelah jeda ~ terjadi lagi」</b>. Ini ぶり yang sama dengan di <span class='gd-jp'>久しぶり</span>, yang pasti sudah kamu kenal.</div><div class='gd-h'>Penggunaan ①: gaya ~</div><div class='gd-sec'><span class='gd-tag'>Cara menyambung</span>Nomina langsung ditambah ぶり: <span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事ぶり</span></span> (kinerja kerja)<br>Verba diubah dulu ke bentuk ます, buang ます, lalu tambahkan ぶり: <span class='gd-pair'><span class='gd-jp'>話します</span> → ます dibuang → <span class='gd-jp'>話しぶり</span></span> (cara bicara) <span class='gd-pair'><span class='gd-jp'>暮らします</span> → <span class='gd-jp'>暮らしぶり</span></span> (cara menjalani hidup)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の仕事ぶりはみんなに認められている。</span> (Kinerja kerjanya diakui oleh semua orang)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女の話しぶりから、自信を感じた。</span> (Dari cara bicaranya, aku merasakan rasa percaya diri)</div><div class='gd-ex-line'>・<span class='gd-jp'>駅の混雑ぶりに驚いた。</span> (Aku kaget melihat stasiun seramai itu)</div><div class='gd-sec'>Biasanya dipakai untuk menggambarkan atau menilai gaya yang ditunjukkan <b>orang lain atau suatu keadaan</b>. Beberapa kata biasa dilafalkan 「っぷり」, misalnya <span class='gd-jp'>食べっぷり</span> dan <span class='gd-jp'>飲みっぷり</span>:</div><div class='gd-ex-line'>・<span class='gd-jp'>いい食べっぷりだね。</span> (Kamu makannya lahap banget, ya)</div><div class='gd-h'>Penggunaan ②: setelah jeda ~, terjadi lagi</div><div class='gd-sec'><span class='gd-tag'>Cara menyambung</span>Rentang waktu + ぶり. Setelahnya sering diikuti 「に＋verba」, 「の＋nomina」, atau langsung 「だ／です」.</div><div class='gd-ex-line'>・<span class='gd-jp'>5年ぶりに母校を訪れた。</span> (Setelah lima tahun, aku akhirnya mengunjungi almamaterku lagi)</div><div class='gd-ex-line'>・<span class='gd-jp'>10年ぶりの再会だった。</span> (Itu pertemuan kembali setelah sepuluh tahun)</div><div class='gd-ex-line'>・<span class='gd-jp'>久しぶりの休みだ。</span> (Akhirnya libur juga setelah sekian lama)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、3年ぶりですね。</span> (Pak Tanaka, sudah tiga tahun ya kita tidak bertemu)</div><div class='gd-sec'>Intinya: selama jeda itu hal tersebut <b>tidak terjadi</b>, dan sekarang <b>terjadi lagi</b>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Penggunaan ② tidak bisa diikuti bentuk negatif. Kalau mau bilang “tiga tahun tidak bertemu”, jangan pakai <span class='gd-jp'>3年ぶりに会わなかった</span>, tapi <span class='gd-jp'>3年間会っていない</span>.<br>・Penggunaan ② selalu berarti “dulu pernah, sekarang terjadi <b>lagi</b>”. Kalau itu pertama kalinya, tidak ada “lagi”, jadi ぶり tidak bisa dipakai.<br>・Penggunaan ① tidak bisa dipasang ke sembarang kata. Yang umum hanya beberapa: <span class='gd-jp'>仕事ぶり</span>, <span class='gd-jp'>話しぶり</span>, <span class='gd-jp'>暮らしぶり</span>, <span class='gd-jp'>生活ぶり</span>, <span class='gd-jp'>活躍ぶり</span>, <span class='gd-jp'>混雑ぶり</span>. Cara paling praktis adalah menghafalnya sebagai satu kosakata utuh.<br>・Verba disambung dalam bentuk ます yang dibuang ます-nya: yang benar <span class='gd-jp'>話しぶり</span>, bukan 話すぶり.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama situasi “setelah lulus”:<br><b>て以来</b> = sejak itu keadaan tertentu <b>terus</b> berlanjut: <span class='gd-jp'>卒業して以来、彼には一度も会っていない。</span> (Sejak lulus, aku tidak pernah bertemu dengannya sekali pun)<br><b>ぶり</b> = setelah jeda selama itu, sesuatu terjadi <b>lagi</b>: <span class='gd-jp'>卒業以来、5年ぶりに彼に会った。</span> (Setelah lima tahun sejak lulus, akhirnya aku bertemu dengannya lagi)<br><b>後</b> = sekadar “setelah ~”, tidak peduli pernah terjadi sebelumnya atau tidak: <span class='gd-jp'>卒業して5年後に結婚した。</span> (Lima tahun setelah lulus, aku menikah)</div><div class='gd-warn'>Trik menentukan: kalau mau bilang “sejak itu terus begini”, pakai て以来. Kalau “setelah sekian lama, akhirnya ~ lagi”, pakai ぶり. Kalau cuma “setelah ~”, pakai 後.</div>","n2-46":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜がたい」artinya <b>「sulit untuk ~」「sukar ~」</b>. Intinya bukan kemampuanmu yang kurang, tapi <b>hati sulit menerimanya</b>: hal itu terlalu keterlaluan sehingga kamu sulit percaya, sulit menerima, atau sulit memaafkan. Nuansanya agak formal, sering muncul di berita, tulisan, dan situasi resmi.</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Ubah verba ke bentuk ます, buang ます, lalu tambahkan がたい.<br><span class='gd-pair'><span class='gd-jp'>信じる</span> → <span class='gd-jp'>信じます</span> → <span class='gd-jp'>信じがたい</span></span><br><span class='gd-pair'><span class='gd-jp'>許す</span> → <span class='gd-jp'>許します</span> → <span class='gd-jp'>許しがたい</span></span><br><span class='gd-pair'><span class='gd-jp'>理解する</span> → <span class='gd-jp'>理解します</span> → <span class='gd-jp'>理解しがたい</span></span><br>Setelah disambung, seluruh kata dipakai seperti kata sifat berakhiran い: bisa diletakkan sebelum nomina dan bisa diubah ke bentuk lampau.<br><span class='gd-pair'><span class='gd-jp'>信じがたい</span> → <span class='gd-jp'>信じがたかった</span></span> (dulu sulit dipercaya)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Di akhir kalimat</span>Langsung menyatakan “aku sungguh sulit ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼のあの行動は今でも理解しがたい。</span> (Tindakannya waktu itu sampai sekarang masih sulit kupahami)</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は受け入れがたい。</span> (Hasil ini sulit diterima)</div><div class='gd-sec'><span class='gd-tag'>Sebelum nomina</span>Dipakai sebagai kata sifat. Ini yang paling umum, dan banyak yang sudah menjadi ungkapan tetap.</div><div class='gd-ex-line'>・<span class='gd-jp'>それは信じがたい話だ。</span> (Itu cerita yang sulit dipercaya)</div><div class='gd-ex-line'>・<span class='gd-jp'>留学は忘れがたい経験になった。</span> (Belajar di luar negeri menjadi pengalaman yang tak terlupakan)</div><div class='gd-ex-line'>・<span class='gd-jp'>許しがたい行為だ。</span> (Ini perbuatan yang tak termaafkan)</div><div class='gd-sec'>Yang umum lainnya: <span class='gd-jp'>想像しがたい</span> (sulit dibayangkan), <span class='gd-jp'>言いがたい</span> (sulit dikatakan), <span class='gd-jp'>得がたい</span> (langka dan berharga), <span class='gd-jp'>耐えがたい</span> (tak tertahankan).</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk ます yang dibuang ます-nya</b>, bukan bentuk kamus: yang benar <span class='gd-jp'>信じがたい</span>, bukan 信じるがたい.<br>・Kalau <b>bendanya sendiri tidak enak dipakai atau sulit dikerjakan</b>, がたい tidak bisa dipakai: pulpen yang susah dipakai menulis adalah <span class='gd-jp'>このペンは書きにくい</span>, bukan 書きがたい.<br>・Nuansanya kaku dan formal. Saat ngobrol dengan teman, <span class='gd-jp'>信じられない</span> dan <span class='gd-jp'>許せない</span> terdengar lebih natural. Kalau bilang 信じがたい, kesannya seperti membaca naskah.<br>・Dalam tulisan sering ditulis dengan kanji 「難い」, dan di sini dibaca <b>がたい</b>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にくい</b> = bendanya sendiri <b>sulit ~</b>, sulit secara fisik atau teknis:<br><span class='gd-jp'>この説明は分かりにくい。</span> (Penjelasan ini sulit dipahami: tulisannya tidak jelas)<br><b>がたい</b> = <b>hati sulit</b> menerima, percaya, atau memaafkan:<br><span class='gd-jp'>彼の考えは理解しがたい。</span> (Pikirannya sungguh tak bisa kupahami: hatiku tidak bisa menyetujuinya)<br><b>かねる</b> = dari posisi sendiri <b>tidak bisa melakukan</b>, sering dipakai untuk menolak dengan sopan:<br><span class='gd-jp'>その件にはお答えしかねます。</span> (Mohon maaf, saya tidak bisa menjawab soal itu)</div><div class='gd-warn'>Trik menentukan: kalau bendanya tidak enak dipakai atau sulit dipahami, pakai にくい. Kalau hati sulit menerimanya, pakai がたい. Kalau mau menolak lawan bicara dengan sopan, pakai かねる.</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'><span class='gd-jp'>ありがたい</span> yang kamu ucapkan setiap hari sebenarnya berasal dari 「有り難い」. Arti aslinya “langka, jarang ada”, lalu kemudian berkembang menjadi “patut disyukuri”.</div>","n2-47":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜かける」artinya <b>「baru separuh ～」「setengah jalan」</b>: buku baru dibaca separuh, makanan baru dimakan separuh, ucapan terhenti di tengah kalimat. Sesuatu sudah dimulai tapi belum selesai, jadi berhenti di tengah jalan. Kalau dipasang pada verba tertentu, artinya bisa berubah jadi <b>「hampir ～」「nyaris ～」</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ambil bentuk ます dari verba, buang 「ます」, lalu tambahkan 「かける」 atau 「かけの」.<br><span class='gd-pair'><span class='gd-jp'>読みます</span> → <span class='gd-jp'>読みかける</span></span><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べかける</span></span><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しかける</span></span><br>「かける」sendiri berubah seperti verba golongan 2 (verba 一段): <span class='gd-jp'>かけた</span>、<span class='gd-jp'>かけて</span>、<span class='gd-jp'>かけている</span>.<br>Untuk menerangkan kata benda, pakai <b>かけの＋kata benda</b>: <span class='gd-jp'>飲みかけのコーヒー</span> (kopi yang baru diminum separuh).<br>Di akhir kalimat, pakai <b>かけだ</b>: <span class='gd-jp'>この本はまだ読みかけだ。</span> (Buku ini belum selesai kubaca)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Berhenti di tengah</span>Dipasang pada tindakan yang kamu lakukan sendiri seperti 「baca, makan, tulis, bicara」, untuk menunjukkan tindakan itu terhenti di tengah jalan.</div><div class='gd-ex-line'>・<span class='gd-jp'>読みかけの小説が本棚に積まれている。</span>(Novel yang baru dibaca separuh menumpuk di rak buku)</div><div class='gd-ex-line'>・<span class='gd-jp'>何か言いかけて、やめた。</span>(Dia mulai mengatakan sesuatu, lalu berhenti)</div><div class='gd-ex-line'>・<span class='gd-jp'>飲みかけのコーヒー、捨ててもいい？</span>(Kopi yang baru diminum separuh ini boleh dibuang?)</div><div class='gd-sec'><span class='gd-tag'>Nyaris, hampir</span>Dipasang pada perubahan yang terjadi seketika seperti 「mati, tenggelam, padam, lupa」. Artinya 「sudah hampir begitu」 atau 「nyaris begitu, tapi ternyata tidak」.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供のころ、海で溺れかけたことがある。</span>(Waktu kecil, aku pernah nyaris tenggelam di laut)</div><div class='gd-ex-line'>・<span class='gd-jp'>道で死にかけた猫を見つけた。</span>(Aku menemukan kucing yang hampir mati di jalan)</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れかけていた夢を思い出した。</span>(Aku teringat kembali pada mimpi yang nyaris terlupakan)</div><div class='gd-h'>Yang sering bikin salah</div><div class='gd-warn'>・<span class='gd-jp'>話しかける</span> bukan 「bicara sampai setengah」, tapi <b>「menyapa / mengajak bicara orang」</b>. Kalau mau bilang 「berhenti bicara di tengah」, pakai <span class='gd-jp'>言いかける</span>. <span class='gd-jp'>呼びかける</span> (menyerukan) dan <span class='gd-jp'>出かける</span> (pergi keluar) juga kata tersendiri yang tidak ada hubungannya dengan 「setengah jalan」.<br>・Untuk menerangkan kata benda, yang paling umum adalah 「かけの」: <span class='gd-jp'>食べかけのパン</span> (roti yang baru dimakan separuh). Jangan ditulis 「食べかけパン」.<br>・Verba yang menyatakan 「keberadaan, keadaan」 seperti <span class='gd-jp'>ある</span> dan <span class='gd-jp'>いる</span> tidak punya awal dan akhir, jadi tidak bisa dipasang dengan かける.<br>・「かける」yang sama bisa berarti 「setengah jalan」 atau 「nyaris」, tergantung verba di depannya: <span class='gd-jp'>死にかける</span> pasti berarti 「nyaris mati」, bukan 「mati setengah」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Bandingkan dalam situasi yang sama:<br><b>かける</b> = sudah <b>hampir sampai di tahap itu</b>, atau berhenti di tengah jalan: <span class='gd-jp'>火が消えかけている。</span> (Apinya hampir padam, tinggal sedikit lagi)<br><b>つつある</b> = <b>sedang berubah sedikit demi sedikit</b>, fokusnya pada proses perubahan: <span class='gd-jp'>火が消えつつある。</span> (Apinya perlahan-lahan mengecil)<br>Selain itu, <span class='gd-jp'>つつある</span> kebanyakan dipakai dalam bahasa tulis dan berita, sedangkan <span class='gd-jp'>かける</span> dan <span class='gd-jp'>かけの</span> sering dipakai dalam percakapan sehari-hari.</div><div class='gd-warn'>Trik cepat: kalau mau bilang 「berhenti di tengah, nyaris ～」, pakai かける; kalau mau bilang 「sedang berubah secara bertahap」, pakai つつある.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'>Lawannya adalah <span class='gd-jp'>〜きる</span> (menyelesaikan, melakukan sampai tuntas): <span class='gd-jp'>一晩で読みきった。</span> (Aku menamatkannya dalam semalam)</div>","n2-48":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ことなく」mirip dengan bahasa tulis formal seperti <b>「tanpa ～」「tidak pernah ～」「tak sekali pun ～」</b>. Artinya sama dengan 「〜ないで」(tanpa ～ lalu…), hanya jauh lebih formal, dan sering muncul di berita, artikel, dan pidato.<br>Yang ditaruh di depan adalah <b>hal yang tidak terjadi</b>: <span class='gd-jp'>休むことなく</span> = tanpa istirahat, terus tanpa henti.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk kamus verba (bentuk aslinya seperti di kamus) langsung ditambah ことなく.<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休むことなく</span></span> (tanpa istirahat)<br><span class='gd-pair'><span class='gd-jp'>迷う</span> → <span class='gd-jp'>迷うことなく</span></span> (tanpa ragu)<br>Verba 「kata benda＋する」 juga sama: <span class='gd-pair'><span class='gd-jp'>遅刻する</span> → <span class='gd-jp'>遅刻することなく</span></span> (tanpa terlambat)<br>Bentuk pasif juga bisa: <span class='gd-pair'><span class='gd-jp'>気づかれる</span> → <span class='gd-jp'>気づかれることなく</span></span> (tanpa ketahuan)<br><b>ことなく sendiri tidak membedakan lampau atau sekarang</b>; waktunya dilihat dari akhir kalimat.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>一度も・一日も</span>Kata-kata ini ditaruh di depan untuk menekankan 「sekali pun tidak」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は一日も休むことなく働き続けた。</span>(Dia terus bekerja tanpa istirahat sehari pun)</div><div class='gd-sec'><span class='gd-tag'>Bertahan lama</span>Dipakai untuk sesuatu yang tidak berubah dan tidak terputus dalam waktu lama.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は40年間、変わることなく同じ味を守っている。</span>(Selama 40 tahun, toko ini terus menjaga rasa yang sama tanpa berubah)</div><div class='gd-sec'><span class='gd-tag'>Menyatakan tekad</span>Sering dipakai dalam pidato dan kata sambutan saat menerima penghargaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも初心を忘れることなく、頑張ってまいります。</span>(Ke depannya pun, saya akan terus berusaha tanpa melupakan niat awal)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は迷うことなく、この道を選んだ。</span>(Dia memilih jalan ini tanpa ragu)</div><div class='gd-h'>Yang sering bikin salah</div><div class='gd-warn'>・Di depannya dipasang bentuk kamus <b>positif</b>, bukan bentuk ない: ○<span class='gd-jp'>休むことなく</span>　×休まないことなく.<br>・Jangan mengira 「休む」 berarti 「ada istirahat」; ことなく menyangkal seluruh hal di depannya.<br>・Pada verba 「kata benda＋する」, する tidak boleh dihilangkan: ×連絡ことなく　○<span class='gd-jp'>連絡することなく</span>.<br>・Ungkapan ini terasa kaku. Kalau bilang ke teman 「berangkat tanpa sarapan」, cukup pakai <span class='gd-jp'>食べないで出かけた</span>; kalau pakai ことなく, kedengarannya seperti membacakan surat resmi.<br>・Biasanya dipakai untuk hal yang 「sebenarnya mungkin terjadi, tapi ternyata tidak」 (capek tapi tidak istirahat, seharusnya ragu tapi tidak ragu), jadi sering terasa 「gigih, hebat」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk hal yang sama, 「dia bekerja terus tanpa istirahat」, ada tiga cara bilang:<br><span class='gd-jp'>休まないで働いた。</span> (lisan, paling sering dipakai saat ngobrol)<br><span class='gd-jp'>休まずに働いた。</span> (agak formal, bisa untuk bicara maupun menulis)<br><span class='gd-jp'>休むことなく働いた。</span> (paling formal, terdengar bobotnya 「konsisten dari awal sampai akhir」)<br>Artinya sama, bedanya ada pada <b>tingkat kesopanan atau formalitas</b>.</div><div class='gd-sec'>Tapi 「ないで」 punya satu pemakaian lain: <b>tidak melakukan A, malah melakukan B</b>. Dalam kasus ini biasanya tidak dipakai ことなく.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車に乗らないで、歩いて帰った。</span>(Aku tidak naik kereta, tapi pulang dengan jalan kaki)</div><div class='gd-sec'>Kalau kalimat ini diganti jadi 「電車に乗ることなく」, hasilnya sangat tidak natural.</div><div class='gd-warn'>Trik cepat: untuk ngobrol pakai ないで, untuk agak formal pakai ずに, dan pakai ことなく kalau mau menulis ala berita atau pidato, atau menekankan 「sekali pun tidak」. Kalau maknanya 「tidak A, malah B」, serahkan ke ないで atau ずに.</div>","n2-49":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ようがない」artinya <b>「sama sekali tidak ada cara untuk ~」「mau ~ pun tidak tahu bagaimana」</b>. 「よう」di sini berarti 「cara」, jadi 「ようがない」berarti <b>tidak ada cara sama sekali</b>. Bukan karena kamu tidak mau, dan bukan juga karena kemampuanmu kurang. Keadaannya yang membuat kamu tidak menemukan jalan untuk memulai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kekurangan syarat atau sarana</span>Kamu ingin melakukannya, tapi tidak punya hal yang penting (informasi, alat, petunjuk), sehingga tidak tahu harus mulai dari mana.</div><div class='gd-ex-line'>・<span class='gd-jp'>住所も電話番号も知らないので、連絡しようがない。</span>（Alamat dan nomor teleponnya tidak tahu, jadi tidak ada cara untuk menghubungi）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部品はもう売っていないから、直しようがないね。</span>（Suku cadang ini sudah tidak dijual, jadi tidak bisa diperbaiki ya）</div><div class='gd-sec'><span class='gd-tag'>ようもない</span>Ada「も」di tengah, nuansanya lebih kuat, seperti 「tidak ada cara sedikit pun」.</div><div class='gd-ex-line'>・<span class='gd-jp'>道が雪で埋まっていて、進みようもなかった。</span>（Jalannya tertimbun salju, sama sekali tidak bisa maju）</div><div class='gd-sec'>Sering dipakai di tulisan maupun percakapan. Ke teman, bilang「<span class='gd-jp'>直しようがないよ</span>」juga terdengar sangat natural.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ambil bentuk ます pada kata kerja, buang ます, lalu tambahkan「ようがない」.<br><span class='gd-pair'><span class='gd-jp'>書きます</span> → buang ます → <span class='gd-jp'>書きようがない</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べようがない</span></span><span class='gd-pair'><span class='gd-jp'>連絡します</span> → <span class='gd-jp'>連絡しようがない</span></span></div><div class='gd-sec'><span class='gd-tag'>名詞＋のしようがない</span>Untuk kata benda seperti「連絡、説明、返事」, sering juga dipakai pola「kata benda＋の＋しようがない」.<br><span class='gd-pair'><span class='gd-jp'>説明しようがない</span> → <span class='gd-jp'>説明のしようがない</span></span>（keduanya benar）</div><div class='gd-sec'><span class='gd-tag'>Di depan kata benda</span>Sering「が」diganti「の」menjadi「ようのない＋kata benda」; 「ようがない＋kata benda」juga boleh.</div><div class='gd-ex-line'>・<span class='gd-jp'>言いようのない寂しさを感じた。</span>（Aku merasakan kesepian yang tak terkatakan）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Dalam percakapan, yang paling sering muncul adalah ungkapan tetap berikut:<br><span class='gd-jp'>どうしようもない</span>: bagaimanapun tidak ada jalan; bisa juga untuk memaki orang, artinya 「sudah tidak tertolong」.<br><span class='gd-jp'>しょうがない</span>: mau bagaimana lagi, ya sudahlah. Sebenarnya ini berasal dari「<span class='gd-jp'>しようがない</span>」yang diucapkan cepat.<br><span class='gd-jp'>言いようがない</span>: (sebegitu bagusnya / sebegitu buruknya) sulit dilukiskan.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨じゃしょうがないね。</span>（Kalau hujan, ya mau bagaimana lagi）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk ます</b>, bukan bentuk volitional: yang benar <span class='gd-jp'>書きようがない</span>, bukan「書こうがない」。<br>・「しよう」pada <span class='gd-jp'>連絡しようがない</span> tampak mirip dengan しよう yang berarti 「ayo kita lakukan」, padahal ini「し＋よう（cara）」, artinya sama sekali berbeda.<br>・Pola ini bicara tentang <b>tidak ada cara atau sarana</b>, bukan soal kemampuan. 「Aku tidak bisa berenang」harus <span class='gd-jp'>泳げない</span>, tidak boleh「泳ぎようがない」。</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasi yang sama: kamu ditanya sesuatu, tapi tidak bisa menjawab.<br><b>Bentuk potensial negatif</b>＝sekadar 「tidak bisa」, alasannya bisa apa saja: <span class='gd-jp'>その質問には答えられない。</span>（Pertanyaan itu tidak bisa kujawab）<br><b>ようがない</b>＝tidak ada informasi atau dasar, jadi <b>tidak tahu harus menjawab bagaimana</b>: <span class='gd-jp'>何も聞いていないので、答えようがない。</span>（Aku tidak diberi tahu apa-apa, jadi tidak ada cara untuk menjawab）<br><b>かねる</b>＝sebenarnya bisa menjawab, tapi <b>secara posisi tidak pantas</b>. Dipakai petugas layanan pelanggan atau pelayan toko untuk menolak dengan sopan: <span class='gd-jp'>その件についてはお答えしかねます。</span>（Mengenai hal itu, mohon maaf kami tidak dapat menjawab）</div><div class='gd-warn'>Trik menentukan: 「kurang cara, tidak tahu mulai dari mana」pakai ようがない; 「secara posisi tidak pantas, menolak dengan halus」pakai かねる; 「tidak bisa」dengan alasan apa saja pakai bentuk potensial negatif.</div>","n2-51":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜際（に）」adalah <b>versi formal</b> dari 「ketika ~」. Pengumuman di stasiun Jepang, pemberitahuan di toko, dan surat perusahaan sering memakainya. Terdengar lebih sopan daripada「時」dan lebih seperti pengumuman resmi, mirip \"pada saat\" atau \"tatkala\" dalam bahasa Indonesia yang formal.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Pengumuman・siaran</span>Saat berbicara kepada pelanggan atau masyarakat umum, untuk mengingatkan 「hal yang perlu diperhatikan ketika melakukan ini」.</div><div class='gd-ex-line'>・<span class='gd-jp'>お降りの際は、足元にご注意ください。</span>（Saat turun, harap hati-hati melangkah）</div><div class='gd-ex-line'>・<span class='gd-jp'>ご利用の際は、こちらのカードをお見せください。</span>（Saat menggunakan, harap tunjukkan kartu ini）</div><div class='gd-sec'><span class='gd-tag'>Bisnis・situasi formal</span>Menulis surat, atau berbicara dengan atasan atau klien.</div><div class='gd-ex-line'>・<span class='gd-jp'>先日お会いした際に、いろいろ教えていただきました。</span>（Waktu kita bertemu beberapa hari lalu, Anda mengajari saya banyak hal）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda</b>: tambahkan「の」lalu sambung 際.<br><span class='gd-pair'><span class='gd-jp'>入場</span> → <span class='gd-jp'>入場の際</span></span><span class='gd-pair'><span class='gd-jp'>申し込み</span> → <span class='gd-jp'>申し込みの際</span></span><br><b>Kata kerja</b>: bentuk kamus atau bentuk た langsung disambung 際.<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来る際</span></span><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った際</span></span></div><div class='gd-sec'>Beda bentuk kamus dan bentuk た sama seperti pada「時」: bentuk kamus untuk saat <b>belum dilakukan, baru mau dilakukan</b>; bentuk た untuk <b>setelah dilakukan, pada kesempatan itu</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行く際に、パスポートを作りました。</span>（Waktu mau pergi ke Jepang, aku membuat paspor: sebelum berangkat）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本へ行った際に、友達に会いました。</span>（Waktu pergi ke Jepang, aku bertemu teman: setelah tiba）</div><div class='gd-sec'>Kalau diikuti「に」, artinya 「pada saat ~」 yang biasa; kalau diganti「は」, muncul nuansa mengingatkan, \"kalau sedang begini, tolong…\". Karena itu pengumuman sering menulis「〜の際は」. Keduanya benar.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>「お／ご＋kata benda＋の際」: お dan ご di depan adalah bentuk hormat untuk pelanggan, hafalkan saja sebagai satu paket.<br><span class='gd-jp'>お帰りの際</span>（saat Anda pulang）、<span class='gd-jp'>お降りの際</span>（saat Anda turun）、<span class='gd-jp'>ご来店の際</span>（saat Anda datang ke toko）、<span class='gd-jp'>ご利用の際</span>（saat Anda menggunakan）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Setelah kata benda wajib ada「の」: yang benar <span class='gd-jp'>入場の際</span>, bukan 入場際.<br>・際 dibaca <b>さい</b>.<br>・Jangan dipakai dalam obrolan sehari-hari. Untuk 「waktu makan kemarin」cukup bilang <span class='gd-jp'>昨日ご飯を食べた時</span>; kalau bilang「食べた際」, terdengar seperti sedang menulis laporan.<br>・際 menyatakan <b>saat suatu tindakan dilakukan</b>, bukan untuk jangka waktu atau keadaan: 「waktu kecil」adalah <span class='gd-jp'>子どもの時</span>, bukan 子どもの際. Kata sifat juga biasanya tidak disambung dengan 際; 「waktu sibuk」harus <span class='gd-jp'>忙しい時</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasi yang sama: login ke sebuah situs web.<br><b>時</b>＝cara bicara umum, bisa dipakai di situasi apa saja: <span class='gd-jp'>ログインする時、パスワードを入れます。</span>（Saat login, kamu memasukkan kata sandi）<br><b>際</b>＝cara bicara formal, sering ada di pengumuman dan teks petunjuk: <span class='gd-jp'>ログインの際は、パスワードを入力してください。</span>（Saat login, harap masukkan kata sandi）<br><b>場合</b>＝\"jika terjadi ~\", tidak semua orang pasti mengalaminya: <span class='gd-jp'>パスワードを忘れた場合は、こちらをクリックしてください。</span>（Jika lupa kata sandi, silakan klik di sini）<br>Setiap orang yang login harus memasukkan kata sandi, jadi dipakai 際; hanya sebagian orang yang lupa kata sandi, jadi dipakai 場合.</div><div class='gd-warn'>Trik menentukan: ngobrol dengan teman pakai「時」; menulis pengumuman atau berbicara dengan pelanggan pakai「際」; 「kalau sampai ~」pakai「場合」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜に先立って」juga bentuk formal, artinya 「sebelum ~」: <span class='gd-jp'>開会に先立って、社長が挨拶をしました。</span>（Sebelum rapat dibuka, presiden direktur memberikan sambutan terlebih dahulu）</div>","n2-60":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜あげく」kira-kira artinya <b>「sudah capek-capek ke sana kemari, ujung-ujungnya malah…」「setelah repot setengah mati, akhirnya…」</b>. Bagian depan adalah proses yang panjang dan melelahkan, sedangkan bagian belakang biasanya hasil yang bikin pasrah dan tidak diinginkan. Si pembicara sering terdengar mengeluh atau merasa “sia-sia”.</div><div class='gd-ex-line'>・<span class='gd-jp'>さんざん待たされたあげく、満席だと言われた。</span>（Dibiarkan menunggu lama sekali, eh ujung-ujungnya dibilang penuh）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja pakai <b>bentuk た</b> (bentuk lampau), lalu sambung dengan <span class='gd-jp'>あげく</span>：<br><span class='gd-pair'><span class='gd-jp'>迷う</span> → <span class='gd-jp'>迷ったあげく</span></span><span class='gd-pair'><span class='gd-jp'>悩む</span> → <span class='gd-jp'>悩んだあげく</span></span><br>Kata benda ditambah 「の」 dulu, baru disambung：<br><span class='gd-pair'><span class='gd-jp'>議論</span> → <span class='gd-jp'>議論のあげく</span></span><span class='gd-pair'><span class='gd-jp'>けんか</span> → <span class='gd-jp'>けんかのあげく</span></span><br>Setelahnya boleh ditambah 「に」 atau tidak, artinya sama saja. Kanjinya ditulis <span class='gd-jp'>挙げ句</span>, jadi kenali juga ya kalau ketemu.</div><div class='gd-h'>Pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Usaha sia-sia</span>Di depan sering dipasangkan dengan <span class='gd-jp'>さんざん</span> (habis-habisan, berkali-kali) atau <span class='gd-jp'>何度も</span> (berkali-kali), dan di belakang sering ada <span class='gd-jp'>結局</span> (pada akhirnya).</div><div class='gd-ex-line'>・<span class='gd-jp'>さんざん迷ったあげく、結局何も買わなかった。</span>（Bingung lama sekali, ujung-ujungnya tidak beli apa-apa）</div><div class='gd-ex-line'>・<span class='gd-jp'>長時間の議論のあげく、何も決まらなかった。</span>（Berdebat lama sekali, ujung-ujungnya tidak ada yang diputuskan）</div><div class='gd-sec'><span class='gd-tag'>Keputusan terpaksa</span>Sudah lama memikirkannya, lalu akhirnya terpaksa mengambil suatu keputusan.</div><div class='gd-ex-line'>・<span class='gd-jp'>悩んだあげく、旅行には行かないことにした。</span>（Galau lama sekali, akhirnya memutuskan tidak jadi pergi liburan）</div><div class='gd-sec'><span class='gd-tag'>あげくの果てに</span>Ungkapan tetap yang artinya 「pada akhirnya bahkan sampai…」, dipakai untuk menceritakan keadaan yang makin lama makin buruk sampai ke tahap yang paling parah.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は遅刻を繰り返し、あげくの果てに無断で休んだ。</span>（Dia terus-terusan terlambat, dan pada akhirnya bahkan bolos tanpa izin）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata kerja harus pakai bentuk た：<span class='gd-jp'>迷うあげく</span> itu salah, yang benar <span class='gd-jp'>迷ったあげく</span>.<br>・Bagian depan harus berupa proses yang <b>berlarut-larut atau terjadi berulang kali</b>. Tindakan yang selesai sekejap tidak bisa dipakai: <span class='gd-jp'>ドアを開けたあげく</span> dan <span class='gd-jp'>一度電話したあげく</span> terdengar aneh. Baru natural kalau seperti <span class='gd-jp'>何度も電話したあげく、やっと通じたと思ったら留守電だった。</span>（Sudah berkali-kali menelepon, kirain akhirnya tersambung, eh ternyata kotak suara）<br>・Bagian belakang adalah <b>hasil akhir yang sudah terjadi</b>, jadi akhir kalimatnya biasanya bentuk lampau. Tidak bisa disambung dengan hal yang belum terjadi, seperti ajakan 「ayo ～」 atau permintaan 「tolong ～」.<br>・Jangan dipakai kalau hasilnya bagus: <span class='gd-jp'>努力したあげく合格した</span> terdengar aneh, gantilah dengan <span class='gd-jp'>末に</span> di bawah ini.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b><span class='gd-jp'>末に</span></b> juga berarti 「setelah melalui proses ～, pada akhirnya…」, dan cara menyambungnya sama (bentuk た／kata benda の＋<span class='gd-jp'>末に</span>). Bedanya, <span class='gd-jp'>末に</span> nadanya <b>lebih netral</b>: bisa untuk hasil baik maupun buruk, dan sering dipakai di berita atau tulisan formal. Sedangkan <span class='gd-jp'>あげく</span> terasa seperti keluhan 「sudah capek-capek, hasilnya tetap begitu」, jadi hampir selalu untuk hasil yang buruk.<br>Contohnya sama-sama rapat yang lama:<br><span class='gd-jp'>何度も話し合った末に、新しい計画が決まった。</span>（Berdiskusi berkali-kali, dan akhirnya rencana baru pun diputuskan: hasil baik, hanya bisa pakai <span class='gd-jp'>末に</span>）<br><span class='gd-jp'>何度も話し合ったあげく、結局何も決まらなかった。</span>（Berdiskusi berkali-kali, ujung-ujungnya tidak ada yang diputuskan: nada mengeluh, paling pas pakai <span class='gd-jp'>あげく</span>）</div><div class='gd-warn'>Trik cepat: kalau hasilnya baik atau hanya sekadar diceritakan apa adanya, pakai <span class='gd-jp'>末に</span>; kalau mau mengeluh 「sudah capek-capek, ujung-ujungnya…」, pakai <span class='gd-jp'>あげく</span>.</div>","n2-61":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜てはじめて」kira-kira artinya <b>「setelah ～ baru (mengerti／sadar)…」「baru ketika ～ barulah…」</b>. Seperti kata pepatah, 「baru terasa berharga setelah hilang」: bagian depan adalah hal yang kamu <b>alami sendiri</b>, dan bagian belakang adalah hal yang <b>baru akhirnya kamu pahami atau rasakan untuk pertama kali</b> setelah mengalaminya. Intinya: sebelum itu, sebenarnya kamu belum paham.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk て dari kata kerja, lalu langsung tambahkan 「はじめて」 (sering juga ditulis dengan kanji 「初めて」).<br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なって</span> → <span class='gd-jp'>なってはじめて</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してはじめて</span></span><br><span class='gd-pair'><span class='gd-jp'>言われる</span> → <span class='gd-jp'>言われて</span> → <span class='gd-jp'>言われてはじめて</span></span><br>Biasanya setelah itu diberi koma, lalu disambung dengan hal yang baru disadari.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Baru paham setelah mengalami</span>Bagian belakang paling sering diisi kata-kata yang berarti 「mengerti／menyadari」 seperti <span class='gd-jp'>わかる</span>、<span class='gd-jp'>気づく</span>、<span class='gd-jp'>知る</span>、<span class='gd-jp'>実感する</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>親になってはじめて、親の気持ちがわかった。</span>（Setelah jadi orang tua sendiri, baru mengerti perasaan orang tua）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしをしてはじめて、家事の大変さに気づいた。</span>（Setelah tinggal sendiri, baru sadar betapa repotnya mengurus pekerjaan rumah）</div><div class='gd-ex-line'>・<span class='gd-jp'>言われてはじめて気づきました。</span>（Baru sadar setelah diberi tahu）</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan hal yang berlaku umum</span>Pakai bentuk kini, untuk mengatakan 「manusia itu baru paham setelah mengalaminya」.</div><div class='gd-ex-line'>・<span class='gd-jp'>病気になってはじめて、健康のありがたさがわかる。</span>（Baru setelah sakit kita tahu betapa berharganya kesehatan）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bagian belakang <b>tidak boleh berisi niat sendiri, perintah, atau permintaan</b>.<br>×<span class='gd-jp'>日本に来てはじめて、日本語を勉強しよう。</span><br>Yang ditaruh di belakang harus 「kesadaran atau perubahan yang sudah terjadi」, bukan 「aku mau melakukan apa」.<br>・Jangan tertukar dengan 「kata kerja bentuk ます＋<span class='gd-jp'>はじめる</span>」 (mulai ～): <span class='gd-jp'>食べはじめる</span> artinya 「mulai makan」, sedangkan <span class='gd-jp'>食べてはじめて</span> artinya 「baru setelah makan…」. Bedanya cuma ada tidaknya 「て」 di tengah.<br>・Pola ini membawa kesan 「sebelumnya tidak tahu」, jadi kalau dipakai untuk hal yang memang sudah diketahui atau sudah jelas, hasilnya terdengar aneh.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama bermakna 「harus dicoba dulu baru tahu」, tapi lihat dua pola ini:<br><b>てはじめて</b> = melihat ke belakang, <b>baru paham setelah melakukannya</b>: <span class='gd-jp'>実際に使ってみてはじめて、よさがわかった。</span>（Setelah benar-benar dipakai, baru tahu bagusnya）<br><b>ないことには</b> = menyebut syarat ke depan, <b>kalau tidak dilakukan dulu, tidak akan bisa</b>, dan bagian belakangnya biasanya negatif: <span class='gd-jp'>実際に使ってみないことには、よさはわからない。</span>（Kalau tidak benar-benar dicoba, kita tidak akan tahu bagus atau tidaknya）</div><div class='gd-warn'>Trik cepat: untuk 「baru tercerahkan setelah mengalaminya」 pakai てはじめて; untuk 「kalau tidak ～ dulu, tidak akan bisa…」 pakai ないことには.</div>","n2-63":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜ものがある」kurang lebih artinya <b>\"ada sesuatu yang ～ di situ\"</b> atau <b>\"memang terasa ～\"</b>. Misalnya kamu mendengarkan sebuah penampilan musik atau melihat foto lama, hatimu tersentuh oleh sesuatu, tapi kamu tidak bisa menjelaskan persisnya apa. Nah, bahasa Jepang memakai pola ini untuk itu: <span class='gd-jp'>彼の演奏には心を打つものがある。</span>（Permainannya punya kekuatan yang menyentuh hati）<br>Di sini <span class='gd-jp'>もの</span> bukan benda yang bisa dilihat, melainkan <b>kualitas atau kesan yang sulit diungkapkan dengan kata-kata</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menilai orang atau hal</span>Dipakai untuk memuji karya, penampilan, atau kemampuan. Dibanding langsung bilang \"hebat banget\", pola ini terdengar lebih berbobot dan tenang. Sering muncul di ulasan film, berita, dan komentar atasan.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の演奏には人を引き込むものがある。</span>（Permainannya punya daya tarik yang memikat orang）</div><div class='gd-ex-line'>・<span class='gd-jp'>新人だが、彼女の企画には光るものがある。</span>（Meski orang baru, rencana proyeknya punya sisi yang menonjol）</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan perasaan sendiri</span>Dipakai saat sesuatu menimbulkan perasaan tertentu di dirimu, baik yang enak maupun yang tidak.</div><div class='gd-ex-line'>・<span class='gd-jp'>この古い写真にはどこか懐かしいものがある。</span>（Foto lama ini entah kenapa terasa membangkitkan nostalgia）</div><div class='gd-ex-line'>・<span class='gd-jp'>この年で徹夜するのは、つらいものがある。</span>（Di usia segini begadang itu benar-benar berat）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja: langsung bentuk kamus　<span class='gd-pair'><span class='gd-jp'>心を打つ</span> → <span class='gd-jp'>心を打つものがある</span></span><br>Kata sifat-い: langsung disambung　<span class='gd-pair'><span class='gd-jp'>懐かしい</span> → <span class='gd-jp'>懐かしいものがある</span></span><br>Kata sifat-な: tambahkan「な」　<span class='gd-pair'><span class='gd-jp'>見事</span> → <span class='gd-jp'>見事なものがある</span></span><br>Bentuk negatif juga bisa: <span class='gd-pair'><span class='gd-jp'>納得できない</span> → <span class='gd-jp'>納得できないものがある</span></span>（agak sulit diterima）<br>Di depannya sering ada「<span class='gd-jp'>〜には</span>」untuk menyebut \"tokoh utamanya\": <span class='gd-jp'>この映画には</span>、<span class='gd-jp'>彼の言葉には</span>……</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'>Beberapa ini hampir selalu dipakai sebagai satu paket, jadi paling cepat kalau dihafal sekaligus:<br><span class='gd-jp'>心を打つものがある</span>（menyentuh hati）<br><span class='gd-jp'>胸に迫るものがある</span>（sangat menggugah perasaan）<br><span class='gd-jp'>目を見張るものがある</span>（mengagumkan, membuat orang terperangah）<br><span class='gd-jp'>光るものがある</span>（punya sisi yang menonjol）<br><span class='gd-jp'>見るべきものがある</span>（ada hal yang layak dilihat）<br><span class='gd-jp'>感慨深いものがある</span>（membuat hati penuh perasaan mendalam）</div><div class='gd-h'>Yang sering salah</div><div class='gd-warn'>・<b>Tidak semua「ものがある」adalah pola tata bahasa ini</b>: <span class='gd-jp'>この店にはおいしいものがある。</span> artinya hanya \"toko ini punya makanan enak\", yaitu makanan sungguhan. Untuk pola ini, \"tokoh utamanya\" biasanya hal abstrak seperti karya, penampilan, atau pengalaman.<br>・<b>Bentuk lampau ditaruh di ある</b>: untuk \"waktu itu aku terharu\" katakan <span class='gd-jp'>心を打つものがあった</span>, jangan ditulis 心を打ったものがある.<br>・<b>Jangan lupa な pada kata sifat-な</b>: yang benar <span class='gd-jp'>見事なものがある</span>, bukan 見事ものがある, dan tidak bisa langsung disambung ke kata benda.<br>・<b>Jangan dipakai untuk fakta objektif</b>: besar atau tidaknya kamar bisa diukur, jadi cukup bilang <span class='gd-jp'>この部屋は広い</span>. Kalau kamu bilang 「この部屋には広いものがある」, terdengar aneh. Pola ini untuk kualitas yang \"menimbulkan kesan\".<br>・Nuansanya cenderung formal, tapi dalam percakapan juga dipakai, seperti <span class='gd-jp'>それはちょっとつらいものがあるね</span>（itu memang agak berat ya）.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ものだ（ungkapan perasaan）</b>＝\"ya ampun, ～ banget ya\", ungkapan perasaan tentang <b>hal umum atau kehidupan</b>:<br><span class='gd-jp'>子どもの成長は早いものだ。</span>（Anak-anak itu cepat sekali besarnya ya）<br><b>ものがある</b>＝menunjuk <b>orang atau hal tertentu</b> dan mengatakan ada kualitas tertentu padanya:<br><span class='gd-jp'>彼の成長ぶりには目を見張るものがある。</span>（Perkembangannya mengagumkan）</div><div class='gd-warn'>Trik membedakan: kalau kamu mengungkapkan perasaan \"begitulah hidup dan dunia ini\", pakai ものだ. Kalau kamu menunjuk orang atau karya di depanmu dan bilang \"ada sisi ～ padanya\", pakai ものがある.</div>","n2-64":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜抜き」itu seperti saat memesan minuman dengan \"tanpa es\" atau memesan mi dengan \"tanpa seledri\": kamu <b>mengeluarkan sesuatu yang seharusnya ada</b>. Di Jepang, saat makan sushi, kalau bilang <span class='gd-jp'>わさび抜きでお願いします</span>, artinya \"tolong jangan pakai wasabi\". Di depannya selalu <b>kata benda</b>, dan biasanya ditulis dengan kanji <span class='gd-jp'>抜き</span>, dibaca ぬき.</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>抜きで＋tindakan</span>Melakukan sesuatu tanpa hal tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>わさび抜きでお願いします。</span>（Tolong tanpa wasabi ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>今朝は朝ごはん抜きで会社に行った。</span>（Tadi pagi aku berangkat ke kantor tanpa sarapan）</div><div class='gd-sec'><span class='gd-tag'>抜きの＋kata benda</span>Disambung ke kata benda, artinya \"yang ～-nya dibuang\".</div><div class='gd-ex-line'>・<span class='gd-jp'>玉ねぎ抜きのハンバーガーをください。</span>（Tolong burger tanpa bawang bombai）</div><div class='gd-sec'><span class='gd-tag'>冗談抜きで</span>Ungkapan tetap yang artinya \"serius deh, tanpa bercanda\". Sangat sering dipakai dalam percakapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談抜きで、このラーメンは日本一だと思う。</span>（Serius deh, menurutku ramen ini nomor satu di Jepang）</div><div class='gd-sec'><span class='gd-tag'>抜きには〜ない</span>\"Tanpa ～ tidak bisa ～\", untuk menekankan betapa pentingnya hal itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の協力抜きには、この仕事は終わらなかった。</span>（Tanpa bantuannya, pekerjaan ini tidak akan selesai）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の夏は花火抜きには語れない。</span>（Musim panas Jepang tidak bisa dibicarakan tanpa kembang api）</div><div class='gd-sec'><span class='gd-tag'>は抜きにして</span>\"～ tidak usah dulu, kita kesampingkan ～\". Sering terdengar saat acara makan bersama atau pembukaan rapat.</div><div class='gd-ex-line'>・<span class='gd-jp'>堅苦しい挨拶は抜きにして、乾杯しましょう。</span>（Basa-basi formal tidak usah ya, ayo bersulang）</div><div class='gd-h'>Yang sering salah</div><div class='gd-warn'>・Hanya bisa disambung ke <b>kata benda</b>. \"Tidak sarapan\" tidak bisa dibilang 食べ抜きで. Katakan <span class='gd-jp'>朝ごはん抜きで</span>, atau pakai kata kerja <span class='gd-jp'>朝ごはんを食べないで</span>.<br>・Kesan 抜き adalah \"sebenarnya ada, tapi sengaja dikeluarkan\". Kalau hal itu memang belum tentu ada, misalnya keluar rumah tanpa membawa payung, lebih natural bilang <span class='gd-jp'>傘なしで出かけた</span>.<br>・Setelah「抜きには」hampir selalu ada makna negatif atau \"tidak bisa\", misalnya <span class='gd-jp'>できない</span>、<span class='gd-jp'>語れない</span>、<span class='gd-jp'>考えられない</span>. Jangan disambung dengan kalimat positif biasa.<br>・<span class='gd-jp'>冗談抜きで</span> biasanya dipakai pembicara untuk menegaskan \"yang kukatakan selanjutnya serius\", bukan untuk menyuruh lawan bicara \"jangan bercanda\". Bisa juga bilang <span class='gd-jp'>冗談抜きに</span>, artinya sama.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>抜きには〜ない</b> dan <b>ないことには</b>（n2-19）sama-sama berarti \"kalau tidak ada／tidak ～, tidak bisa ～\". Bedanya ada pada apa yang disambung di depannya:<br>・<span class='gd-jp'>社長の許可抜きには決められない。</span>（Tanpa izin direktur, tidak bisa diputuskan）: di depannya kata benda<br>・<span class='gd-jp'>社長が許可しないことには決められない。</span>（Kalau direktur tidak menyetujui, tidak bisa diputuskan）: di depannya kata kerja</div><div class='gd-sec'><b>抜きで</b> dan <b>ことなく</b>（n2-48）sama-sama bisa diterjemahkan \"melakukan tanpa ～\":<br>・<span class='gd-jp'>休憩抜きで働いた。</span>（Bekerja tanpa istirahat）: mengeluarkan kata benda \"waktu istirahat\"<br>・<span class='gd-jp'>休むことなく働いた。</span>（Bekerja tanpa berhenti sama sekali）: di depannya kata kerja, nuansanya lebih tulisan</div><div class='gd-warn'>Trik membedakan: kalau di depannya <b>kata benda</b>, pakai 抜き. Kalau di depannya <b>kata kerja</b>, ganti ke ないことには atau ことなく.</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'>抜き berasal dari kata kerja <span class='gd-jp'>抜く</span>（mengeluarkan, melewatkan）, dan dalam kehidupan sehari-hari kata kerjanya juga sering langsung dipakai: <span class='gd-jp'>忙しくて昼ごはんを抜いた。</span>（Sibuk sekali, jadi aku melewatkan makan siang）</div>","n2-58":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜とは限らない」setara dengan <b>「belum tentu ～」「tidak selalu ～」</b>. Saat semua orang mengira \"pasti begitu\", kamu menyela: \"Belum tentu lho, ada pengecualiannya.\" Seperti ungkapan \"yang mahal belum tentu bagus\", dalam bahasa Jepang jadi <span class='gd-jp'>高いものがいいとは限らない。</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mematahkan stereotip</span>Mengerem anggapan yang \"dianggap wajar oleh semua orang\".</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人がみんな寿司が好きだとは限らない。</span>(Belum tentu semua orang Jepang suka sushi)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の言うことがいつも正しいとは限らない。</span>(Ucapan guru belum tentu selalu benar)</div><div class='gd-sec'><span class='gd-tag'>Mengingatkan adanya risiko</span>Hasilnya tidak dijamin sesuai harapan, jadi bersiap-siaplah lebih dulu.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報が当たるとは限らないから、傘を持っていこう。</span>(Ramalan cuaca belum tentu tepat, bawa payung saja)</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Taruh kalimat lengkap di depan (bentuk biasa, yaitu tanpa です・ます), lalu langsung sambung とは限らない.<br>Verba: <span class='gd-pair'><span class='gd-jp'>成功する</span> → <span class='gd-jp'>成功するとは限らない</span></span><br>Kata sifat-い: <span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いとは限らない</span></span><br>Kata sifat-な: <span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利だとは限らない</span></span> (だ juga sering dihilangkan: <span class='gd-jp'>便利とは限らない</span>)<br>Nomina: <span class='gd-pair'><span class='gd-jp'>本物だ</span> → <span class='gd-jp'>本物だとは限らない</span></span> (boleh juga bilang <span class='gd-jp'>本物とは限らない</span>)<br>Kepada orang yang lebih tua atau dalam situasi formal, pakai <span class='gd-jp'>とは限りません</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>必ずしも〜</span>Tambahkan <span class='gd-jp'>必ずしも</span> (belum tentu) di depan, jadi nuansa \"belum tentu\" terasa lebih jelas. Sering muncul di tulisan.</div><div class='gd-ex-line'>・<span class='gd-jp'>有名な大学を出た人が、必ずしも仕事ができるとは限らない。</span>(Lulusan universitas ternama belum tentu pandai bekerja)</div><div class='gd-sec'><span class='gd-tag'>からといって〜</span>Artinya \"tidak bisa serta-merta bilang pasti ～ hanya karena ～\". Paling gampang kalau dihafal sebagai satu kalimat utuh.</div><div class='gd-ex-line'>・<span class='gd-jp'>安いからといって、お得だとは限らない。</span>(Murah bukan berarti pasti untung)</div><div class='gd-sec'><span class='gd-tag'>みんな・いつも・全て</span>Di depannya sering muncul kata-kata \"semua, setiap kali\" ini, karena とは限らない memang dipakai untuk membantah anggapan \"semuanya begitu\".</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Artinya \"<b>belum tentu</b>\", bukan \"<b>bukan</b>\". <span class='gd-jp'>高いものがいいとは限らない</span> hanya bilang yang mahal tidak dijamin bagus, bukan bilang barang mahal itu jelek.<br>・<span class='gd-jp'>必ずしも</span> harus diikuti bentuk negatif. Tidak bisa bilang 「必ずしもいい」, harus <span class='gd-jp'>必ずしもいいとは限らない</span>.<br>・Hati-hati dengan <span class='gd-jp'>〜ないとも限らない</span>, artinya justru berbalik: <span class='gd-jp'>事故が起きないとも限らない。</span> berarti \"tidak bisa dijamin tidak akan terjadi kecelakaan\", yaitu <b>tetap mungkin terjadi kecelakaan</b>. Dipakai untuk mengingatkan agar berhati-hati.<br>・限る dibaca <b>かぎる</b>, jadi かぎらない. Jangan dibaca げんらない.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama membahas \"apakah akhir pekan ramai\":<br><b>に限らず</b>＝bukan hanya ～ (cakupan lebih luas): <span class='gd-jp'>この店は週末に限らず、いつも混んでいる。</span> (Toko ini tidak hanya di akhir pekan, hari biasa pun selalu ramai)<br><b>とは限らない</b>＝belum tentu ～ (ada pengecualian): <span class='gd-jp'>週末だからといって、混んでいるとは限らない。</span> (Meski akhir pekan, belum tentu ramai)<br><b>に決まっている</b>＝pasti ～ (sangat yakin): <span class='gd-jp'>週末だから、混んでいるに決まっている。</span> (Ini kan akhir pekan, pasti ramai)</div><div class='gd-warn'>Trik membedakan: <b>nomina＋に限らず</b>＝\"bukan hanya ～\"; <b>seluruh kalimat＋とは限らない</b>＝\"belum tentu ～\". Kalau mau bilang \"pasti\", pakai に決まっている. Kalau mau bilang \"belum tentu\", pakai とは限らない.</div>","n2-59":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「<span class='gd-jp'>〜をきっかけに</span>」setara dengan <b>「berawal dari ～, lalu mulai…」「memanfaatkan momen ～, lalu…」</b>. Di depan ditaruh satu kejadian yang memicumu, di belakang ditaruh <b>tindakan baru atau perubahan yang dimulai</b> karenanya. Contohnya \"karena datang ke Jepang, mulai masak sendiri\" atau \"karena sakit, mulai memperhatikan kesehatan\".</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たのをきっかけに、料理を始めた。</span>(Sejak datang ke Jepang, aku mulai masak sendiri)</div><div class='gd-ex-line'>・<span class='gd-jp'>入院をきっかけに、健康に気をつけるようになった。</span>(Setelah dirawat di rumah sakit, aku jadi mulai memperhatikan kesehatan)</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><span class='gd-tag'>Nomina</span>Langsung disambung: <span class='gd-pair'><span class='gd-jp'>留学</span> → <span class='gd-jp'>留学をきっかけに</span></span><br><span class='gd-tag'>Verba</span>Tambahkan 「の」 atau 「こと」 dulu untuk menjadikannya satu \"hal\", baru disambung: <span class='gd-pair'><span class='gd-jp'>子どもが生まれた</span> → <span class='gd-jp'>子どもが生まれたのをきっかけに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが生まれたのをきっかけに、タバコをやめた。</span>(Setelah anakku lahir, aku berhenti merokok)</div><div class='gd-sec'>Di belakangnya sering dipasangkan dengan 「<span class='gd-jp'>始めた</span>」「<span class='gd-jp'>ようになった</span>」「<span class='gd-jp'>やめた</span>」, yaitu ungkapan yang menyatakan \"mulai, berubah\".</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>がきっかけで</span>Menjadikan pemicunya sebagai tokoh utama kalimat. Sering dipakai dalam percakapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達の一言がきっかけで、転職を考えるようになった。</span>(Gara-gara satu kata dari temanku, aku mulai mempertimbangkan pindah kerja)</div><div class='gd-sec'><span class='gd-tag'>きっかけは〜</span>Pertanyaan yang sangat sering muncul saat wawancara dan perkenalan diri.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語を始めたきっかけは何ですか。</span>(Apa yang membuatmu mulai belajar bahasa Jepang?)</div><div class='gd-ex-line'>・<span class='gd-jp'>アニメがきっかけです。</span>(Gara-gara anime)</div><div class='gd-sec'><span class='gd-tag'>をきっかけとして</span>Artinya sama, tapi lebih formal. Lebih sering terlihat di berita dan tulisan.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Sebelum verba harus ada 「の」 atau 「こと」. Harus bilang <span class='gd-jp'>日本に来たのをきっかけに</span>, tidak boleh langsung 「日本に来たをきっかけに」.<br>・「を」berpasangan dengan 「に」, 「が」berpasangan dengan 「で」: <span class='gd-jp'>留学をきっかけに</span>／<span class='gd-jp'>留学がきっかけで</span>. Dua pasangan ini jangan dipisah dan dicampur sembarangan.<br>・Pola ini menyatakan \"pemicu yang membuatmu memulai hal baru\", bukan sekadar sebab. Untuk akibat langsung seperti \"kereta berhenti karena hujan deras\", cukup pakai <span class='gd-jp'>大雨で電車が止まった</span>. Kalau pakai きっかけ malah terdengar aneh.<br>・Di depan boleh diisi hal baik maupun buruk. Sakit, putus cinta, atau dimarahi pun bisa jadi きっかけ.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama soal \"pindah rumah\":<br><b>をきっかけに</b>＝pindah rumah <b>memicu</b> kamu mulai melakukan hal baru:<br><span class='gd-jp'>引っ越しをきっかけに、ジョギングを始めた。</span> (Memanfaatkan momen pindahan, aku mulai jogging)<br><b>て以来</b>＝<b>sejak</b> itu, terus bertahan dalam satu keadaan:<br><span class='gd-jp'>引っ越して以来、毎朝ジョギングしている。</span> (Sejak pindah, aku jogging setiap pagi)<br><b>に伴って</b>＝hal yang <b>ikut</b> terjadi bersama pindahan, bukan hal yang kamu lakukan karena terinspirasi:<br><span class='gd-jp'>引っ越しに伴って、住所変更の手続きをした。</span> (Seiring pindahan, aku sekalian mengurus perubahan alamat)</div><div class='gd-warn'>Trik membedakan: \"Karena hal itu, aku mulai ～\" berarti をきっかけに; \"sejak itu terus ～\" berarti て以来; \"begitu hal itu terjadi, otomatis ikut ～\" berarti に伴って.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Ada bentuk yang lebih formal, yaitu 「<span class='gd-jp'>〜を機に</span>」「<span class='gd-jp'>〜を契機に</span>」, yang sering muncul di pengumuman perusahaan dan berita: <span class='gd-jp'>結婚を機に、仕事を辞めた。</span> (Memanfaatkan momen menikah, aku berhenti kerja)</div>","n2-65":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜きる」artinya <b>\"sampai habis\", \"sampai tuntas\", \"sepenuhnya\"</b>: berlari sampai garis finis, uang habis terpakai, capek banget.<br>「〜きれる」berarti <b>bisa dihabiskan</b>, dan 「〜きれない」berarti <b>tidak bisa dihabiskan, tidak habis-habis</b>. Intinya selalu sama: semuanya, sampai tuntas, tanpa sisa.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ambil bentuk ます dari kata kerja, buang ます, lalu sambungkan dengan <span class='gd-jp'>きる</span>.<br><span class='gd-pair'><span class='gd-jp'>走ります</span> → buang ます → <span class='gd-jp'>走りきる</span></span><br><span class='gd-pair'><span class='gd-jp'>食べます</span> → <span class='gd-jp'>食べきる</span></span><span class='gd-pair'><span class='gd-jp'>使います</span> → <span class='gd-jp'>使いきる</span></span><br><span class='gd-jp'>する</span> dipakai pada kata seperti <span class='gd-jp'>説明する</span>: <span class='gd-pair'><span class='gd-jp'>説明します</span> → <span class='gd-jp'>説明しきる</span></span><br>Setelah tersambung, <span class='gd-jp'>きる</span> sendiri berubah seperti kelompok I (verba godan): <span class='gd-jp'>きった</span> (sudah habis/tuntas), <span class='gd-jp'>きれる</span> (bisa dihabiskan), <span class='gd-jp'>きれない</span> (tidak bisa dihabiskan).</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Dilakukan sampai akhir, semuanya selesai</span>Tidak menyerah di tengah jalan, atau tidak ada yang tersisa sama sekali.</div><div class='gd-ex-line'>・<span class='gd-jp'>フルマラソンを走りきった。</span>(Aku berhasil menyelesaikan lari maraton penuh)</div><div class='gd-ex-line'>・<span class='gd-jp'>給料を三日で使いきってしまった。</span>(Gajiku habis dalam tiga hari)</div><div class='gd-sec'><span class='gd-tag'>Sampai batas maksimal</span>Dipakai setelah kata kerja yang menunjukkan keadaan seperti <span class='gd-jp'>疲れる</span> dan <span class='gd-jp'>困る</span>. Artinya \"benar-benar ~\", \"~ banget\".</div><div class='gd-ex-line'>・<span class='gd-jp'>残業続きで、疲れきっている。</span>(Lembur terus, capek banget)</div><div class='gd-ex-line'>・<span class='gd-jp'>そんな分かりきったこと、聞かないでよ。</span>(Hal yang sudah jelas banget begitu, jangan ditanyakan dong)</div><div class='gd-sec'><span class='gd-tag'>Mengatakan dengan yakin</span><span class='gd-jp'>言いきる</span> = menegaskan, bicara tegas tanpa menyisakan jalan mundur.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は「絶対に勝つ」と言いきった。</span>(Dia menegaskan, \"Pasti menang\")</div><div class='gd-sec'><span class='gd-tag'>きれる／きれない</span>Menanyakan apakah bisa dihabiskan, atau menyatakan jumlahnya terlalu banyak untuk dihabiskan.</div><div class='gd-ex-line'>・<span class='gd-jp'>こんなにたくさん、一人で食べきれる？</span>(Sebanyak ini, kamu sanggup menghabiskannya sendirian?)</div><div class='gd-ex-line'>・<span class='gd-jp'>空に数えきれないほど星が出ている。</span>(Bintang di langit banyak sekali sampai tak terhitung)</div><div class='gd-ex-line'>・<span class='gd-jp'>明日からの旅行が待ちきれない。</span>(Aku sudah tidak sabar menunggu liburan mulai besok)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Sambungkan dengan bentuk ます yang ます-nya dibuang, bukan bentuk kamus: yang benar <span class='gd-jp'>食べきる</span>, bukan 「食べるきる」。<br>・<span class='gd-jp'>食べきれない</span> khusus berarti \"jumlahnya terlalu banyak, tidak sanggup menghabiskan semuanya\". <span class='gd-jp'>食べられない</span> cakupannya lebih luas: bisa berarti \"tidak bisa makan\" (alergi, tidak berani makan), bisa juga \"sudah tidak sanggup makan lagi\" (<span class='gd-jp'>もうお腹いっぱいで食べられない</span>). Kalau kamu ingin jelas mengatakan \"porsinya kebanyakan, tidak habis\", pakai <span class='gd-jp'>食べきれない</span> supaya tidak disalahpahami.<br>・<span class='gd-jp'>待ちきれない</span> artinya \"tidak sabar menunggu\", bukan \"tidak habis ditunggu\".<br>・<span class='gd-jp'>疲れきる</span> bukan \"capeknya sudah selesai, jadi tidak capek lagi\", tapi \"capek sampai batas maksimal\". Jangan terkecoh oleh kesan kata \"selesai\".<br>・Kanjinya boleh ditulis <span class='gd-jp'>切る</span> (<span class='gd-jp'>食べ切る</span>), itu juga benar. Tapi ini bukan <span class='gd-jp'>着る</span> yang berarti memakai baju.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>〜終わる</b> = tindakan itu <b>sudah berakhir</b>. Entah semuanya habis atau tidak, bukan itu poinnya:<br></div><div class='gd-ex-line'>・<span class='gd-jp'>もうご飯食べ終わった？</span>(Kamu sudah selesai makan? : menanyakan apakah kegiatan makannya sudah berakhir)</div><div class='gd-sec'><b>〜きる</b> = <b>semuanya, tanpa sisa</b>, sering terasa \"jumlahnya banyak, tidak mudah\":</div><div class='gd-ex-line'>・<span class='gd-jp'>こんなに多いのに、全部食べきったの？</span>(Sebanyak ini, kamu habiskan semuanya?)</div><div class='gd-warn'>Trik cepat: kalau mau bilang \"sudah selesai\", pakai <span class='gd-jp'>終わる</span>. Kalau mau menekankan \"habis semua, bertahan sampai akhir, tanpa sisa\", pakai <span class='gd-jp'>きる</span>.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kebalikannya adalah <span class='gd-jp'>〜かける</span> (setengah jalan): <span class='gd-jp'>食べかけのパン</span> adalah \"roti yang baru dimakan setengah\", sedangkan <span class='gd-jp'>食べきる</span> adalah \"dimakan sampai habis\". Kalau dihafal berdua, gampang dibedakan.</div>","n2-66":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜に先立って」adalah <b>\"sebelum ~, terlebih dahulu ~\"</b> dalam situasi resmi. Seperti pembawa acara yang bilang \"Sebelum upacara dimulai, kita persilakan penyelenggara memberi sambutan\", atau berita yang bilang \"Sebelum produk baru diluncurkan, diadakan konferensi pers\". Itulah \"sebelum\" yang sangat formal. Untuk \"cuci tangan sebelum makan\" sehari-hari, kita tidak memakainya.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Di depan ditaruh <b>peristiwa besar yang resmi dan terencana</b> (rapat, konstruksi, peluncuran, keberangkatan, upacara). Di belakang disebut <b>persiapan, pengumuman, atau acara yang dilakukan sebelum itu</b>. Paling sering muncul di berita, pengumuman, pidato, dan dokumen bisnis.</div><div class='gd-ex-line'>・<span class='gd-jp'>新商品の発売に先立って、記者会見が開かれた。</span>(Sebelum produk baru diluncurkan, diadakan konferensi pers)</div><div class='gd-ex-line'>・<span class='gd-jp'>出発に先立ち、参加者に注意事項が説明された。</span>(Sebelum berangkat, para peserta diberi penjelasan tentang hal-hal yang perlu diperhatikan)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina＋に先立って／に先立ち</b>: yang paling umum. Nominanya biasanya kata seperti 「開会、工事、発売」 yang bisa ditambah する.<br><span class='gd-pair'><span class='gd-jp'>工事</span> → <span class='gd-jp'>工事に先立って</span></span><br><b>Kata kerja bentuk kamus＋に先立って</b>: juga bisa, tapi lebih jarang.<br><span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学するに先立って</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>留学するに先立って、ビザの手続きを済ませた。</span>(Sebelum berangkat studi ke luar negeri, aku menyelesaikan urusan visa terlebih dahulu)</div><div class='gd-sec'>「に先立ち」lebih bersifat tulisan dan lebih kaku daripada 「に先立って」, tapi artinya sama.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>に先立ちまして</span>Ungkapan baku untuk membuka pidato atau upacara, lebih sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>開会に先立ちまして、一言ご挨拶申し上げます。</span>(Sebelum rapat dibuka, izinkan saya menyampaikan sepatah dua kata)</div><div class='gd-sec'><span class='gd-tag'>に先立つ＋nomina</span>Langsung menerangkan nomina di belakangnya, artinya \"~ yang diadakan sebelum ~\".</div><div class='gd-ex-line'>・<span class='gd-jp'>試合に先立つ開会式で、選手代表が宣誓した。</span>(Pada upacara pembukaan sebelum pertandingan, perwakilan atlet mengucapkan sumpah)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Setelah nomina langsung pakai 「に」, jangan tambah の: yang benar <span class='gd-jp'>開会に先立って</span>, bukan 「開会の先立って」。<br>・Kata kerjanya harus bentuk kamus, tidak bisa bentuk た: tidak boleh bilang 「決めたに先立って」。<br>・Bacanya <b>さきだって</b>, bukan せんだって。<br>・Jangan dipakai untuk hal sepele sehari-hari, terdengar berlebihan: \"sikat gigi sebelum tidur\" cukup <span class='gd-jp'>寝る前に歯を磨く</span>. Kalau bilang 「寝るに先立って」, kedengarannya seperti sedang membacakan siaran pers.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>前に</b> = \"sebelum\" biasa, bisa dipakai di situasi apa saja: <span class='gd-jp'>会議の前に、資料を確認しておこう。</span>(Sebelum rapat, yuk cek dulu materinya)<br><b>に先立って</b> = \"demi peristiwa besar itu, sebelumnya ~\" dalam situasi resmi: <span class='gd-jp'>会議に先立ち、資料が配布された。</span>(Sebelum rapat dimulai, materi dibagikan terlebih dahulu)<br><b>際に</b> = \"pada saat ~\", membicarakan saat itu, bukan sebelumnya: <span class='gd-jp'>ご使用の際は、十分ご注意ください。</span>(Harap berhati-hati saat menggunakan)／<span class='gd-jp'>ご使用に先立ち、説明書をお読みください。</span>(Sebelum menggunakan, harap baca buku petunjuk terlebih dahulu)</div><div class='gd-warn'>Trik cepat: untuk \"sebelum\" sehari-hari pakai 前に; untuk situasi resmi \"sebelum acara besar dimulai, lakukan persiapan\" pakai に先立って; untuk \"saat melakukannya\" pakai 際に.</div>","n2-67":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Ketiga pola ini dipakai saat perasaan di hati atau sensasi di tubuh sudah begitu kuat sampai tak tertahankan. Padanannya dalam bahasa Indonesia kira-kira <b>「…banget sampai nggak tahan」「…setengah mati」「nggak bisa berhenti …」</b>. Artinya hampir sama, bedanya terutama di <b>tingkat keformalan</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格の知らせを聞いて、嬉しくてたまらない。</span>（Mendengar kabar lulus, senangnya bukan main）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bagian depan diubah dulu ke bentuk 「て」, lalu disambung dengan <span class='gd-jp'>たまらない</span>／<span class='gd-jp'>ならない</span>／<span class='gd-jp'>しょうがない</span>.<br>Kata kerja: pakai bentuk て　<span class='gd-pair'><span class='gd-jp'>気になる</span> → <span class='gd-jp'>気になってしょうがない</span></span><br>Kata sifat い: ganti 「い」 di akhir dengan 「くて」　<span class='gd-pair'><span class='gd-jp'>嬉しい</span> → <span class='gd-jp'>嬉しくてたまらない</span></span><br>Kata sifat な: tambahkan 「で」 di belakangnya　<span class='gd-pair'><span class='gd-jp'>心配</span> → <span class='gd-jp'>心配でたまらない</span></span><br>Ingin melakukan sesuatu: <span class='gd-jp'>たい</span> juga diganti 「い」 → 「くて」　<span class='gd-pair'><span class='gd-jp'>会いたい</span> → <span class='gd-jp'>会いたくてたまらない</span></span></div><div class='gd-h'>Memilih di antara ketiganya</div><div class='gd-sec'><span class='gd-tag'>たまらない</span>Paling standar. Bisa dipakai untuk perasaan, sensasi tubuh, maupun keinginan, dan cocok untuk percakapan sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>国の家族に会いたくてたまらない。</span>（Kangen banget sama keluarga di kampung halaman）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は暑くてたまらない。</span>（Hari ini panasnya nggak tertahankan）</div><div class='gd-sec'><span class='gd-tag'>しょうがない</span>Paling kasual, paling sering kamu dengar saat ngobrol dengan teman. Versi yang sedikit lebih formal adalah <span class='gd-jp'>しかたがない</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>昨日あまり寝てないから、眠くてしょうがない。</span>（Kemarin kurang tidur, jadi ngantuk setengah mati）</div><div class='gd-sec'><span class='gd-tag'>ならない</span>Cenderung bahasa tulis dan formal, dengan nuansa perasaan itu muncul sendiri di hati terus-menerus. Paling sering berpasangan dengan ungkapan seperti <span class='gd-jp'>気がする</span>, <span class='gd-jp'>思われる</span>, <span class='gd-jp'>思い出される</span>, yaitu ungkapan \"perasaan yang muncul dengan sendirinya\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が何か隠している気がしてならない。</span>（Aku terus merasa dia menyembunyikan sesuatu）</div><div class='gd-ex-line'>・<span class='gd-jp'>故郷のことが思い出されてならない。</span>（Aku tak bisa berhenti teringat kampung halaman）</div><div class='gd-h'>Jebakan yang sering terjadi</div><div class='gd-warn'>・Pola ini untuk perasaan <b>dirimu sendiri</b>. Untuk perasaan orang lain, tambahkan <span class='gd-jp'>ようだ</span> atau <span class='gd-jp'>らしい</span>: <span class='gd-jp'>妹は寂しくてたまらないようだ。</span>（Adikku sepertinya kesepian sekali）<br>・Di depannya hanya boleh perasaan atau emosi, bukan tindakan yang kamu putuskan sendiri. \"Belajar sampai nggak tahan\" tidak bisa dibilang <span class='gd-jp'>勉強してたまらない</span>. Kalau ingin melakukan sesuatu, pakai <span class='gd-jp'>〜たくて</span>.<br>・<span class='gd-jp'>てならない</span> jangan tertukar dengan <span class='gd-jp'>てはならない</span>. Kalau ada tambahan 「は」, artinya jadi \"tidak boleh\": <span class='gd-jp'>嘘をついてはならない。</span>（Tidak boleh berbohong）Sedangkan <span class='gd-jp'>なくてはならない</span> artinya \"harus\".<br>・<span class='gd-jp'>てしょうがない</span> jangan tertukar dengan <span class='gd-jp'>てもしょうがない</span>. Kalau ada tambahan 「も」, artinya jadi \"～pun percuma\": <span class='gd-jp'>今さら後悔してもしょうがない。</span>（Menyesal sekarang pun percuma）<br>・Dalam tulisan formal atau pidato, <span class='gd-jp'>しょうがない</span> terlalu santai. Pakai <span class='gd-jp'>ならない</span> atau <span class='gd-jp'>しかたがない</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Dalam bahasa Indonesia, keduanya sering diterjemahkan jadi \"nggak tahan/tak bisa menahan\", jadi gampang tertukar dengan <b>ずにはいられない</b>.<br><b>てたまらない</b> = perasaan begitu kuat sampai tak tertahankan, fokusnya pada <b>perasaan itu sendiri</b>: <span class='gd-jp'>母の病気が心配でたまらない。</span>（Aku khawatir sekali dengan sakitnya ibu）<br><b>ずにはいられない</b> = tak tahan untuk <b>melakukan suatu tindakan</b>: <span class='gd-jp'>心配で、母に電話せずにはいられなかった。</span>（Saking khawatirnya, aku tak tahan untuk menelepon ibu）</div><div class='gd-warn'>Tips menentukan: kalau yang tak tertahankan adalah \"perasaan\", pakai てたまらない; kalau tak tahan \"melakukan sesuatu\", pakai ずにはいられない.</div>","n2-44":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ものだ」itu seperti bahasa Indonesia <b>「Duh, ternyata begitu ya…」「Dulu tuh ya…」</b>. Pola ini bukan sekadar melaporkan fakta, tapi diucapkan dengan <b>perasaan mendalam tentang hidup</b>, mirip nada orang tua yang melihat foto lama lalu bilang, \"Waktu cepat sekali berlalu ya.\"</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk biasa: <span class='gd-pair'><span class='gd-jp'>変わる</span> → <span class='gd-jp'>変わるものだ</span></span><br>Kata sifat-い: <span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早いものだ</span></span><br>Kata sifat-な harus tetap pakai 「な」: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなものだ</span></span><br>Kalau membicarakan hal di masa lalu, pakai bentuk た: <span class='gd-pair'><span class='gd-jp'>遊んだ</span> → <span class='gd-jp'>遊んだものだ</span></span><br>Dalam percakapan sering disingkat jadi <b>もんだ</b>, dan akhir kalimat sering ditambah <b>なあ</b>: <span class='gd-jp'>早いもんだなあ。</span>Kalau mau lebih sopan, pakai <span class='gd-jp'>ものです</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Renungan hidup</span>Mengungkapkan rasa haru tentang waktu, hidup, dan perubahan.</div><div class='gd-ex-line'>・<span class='gd-jp'>月日がたつのは早いものだ。</span>（Waktu berlalu cepat sekali ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>この町もずいぶん変わったものだ。</span>（Kota ini juga sudah banyak berubah ya）</div><div class='gd-sec'><span class='gd-tag'>Mengenang masa lalu</span>Bentuk た＋ものだ sering muncul bersama 「よく」, untuk menceritakan hal yang <b>dulu sering dilakukan</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃はよくこの川で遊んだものだ。</span>（Waktu kecil dulu aku sering main di sungai ini）</div><div class='gd-ex-line'>・<span class='gd-jp'>学生時代は朝まで友達と話したものだ。</span>（Waktu kuliah dulu aku sering ngobrol sama teman sampai pagi）</div><div class='gd-sec'><span class='gd-tag'>Kagum atau tak habis pikir</span>「よく～たものだ」＝bisa-bisanya ～.</div><div class='gd-ex-line'>・<span class='gd-jp'>よくそんなことが言えたものだ。</span>（Bisa-bisanya kamu ngomong begitu）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Pemakaian untuk mengenang hanya bisa untuk hal yang <b>dulu dilakukan berulang kali</b>. Hal yang terjadi sekali saja tidak bisa: <span class='gd-jp'>去年京都へ行ったものだ</span> itu salah, cukup bilang <span class='gd-jp'>去年京都へ行った</span>.<br>・「よく」punya dua arti: di <span class='gd-jp'>よく遊んだものだ</span>, よく berarti \"sering\"; di <span class='gd-jp'>よく言えたものだ</span>, よく berarti \"bisa-bisanya\". Lihat konteksnya untuk membedakan.<br>・Untuk hal kecil yang ada di depan mata, seperti cuaca panas atau makanan enak, cukup pakai <span class='gd-jp'>暑いなあ</span> atau <span class='gd-jp'>おいしいね</span>. Kalau dipaksa pakai ものだ, kesannya seperti sedang berfilosofi tentang hidup.<br>・Kata sifat-な tidak boleh disambung 「だ」 lalu ものだ. <span class='gd-jp'>静かだものだ</span> itu salah.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ものだ（memang begitu／seharusnya）</b>: membicarakan akal sehat atau aturan umum, tanpa banyak emosi.<br><span class='gd-jp'>年をとると、物忘れが多くなるものだ。</span>（Kalau sudah tua, memang jadi gampang lupa）<br><span class='gd-jp'>人の話は最後まで聞くものだ。</span>（Kalau orang bicara, seharusnya didengarkan sampai selesai）<br><b>ものだ（ungkapan haru）</b>: bentuknya sama, tapi ada perasaan mendalam.<br><span class='gd-jp'>子供が大きくなるのは本当に早いものだ。</span>（Anak cepat besar itu benar-benar cepat ya）<br><b>ものがある</b>: ada sesuatu yang membuatmu <b>merasakan suatu kualitas</b>, dipakai untuk menilai karya, orang, atau penampilan.<br><span class='gd-jp'>彼の歌には人の心を打つものがある。</span>（Lagunya punya sesuatu yang menyentuh hati orang）</div><div class='gd-warn'>Trik cepat: kalau kalimatnya bisa ditambah 「本当に」 atau 「なあ」 dan terasa penuh perasaan, itu ungkapan haru. Kalau bicaranya tenang tentang akal sehat atau aturan, itu \"memang begitu／seharusnya\". Kalau maksudnya \"sesuatu itu punya kesan ～\", itu ものがある.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Lanjutkan ke <span class='gd-jp'>〜ものがある</span>, lalu kembali ulang <span class='gd-jp'>ものだ</span> yang artinya \"memang begitu\". Kalau ketiganya dibandingkan sekaligus, kamu paling kecil kemungkinannya tertukar.</div>","n2-52":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜からすると」itu seperti bahasa Indonesia <b>「dari sudut pandang ～」「kalau dilihat dari ～」</b>. Kalau di depannya ada orang, artinya kamu pindah ke posisi orang itu untuk berpikir. Kalau di depannya ada petunjuk (ekspresi wajah, keadaan, nilai), artinya kamu menyimpulkan berdasarkan petunjuk itu.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋<span class='gd-jp'>からすると</span>／<span class='gd-jp'>からすれば</span>／<span class='gd-jp'>からしたら</span><br>Ketiganya artinya sama, tapi <span class='gd-jp'>からしたら</span> lebih kolokial dan sering terdengar saat ngobrol.<br><span class='gd-pair'><span class='gd-jp'>親</span> → <span class='gd-jp'>親からすると</span></span><span class='gd-pair'><span class='gd-jp'>彼の表情</span> → <span class='gd-jp'>彼の表情からすれば</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dari posisi seseorang</span>Di depannya ada orang atau kelompok, misalnya <span class='gd-jp'>親</span>, <span class='gd-jp'>子供</span>, <span class='gd-jp'>外国人</span>, <span class='gd-jp'>会社</span>. Artinya \"kalau jadi orang itu, akan melihatnya begini\", yang belum tentu sama dengan perasaanmu sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>親からすると、子供の将来を心配するのは自然なことだ。</span>（Dari sudut pandang orang tua, mengkhawatirkan masa depan anak itu hal yang wajar）</div><div class='gd-ex-line'>・<span class='gd-jp'>子供からしたら、大人の話はつまらないだろう。</span>（Dari sudut pandang anak-anak, obrolan orang dewasa mungkin membosankan）</div><div class='gd-ex-line'>・<span class='gd-jp'>外国人からすれば、敬語はかなり難しい。</span>（Dari sudut pandang orang asing, bahasa sopan itu cukup sulit）</div><div class='gd-sec'><span class='gd-tag'>Menyimpulkan dari petunjuk</span>Di depannya ada petunjuk yang bisa dilihat, misalnya <span class='gd-jp'>表情</span>, <span class='gd-jp'>様子</span>, <span class='gd-jp'>話し方</span>, <span class='gd-jp'>成績</span>. Akhir kalimat sering memakai <span class='gd-jp'>ようだ</span>, <span class='gd-jp'>らしい</span>, <span class='gd-jp'>はずだ</span>, <span class='gd-jp'>だろう</span>, yang berarti \"ini dugaanku\".</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の表情からすると、何か隠しているようだ。</span>（Dilihat dari ekspresinya, sepertinya dia menyembunyikan sesuatu）</div><div class='gd-ex-line'>・<span class='gd-jp'>この成績からすれば、合格できるはずだ。</span>（Dilihat dari nilai ini, seharusnya bisa lulus）</div><div class='gd-ex-line'>・<span class='gd-jp'>空の様子からすると、午後は雨になりそうだ。</span>（Dilihat dari keadaan langit, sepertinya sore nanti akan hujan）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・「から」di sini <b>bukan \"karena\"</b>. <span class='gd-jp'>親からすると</span> bukan \"karena orang tua\", tapi \"dilihat dari pihak orang tua\". Jangan juga dicampur dengan <span class='gd-jp'>からには</span> (karena sudah ～ maka ～) atau <span class='gd-jp'>からこそ</span> (justru karena ～).<br>・Di depannya hanya bisa <b>kata benda</b>. Kalau mau memakai suatu tindakan sebagai petunjuk, ubah dulu jadi kata benda, misalnya <span class='gd-jp'>彼の話し方からすると</span>. Tidak bisa langsung bilang 「話すからすると」.<br>・<span class='gd-jp'>すれば</span> dan <span class='gd-jp'>したら</span> mirip \"kalau ～\", tapi di sini <b>tidak ada makna pengandaian</b>. Ketiganya sama-sama berarti \"kalau dilihat dari ～\".<br>・Bagian belakang kalimat berisi <b>pendapat atau penilaian</b>. Tidak dipakai dengan kalimat keputusan atau permintaan seperti 「aku akan ～」 atau 「tolong ～」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b><span class='gd-jp'>にとって</span></b>＝<b>apa arti hal ini bagi seseorang</b>, di belakangnya sering ada kata penilaian (<span class='gd-jp'>大切</span>, <span class='gd-jp'>ありがたい</span>, <span class='gd-jp'>難しい</span>).</div><div class='gd-ex-line'>・<span class='gd-jp'>子供にとって、親は一番大切な存在だ。</span>（Bagi anak, orang tua adalah sosok yang paling penting）</div><div class='gd-sec'><b><span class='gd-jp'>からすると</span></b>＝pindah ke posisi orang itu dan membicarakan <b>bagaimana dia akan melihat dan memikirkannya</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供からすると、親の注意はうるさいだけだろう。</span>（Dari sudut pandang anak, nasihat orang tua mungkin cuma terasa cerewet）</div><div class='gd-sec'>Selain itu, pemakaian \"menyimpulkan dari petunjuk\" tidak bisa diganti dengan <span class='gd-jp'>にとって</span>. Tidak ada ungkapan 「<span class='gd-jp'>表情にとって</span>」 (dalam kasus ini bisa pakai <span class='gd-jp'>からすると</span> atau <span class='gd-jp'>から見ると</span>).<br><br><b><span class='gd-jp'>から見ると</span></b>＝sebagian besar bisa saling menggantikan dengan <span class='gd-jp'>からすると</span>, baik untuk \"dari posisi seseorang\" maupun \"menyimpulkan dari petunjuk\".</div><div class='gd-ex-line'>・<span class='gd-jp'>あの様子から見ると、何かあったらしい。</span>（Dilihat dari keadaannya, sepertinya telah terjadi sesuatu）</div><div class='gd-warn'>Trik cepat: untuk \"nilai atau pengaruh hal ini bagi seseorang\", pakai <span class='gd-jp'>にとって</span>. Untuk \"kalau jadi orang itu, bagaimana pikirannya\" atau \"menyimpulkan dari petunjuk\", pakai <span class='gd-jp'>からすると</span>, dan biasanya bisa diganti dengan <span class='gd-jp'>から見ると</span>.</div>","n2-30":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜だけのことはある」kira-kira berarti <b>“pantas saja ~”, “memang pantas ~”, “tidak sia-sia ~”</b>. Kamu melihat hasil yang hebat, lalu menoleh ke belakang dan bilang: “Hmm, ini cocok sekali dengan statusnya, uang yang dikeluarkan, dan usahanya.” Jadi, <b>namanya memang bukan isapan jempol</b>.</div><div class='gd-sec'><span class='gd-jp'>だけ</span> di sini bukan “hanya”. Kesan kalimatnya: “Dia kan ～, dengan status itu wajar kalau kemampuannya memang segitu. Benar kan.”</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Status yang sesuai reputasi</span>Penampilan ahli, toko terkenal, atau orang terkenal sama bagusnya dengan namanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>さすがプロだけのことはある。</span>（Pantas saja, dia memang profesional）</div><div class='gd-ex-line'>・<span class='gd-jp'>英語がペラペラだ。5年もアメリカに住んでいただけのことはある。</span>（Bahasa Inggrisnya lancar sekali. Pantas saja, dia tinggal di Amerika selama lima tahun）</div><div class='gd-sec'><span class='gd-tag'>Uang yang dikeluarkan terasa sepadan</span>Seperti ungkapan “ada harga, ada kualitas”.</div><div class='gd-ex-line'>・<span class='gd-jp'>このいす、全然疲れない。高かっただけのことはある。</span>（Kursi ini selama apa pun diduduki tidak bikin capek. Memang pantas mahal）</div><div class='gd-sec'><span class='gd-tag'>Pantas saja populer</span>Setelah mencoba sendiri, kamu merasa penilaian orang-orang memang benar.</div><div class='gd-ex-line'>・<span class='gd-jp'>このパン、本当においしい。行列ができるだけのことはあるね。</span>（Roti ini enak banget. Pantas saja antreannya panjang）</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Kata kerja</b>: bentuk biasa langsung disambung　<span class='gd-pair'><span class='gd-jp'>練習した</span> → <span class='gd-jp'>練習しただけのことはある</span></span><br><b>Kata sifat-い</b>: langsung disambung　<span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いだけのことはある</span></span><br><b>Kata sifat-な</b>: 「な」 harus dipertahankan　<span class='gd-pair'><span class='gd-jp'>有名</span> → <span class='gd-jp'>有名なだけのことはある</span></span><br><b>Kata benda</b>: langsung disambung, tanpa だ　<span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロだけのことはある</span></span><br>Kalau mau lebih sopan, katakan <span class='gd-jp'>だけのことはありますね</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Di depannya sering ada <span class='gd-jp'>さすが</span>. Kalau dipakai bersama, nuansa “pantas saja” makin kuat. Urutan yang sering muncul: <b>sebutkan dulu hasil yang kamu lihat, lalu tambahkan だけのことはある</b> sebagai kesimpulan.</div><div class='gd-ex-line'>・<span class='gd-jp'>景色が最高だ。さすが有名なだけのことはある。</span>（Pemandangannya luar biasa. Pantas saja terkenal）</div><div class='gd-sec'>Untuk hal yang hasilnya sudah keluar, kamu juga bisa pakai bentuk lampau「あった」. Ini sering dipakai untuk bilang usaha membuahkan hasil.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できた。毎日勉強しただけのことはあった。</span>（Aku lulus. Belajar tiap hari ternyata tidak sia-sia）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kalau kamu lihat <span class='gd-jp'>だけ</span> lalu menerjemahkannya “hanya”, seluruh kalimat jadi tidak masuk akal. Di sini artinya “pantas saja, memang sesuai namanya”.<br>・Jangan tambahkan だ setelah kata benda: yang benar <span class='gd-jp'>プロだけのことはある</span>, bukan プロだだけのことはある.<br>・Kata sifat-な harus mempertahankan 「な」: yang benar <span class='gd-jp'>有名なだけのことはある</span>, bukan 有名だけのことはある.<br>・Harus ada <b>hasil yang benar-benar kamu lihat</b> sebagai bukti. Kalau hal itu belum terjadi dan baru dugaan, tidak bisa dipakai.<br>・Untuk pemula, ingat dulu: ini ungkapan <b>pujian dan persetujuan</b>. Kalau mau mengeluh barangnya jelek, jangan pakai ini.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>だけあって</b>: artinya sama, “pantas saja”, tetapi diletakkan <b>di tengah kalimat</b>, langsung disambung hasilnya, jadi selesai dalam satu kalimat.<br>・<span class='gd-jp'>さすがプロだけあって、写真がきれいだ。</span>（Pantas saja profesional, fotonya bagus）<br><b>だけのことはある</b>: diletakkan <b>di akhir kalimat</b> sebagai kesimpulan.<br>・<span class='gd-jp'>写真がきれいだ。さすがプロだけのことはある。</span>（Fotonya bagus sekali. Pantas saja, dia profesional）</div><div class='gd-sec'><b>ことだから</b>: sama-sama berkaitan dengan sifat atau kemampuan seseorang, tetapi ini <b>dugaan sebelum hasilnya keluar</b>. Cara menyambungnya: kata benda＋の＋ことだから.<br>・<span class='gd-jp'>田中さんのことだから、きっと今回も合格するよ。</span>（Kalau Tanaka sih, pasti kali ini juga lulus）<br>・<span class='gd-jp'>一回で合格した。さすが田中さんだけのことはある。</span>（Sekali coba langsung lulus. Pantas saja, dia Tanaka）</div><div class='gd-warn'>Trik membedakan: kalau hasilnya belum keluar dan kamu baru menebak, pakai ことだから. Kalau hasilnya sudah keluar dan kamu kagum, pakai だけのことはある. Kalau mau langsung menyambung hasilnya dalam satu kalimat, ganti ke だけあって.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'><span class='gd-jp'>〜に値する</span> (layak ～) juga memberi penilaian positif, misalnya <span class='gd-jp'>この映画は見るに値する。</span>（Film ini layak ditonton）.</div>","n2-42":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に決まっている」kira-kira berarti <b>“pasti ~ lah, sudah jelas”</b>. Si pembicara sudah yakin di dalam hatinya, nadanya tegas, dan ada kesan “ya iyalah, masih perlu dibilang?”</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'><b>Kata kerja, kata sifat-い</b>: langsung disambung, bentuk lampau dan negatif juga boleh.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くに決まっている</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いに決まっている</span></span><span class='gd-pair'><span class='gd-jp'>忘れた</span> → <span class='gd-jp'>忘れたに決まっている</span></span></div><div class='gd-sec'><b>Kata benda, kata sifat-な</b>: <b>jangan tambahkan だ</b>, langsung sambung に.<br><span class='gd-pair'><span class='gd-jp'>嘘</span> → <span class='gd-jp'>嘘に決まっている</span></span><span class='gd-pair'><span class='gd-jp'>無理</span> → <span class='gd-jp'>無理に決まっている</span></span></div><div class='gd-sec'>Saat ngobrol sering disingkat jadi <span class='gd-jp'>〜に決まってる</span>; versi yang agak sopan: <span class='gd-jp'>〜に決まっています</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sudah pasti, tak perlu dipikir</span>Tanpa bukti pun, kamu yakin memang begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな時間に電話なんて、急用に決まってる。</span>（Telepon jam segini, pasti ada urusan mendesak）</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなに安いのは偽物に決まってるよ。</span>（Semurah itu, pasti barang palsu lah）</div><div class='gd-sec'><span class='gd-tag'>Ya iyalah</span>Lawan bicara menanyakan hal yang sudah jelas, dan kamu jawab “ya jelas dong”.</div><div class='gd-ex-line'>・<span class='gd-jp'>「一緒に行く？」「行くに決まってるじゃん！」</span>（“Mau pergi bareng?” “Ya jelas mau dong!”）</div><div class='gd-ex-line'>・<span class='gd-jp'>10時間も歩いたんだから、疲れたに決まってるでしょ。</span>（Jalan sampai 10 jam, ya jelas capek lah）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Jangan tambahkan だ setelah kata benda dan kata sifat-な: <span class='gd-jp'>嘘だに決まっている</span> itu salah, yang benar <span class='gd-jp'>嘘に決まっている</span>.<br>・Ini <b>keyakinan subjektif si pembicara</b> dengan nada yang kuat. Kalau dipakai ke atasan atau pelanggan, 「〜に決まっています」 mudah terdengar memaksa, bahkan seperti menyerang. Dalam tulisan formal atau laporan juga jarang dipakai.<br>・Kata “pasti” dalam bahasa Indonesia kadang bisa berarti “harus” (misalnya “besok pasti datang ya”), tetapi に決まっている <b>tidak punya arti itu</b>. Untuk bilang “besok kamu harus datang”, pakai <span class='gd-jp'>明日は必ず来てください</span>.<br>・<span class='gd-jp'>決まっている</span> aslinya berarti “sudah diputuskan”. Jadi kadang artinya memang harfiah: <span class='gd-jp'>会議は月曜日に決まっている。</span>（Rapatnya sudah ditetapkan hari Senin）Lihat konteksnya untuk menilai.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Situasinya sama: temanmu sampai sekarang belum datang.<br><b>に違いない</b> = dugaan yang ada dasarnya, nadanya lebih tenang, bisa dipakai dalam percakapan maupun tulisan:<br><span class='gd-jp'>道が混んでいるに違いない。</span>（Pasti jalanan macet）<br><b>に決まっている</b> = lebih subjektif dan emosinya lebih kuat, hampir hanya dipakai saat ngobrol:<br><span class='gd-jp'>道が混んでいるに決まってるよ。</span>（Pasti macet lah, sudah jelas）<br><b>に相違ない</b> = artinya sama dengan に違いない, tetapi kaku dan lebih sering muncul di tulisan atau novel:<br><span class='gd-jp'>道が混んでいるに相違ない。</span>（Pasti lalu lintas sedang padat）<br>Arah sebaliknya adalah <b>っこない</b> = “mustahil lah ~”, sama-sama lisan dan subjektif:<br><span class='gd-jp'>あの人が時間通りに来っこないよ。</span>（Mustahil dia datang tepat waktu lah）</div><div class='gd-warn'>Trik membedakan: untuk penalaran yang tenang, pakai に違いない; untuk tulisan, pakai に相違ない; kalau nadanya “sudah jelas” atau “ya iyalah”, pakai に決まっている. Kalau mau bilang “mustahil”, pakai っこない.</div>","n2-53":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にかけては」artinya <b>「kalau soal ～, (orang itu) hebat banget」</b>. Pertama kamu sebut satu bidang, misalnya masak, matematika, atau penjualan, lalu di belakangnya ada pujian seperti 「tidak ada yang bisa menandingi」 atau 「tidak kalah dari siapa pun」. Inti kalimatnya: <b>orang itu sangat jago di bidang tersebut</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata benda＋にかけては<br><span class='gd-pair'><span class='gd-jp'>料理</span> → <span class='gd-jp'>料理にかけては</span></span>(kalau soal masak)<br>Kalau yang mau kamu bicarakan adalah suatu kegiatan, tambahkan 「こと」 dulu supaya jadi kata benda:<br><span class='gd-pair'><span class='gd-jp'>走る</span> → <span class='gd-jp'>走ることにかけては</span></span>(kalau soal berlari)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Memuji orang lain</span>Di belakangnya paling sering muncul 「<span class='gd-jp'>右に出る者はいない</span>」(tidak ada yang melebihi dia) dan 「<span class='gd-jp'>かなう人はいない</span>」(tidak ada yang bisa menandingi).</div><div class='gd-ex-line'>・<span class='gd-jp'>和食にかけては、彼女の右に出る者はいない。</span>(Kalau soal masakan Jepang, tidak ada yang bisa melebihi dia)</div><div class='gd-ex-line'>・<span class='gd-jp'>営業にかけては、彼が社内一だ。</span>(Kalau soal penjualan, dia nomor satu di seluruh perusahaan)</div><div class='gd-sec'><span class='gd-tag'>Membicarakan diri sendiri</span>Di belakangnya dipakai 「<span class='gd-jp'>誰にも負けない</span>」(tidak kalah dari siapa pun) atau 「<span class='gd-jp'>自信がある</span>」(percaya diri).</div><div class='gd-ex-line'>・<span class='gd-jp'>記憶力にかけては、誰にも負けない。</span>(Kalau soal daya ingat, aku tidak kalah dari siapa pun)</div><div class='gd-ex-line'>・<span class='gd-jp'>人の名前を覚えることにかけては、自信がある。</span>(Kalau soal mengingat nama orang, aku percaya diri)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depannya harus ada <b>suatu keahlian atau bidang yang dikuasai</b>, dan di belakangnya harus ada <b>penilaian bahwa kemampuannya hebat</b>. Topik yang tidak ada hubungannya dengan kemampuan, seperti 「<span class='gd-jp'>日本の天気にかけては</span>」, tidak bisa dipakai.<br>・Kalau dipakai untuk kekurangan, misalnya 「kalau soal cari-cari alasan, dia jagonya」, nuansanya jadi sindiran atau bercanda, bukan pujian yang tulus.<br>・Jangan lupa 「は」. Tanpa は jadi 「にかけて」, yang dianggap tata bahasa lain untuk menyatakan rentang waktu atau tempat.<br>・Ungkapan ini cukup formal, cocok untuk memperkenalkan orang atau menulis karangan. Saat ngobrol dengan teman, lebih sering dipakai 「<span class='gd-jp'>料理なら誰にも負けない</span>」(kalau soal masak, aku tidak kalah dari siapa pun).</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にかけて</b>(tanpa は) = <b>rentang</b> dari mana sampai mana, di depannya waktu atau tempat:<br><div class='gd-ex-line'>・<span class='gd-jp'>今夜から明日の朝にかけて、雨が降るでしょう。</span>(Dari malam ini sampai besok pagi akan turun hujan)</div><b>にかけては</b> = kalau soal suatu <b>keahlian</b>:<br><div class='gd-ex-line'>・<span class='gd-jp'>数学にかけては、クラスで彼に勝てる人はいない。</span>(Kalau soal matematika, tidak ada yang bisa mengalahkan dia di kelas)</div></div><div class='gd-sec'><b>に関しては</b> = sekadar 「mengenai ～」, hanya menyebut topik, jadi di belakangnya boleh apa saja:<br><div class='gd-ex-line'>・<span class='gd-jp'>料理に関しては、母に聞いてください。</span>(Soal masak, tanya ibuku saja ya)</div><b>にかけては</b> = di belakangnya pasti memuji kemampuan di bidang itu:<br><div class='gd-ex-line'>・<span class='gd-jp'>料理にかけては、母にかなう人はいない。</span>(Kalau soal masak, tidak ada yang bisa menandingi ibuku)</div></div><div class='gd-warn'>Tips membedakan: kalau di depannya waktu atau tempat, pakai にかけて. Kalau hanya menyebut topik, pakai に関しては. Kalau mau bilang 「di bidang ini dialah yang terhebat」, baru pakai にかけては.</div>","n2-55":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にしろ／〜にせよ」artinya <b>「baik A maupun B, tetap ～」</b> atau <b>「biarpun ～, tetap ～」</b>. Di depan kamu lempar beberapa kemungkinan, lalu di belakang kamu sampaikan kesimpulan atau pendapat yang <b>tidak berubah karena itu</b>. Maknanya sama, tapi <span class='gd-jp'>にせよ</span> lebih formal dan lebih sering muncul di tulisan dan situasi resmi.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Baik A maupun B</span>Kamu taruh dua (atau beberapa) pilihan berdampingan, dan mana pun yang dipilih, kesimpulannya sama. Ini bentuk yang paling umum.</div><div class='gd-ex-line'>・<span class='gd-jp'>行くにしろ行かないにしろ、早めに連絡してください。</span>(Pergi atau tidak, tolong kabari lebih awal)</div><div class='gd-ex-line'>・<span class='gd-jp'>肉にせよ魚にせよ、新鮮なものを選びたい。</span>(Baik daging maupun ikan, aku ingin memilih yang segar)</div><div class='gd-sec'><span class='gd-tag'>Apa pun</span>Di depannya ditaruh kata tanya seperti 「何」「どちら」「誰」, artinya 「yang mana pun sama saja」.</div><div class='gd-ex-line'>・<span class='gd-jp'>何をするにしろ、健康が一番大事だ。</span>(Apa pun yang kamu lakukan, kesehatan yang paling penting)</div><div class='gd-ex-line'>・<span class='gd-jp'>いずれにせよ、一度会って話しましょう。</span>(Bagaimanapun, ayo ketemu dan bicara dulu)</div><div class='gd-sec'><span class='gd-jp'>いずれにせよ</span> dan <span class='gd-jp'>どっちにしろ</span> hampir sudah jadi ungkapan baku yang artinya 「pokoknya, bagaimanapun juga」. Sering terdengar di rapat maupun obrolan sehari-hari.</div><div class='gd-sec'><span class='gd-tag'>Biarpun ～</span>Hanya satu keadaan yang disebut, artinya 「biarpun memang begitu, tetap ～」, sering dengan nada kurang setuju atau mengingatkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>冗談にしろ、そんなことを言うべきではない。</span>(Biarpun bercanda, tidak seharusnya bilang hal seperti itu)</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいにせよ、電話ぐらいできたはずだ。</span>(Sesibuk apa pun, harusnya masih bisa menelepon sebentar)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat-い</b>: pakai bentuk biasa (yaitu bentuk tanpa ます; positif, negatif, dan lampau semua bisa), langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くにしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないにしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いにせよ</span></span></div><div class='gd-sec'><b>Kata benda, kata sifat-な</b>: langsung disambung, atau tambahkan 「である」 dulu (lebih formal). <b>Jangan taruh だ di tengah</b>.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生にしろ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便にせよ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → <span class='gd-jp'>不便であるにせよ</span></span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata benda atau kata sifat-な, <b>jangan tambahkan だ</b>: <span class='gd-jp'>学生だにしろ</span> dan <span class='gd-jp'>不便だにせよ</span> itu salah.<br>・Pada pola 「AにしろBにしろ」, A dan B harus sejenis dan setara: <span class='gd-jp'>賛成にしろ反対にしろ</span>, <span class='gd-jp'>行くにしろ行かないにしろ</span>.<br>・Bagian belakangnya biasanya berisi <b>pendapat, permintaan, atau saran</b> kamu, seperti <span class='gd-jp'>べきだ</span>, <span class='gd-jp'>てください</span>, <span class='gd-jp'>ほうがいい</span>.<br>・<span class='gd-jp'>しろ</span> dan <span class='gd-jp'>せよ</span> aslinya bentuk perintah dari <span class='gd-jp'>する</span>, tapi di sini <b>sama sekali tidak bermakna perintah</b>. <span class='gd-jp'>勉強しろ</span> artinya 「belajar sana!」, sedangkan <span class='gd-jp'>勉強にしろ遊びにしろ</span> artinya 「baik belajar maupun main」. Bedanya ada di 「に」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にしても</b>: artinya hampir sama dengan にしろ dan にせよ, bedanya di tingkat formalitas.<br>・<span class='gd-jp'>行くにしても行かないにしても、連絡してね。</span>(Pergi atau tidak, kabari aku ya: antarteman)<br>・<span class='gd-jp'>出席されるにせよされないにせよ、ご連絡ください。</span>(Hadir maupun tidak, mohon kabari kami: pemberitahuan resmi)<br>Dari yang santai ke yang formal kurang lebih: <span class='gd-jp'>にしても</span> → <span class='gd-jp'>にしろ</span> → <span class='gd-jp'>にせよ</span>.</div><div class='gd-sec'><b>を問わず</b>: 「tidak memandang, tanpa membedakan」. Di depannya hanya kata benda, sering berupa cakupan menyeluruh seperti 「年齢」「男女」, dipakai di peraturan dan iklan lowongan kerja.<br>・<span class='gd-jp'>年齢を問わず、誰でも参加できます。</span>(Tanpa batasan usia, siapa pun boleh ikut)<br>・<span class='gd-jp'>大人にしろ子どもにしろ、参加費は同じだ。</span>(Baik dewasa maupun anak-anak, biaya partisipasinya sama)</div><div class='gd-warn'>Tips membedakan: untuk menyatakan cakupan syarat 「tanpa batas ～」, pakai を問わず. Kalau kamu menyebutkan pilihan-pilihan satu per satu lalu menarik kesimpulan, pakai にしろ・にせよ. Saat ngobrol dengan teman, にしても paling natural; untuk tulisan dan situasi formal, pakai にせよ.</div>","n2-28":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「AはもちろんBも」artinya <b>\"A tak perlu dibicarakan lagi, bahkan B juga ～\"</b>. A adalah hal yang semua orang pasti sudah terpikir dan memang sewajarnya, sedangkan B adalah tambahan yang kurang terduga.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は味はもちろん、サービスもいい。</span>（Rasa di toko ini tak perlu ditanya lagi, pelayanannya pun bagus）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Pada dasarnya, tambahkan 「はもちろん」 langsung setelah kata benda. Di belakangnya biasanya ada <b>も</b> atau <b>まで</b> sebagai pasangannya:<br><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供はもちろん、大人も</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>子供はもちろん、大人も楽しめる映画です。</span>（Film yang tentu saja bisa dinikmati anak-anak, dan orang dewasa pun bisa menikmatinya）</div><div class='gd-ex-line'>・<span class='gd-jp'>家具はもちろん、家電までついている部屋だ。</span>（Kamar yang perabotnya sudah pasti ada, bahkan peralatan elektroniknya pun disediakan）</div><div class='gd-sec'>Kalau setelah kata benda ada partikel kecil seperti 「で」「に」, biarkan saja di tempatnya, lalu tambahkan 「はもちろん」:</div><div class='gd-ex-line'>・<span class='gd-jp'>日本ではもちろん、海外でも人気がある。</span>（Di Jepang tentu saja, di luar negeri pun populer）</div><div class='gd-sec'>Kalau ingin memasukkan tindakan, tambahkan 「の」 setelah verba agar menjadi kata benda:</div><div class='gd-ex-line'>・<span class='gd-jp'>話すのはもちろん、書くのも得意だ。</span>（Berbicara sudah pasti, menulis pun dia jago）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>Jangan terbalik urutannya</b>: taruh di depan hal yang \"memang sudah sewajarnya\". Orang pasti lebih dulu terpikir anak-anak, jadi <span class='gd-jp'>子供はもちろん、大人も</span> terdengar lebih natural.<br>・<b>Kalau akhir kalimat negatif, taruh yang \"sulit\" di depan</b>: <span class='gd-jp'>漢字はもちろん、ひらがなも書けない。</span>（Kanji sudah pasti tidak bisa, bahkan hiragana pun tidak bisa menulis）Tidak bisa menulis kanji itu wajar, yang jadi poin adalah hiragana yang mudah pun tidak bisa.<br>・Jangan lupa menambahkan <b>も</b> atau <b>まで</b> di belakang. Kalau <span class='gd-jp'>英語はもちろん、スペイン語が話せる</span> tanpa も, kedengarannya janggal.<br>・Ini berbeda dengan 「もちろん」 yang berdiri sendiri (tentu saja): <span class='gd-jp'>もちろん行きます</span> artinya \"tentu saja aku akan pergi\", tidak ada makna \"A tak perlu dibicarakan, bahkan B juga\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Ketiganya bisa diterjemahkan jadi \"tidak hanya A, B juga ～\". Mari bandingkan dengan kalimat yang sama:<br><b>はもちろん</b> = A memang sudah sewajarnya: <span class='gd-jp'>彼は英語はもちろん、中国語も話せる。</span>（Bahasa Inggris sudah pasti, bahasa Mandarin pun dia bisa）<br><b>ばかりか</b> = fokusnya pada B yang agak mengejutkan: <span class='gd-jp'>彼は英語ばかりか、中国語も話せる。</span>（Dia tidak hanya bisa bahasa Inggris, bahkan bahasa Mandarin pun bisa）<br><b>のみならず</b> = maknanya hampir sama dengan ばかりか, tapi sangat formal, kebanyakan dipakai dalam tulisan atau pidato: <span class='gd-jp'>彼は英語のみならず、中国語も話せる。</span></div><div class='gd-sec'>Ada satu perbedaan praktis lagi: setelah <b>はもちろん</b> boleh diikuti permintaan atau keputusan seperti \"tolong ～\" atau \"aku akan ～\", sedangkan <b>ばかりか</b> kurang cocok dipakai begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>準備はもちろん、片付けも手伝ってください。</span>（Persiapan sudah pasti, tolong bantu juga membereskannya）</div><div class='gd-warn'>Trik cepat: kalau mau bilang \"A tak perlu dibahas\", pakai はもちろん; kalau mau menekankan \"bahkan B, wah mengejutkan\", pakai ばかりか; のみならず hanya untuk tulisan formal.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜はもちろんのこと」maknanya sama, hanya nadanya sedikit lebih menekankan. Dalam tulisan, kamu juga sering menemukan bentuk yang lebih formal, yaitu <span class='gd-jp'>〜はもとより</span>: <span class='gd-jp'>国内はもとより、海外からも注文が来る。</span>（Dalam negeri tak perlu dibicarakan lagi, bahkan dari luar negeri pun ada pesanan）</div>","n2-56":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にほかならない」setara dengan <b>“tak lain adalah ～”, “justru ～”, “pada dasarnya ya ～ itu sendiri”</b>. Si pembicara menyimpulkan dengan sangat yakin: jawabannya ya ini, <b>bukan yang lain</b>.<br>「ほか」artinya “lain”, jadi 「ほかならない」secara harfiah berarti “tidak mungkin yang lain”. Dari situ muncul arti “tak lain adalah”. Nuansanya tegas dan kaku, jadi paling sering muncul di artikel, pidato, dan komentar berita.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menegaskan hakikat</span>“A pada dasarnya adalah B”, untuk membuka wajah asli dari suatu hal.</div><div class='gd-ex-line'>・<span class='gd-jp'>この結果は、皆さんの協力の成果にほかならない。</span>（Hasil ini tak lain adalah buah kerja sama kalian semua）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の説明は、言い訳にほかならない。</span>（Penjelasannya itu pada dasarnya hanyalah alasan yang dibuat-buat）</div><div class='gd-sec'><span class='gd-tag'>Menegaskan penyebab</span>Pakai pola 「〜のは、〜からにほかならない」, artinya “alasan kenapa ～ tak lain adalah karena ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼が合格できたのは、毎日努力したからにほかならない。</span>（Alasan dia bisa lulus tak lain adalah karena dia berusaha setiap hari）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故が起きたのは、安全確認を怠ったからにほかならない。</span>（Kecelakaan itu terjadi tak lain karena pemeriksaan keselamatan diabaikan）</div><div class='gd-h'>Cara menyambungkan</div><div class='gd-sec'><b>Kata benda</b>: sambung langsung. <span class='gd-pair'><span class='gd-jp'>努力の結果</span> → <span class='gd-jp'>努力の結果にほかならない</span></span><br><b>Menyatakan alasan</b>: pada bentuk biasa, tambahkan 「から」 dulu, baru sambung. <span class='gd-pair'><span class='gd-jp'>努力した</span> → <span class='gd-jp'>努力したからにほかならない</span></span><br><b>Menyatakan hakikat sebuah tindakan</b>: tambahkan 「こと」 pada bentuk kamus kata kerja untuk menjadikannya kata benda, lalu sambung. <span class='gd-pair'><span class='gd-jp'>逃げる</span> → <span class='gd-jp'>逃げることにほかならない</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>何もしないのは、問題から逃げることにほかならない。</span>（Tidak melakukan apa-apa itu pada dasarnya sama saja dengan lari dari masalah）</div><div class='gd-sec'>Dalam pidato atau situasi formal, pakai bentuk sopan: <b>にほかなりません</b>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Jangan mengira 「ならない」 di sini berarti negasi atau “tidak boleh”. Ini adalah <b>penegasan yang sangat kuat</b>: “tak lain adalah”.<br>・Kata kerja tidak bisa langsung disambung: bilang <span class='gd-jp'>遅れたからにほかならない</span>, bukan 遅れたにほかならない.<br>・Kalau bagian depannya 「〜のは」 yang menanyakan “kenapa bisa begini”, lebih natural diakhiri dengan 「〜からにほかならない」 atau 「〜のおかげにほかならない」. Kalau langsung ditaruh kata benda, kalimatnya gampang jadi tidak nyambung.<br>・Kalau dipakai ngobrol dengan teman, kedengarannya seperti sedang membacakan skripsi. Untuk percakapan, cukup pakai 「〜からだよ」 atau 「まさに〜だ」.<br>・Ini adalah pernyataan tegas, bukan dugaan. Jangan dipakai untuk hal yang kamu sendiri belum yakin.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>にすぎない</b> = “hanya ～ saja”, dengan nuansa <b>meremehkan</b>.<br><span class='gd-jp'>彼の成功は運がよかったからにすぎない。</span>（Dia sukses hanya karena kebetulan beruntung）<br><span class='gd-jp'>彼の成功は努力の結果にほかならない。</span>（Kesuksesannya tak lain adalah hasil kerja kerasnya）<br>Keduanya terlihat mirip, tapi yang satu merendahkan, yang satu menarik kesimpulan.</div><div class='gd-sec'><b>からこそ</b> = menekankan “<b>justru karena</b> alasan ini, hasil ini terjadi”. Bisa diletakkan di tengah kalimat, atau di akhir kalimat dengan pola 「〜のは〜からこそだ」. Pola ini juga sering dipakai dalam percakapan dan biasanya membawa perasaan.<br><span class='gd-jp'>努力したからこそ、合格できた。</span>（Justru karena sudah berusaha, aku bisa lulus）<br><span class='gd-jp'>合格できたのは、努力したからこそだ。</span>（Bisa lulus itu justru karena sudah berusaha）<br><span class='gd-jp'>合格できたのは、努力したからにほかならない。</span>（Bisa lulus itu tak lain karena berusaha）<br>Dua kalimat terakhir artinya hampir sama, bedanya ada di nuansa: からこそ <b>menekankan alasan itu</b>; にほかならない <b>menegaskan “bukan yang lain”</b>, lebih kaku dan lebih tulisan, seperti menarik kesimpulan dalam sebuah laporan.</div><div class='gd-warn'>Tips memilih: kalau maksudmu “cuma ～ saja” dengan sedikit nada meremehkan, pakai にすぎない; kalau ingin menekankan “justru karena ～ maka …”, pakai からこそ; kalau ingin menyimpulkan dengan sangat yakin “bukan yang lain, melainkan ～”, pakai にほかならない.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Masih sama-sama bernada yakin, kamu bisa membandingkan dengan <span class='gd-jp'>〜に違いない</span> dan <span class='gd-jp'>〜に相違ない</span>: keduanya adalah dugaan kuat “pasti ～”, sedangkan にほかならない langsung menyimpulkan “ya ～ itu”.</div>"});
